                  AND NOT rolsuper
                  AND NOT rolcreatedb
                  AND NOT rolcreaterole
                  AND NOT rolreplication
                  AND NOT rolbypassrls
            ) THEN
                RAISE EXCEPTION 'COMPAT_REGION_INGEST_ROLE_INVALID';
            END IF;
        END
