CREATE TABLE public.lesson_source_region_backfill_manifest (
    course_id VARCHAR(128) NOT NULL,
    source_region VARCHAR(8) NOT NULL,
    evidence_kind VARCHAR(40) NOT NULL,
    evidence_ref TEXT NOT NULL,
    evidence_sha256 VARCHAR(64) NOT NULL,
    approved_by VARCHAR(128) NOT NULL,
    approved_at TIMESTAMP WITH TIME ZONE NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT pk_lesson_source_region_backfill_manifest PRIMARY KEY (course_id),
    CONSTRAINT ck_lesson_region_manifest_region CHECK (source_region IN ('dom','ovs')),
    CONSTRAINT ck_lesson_region_manifest_evidence_kind CHECK (evidence_kind IN ('SOURCE_APPOINT_SNAPSHOT','DTS_LEDGER','MANUAL_VERIFIED')),
    CONSTRAINT ck_lesson_region_manifest_evidence CHECK (btrim(evidence_ref) <> '' AND evidence_sha256 ~ '^[0-9a-f]{64}$' AND btrim(approved_by) <> '')
);

CREATE TABLE public.lesson_source_region_migration_control (
    control_id VARCHAR(16) NOT NULL,
    phase VARCHAR(24) NOT NULL,
    writer_contract_version VARCHAR(64),
    writer_smoke_sha256 VARCHAR(64),
    approved_by VARCHAR(128),
    writer_ready_at TIMESTAMP WITH TIME ZONE,
    contracted_at TIMESTAMP WITH TIME ZONE,
    row_version BIGINT DEFAULT 1 NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT pk_lesson_source_region_migration_control PRIMARY KEY (control_id),
    CONSTRAINT ck_lesson_region_control_singleton CHECK (control_id = 'PRIMARY'),
    CONSTRAINT ck_lesson_region_control_phase CHECK (phase IN ('EXPANDED','WRITER_READY','CONTRACTED')),
    CONSTRAINT ck_lesson_region_control_shape CHECK ((phase = 'EXPANDED' AND writer_contract_version IS NULL AND writer_smoke_sha256 IS NULL AND approved_by IS NULL AND writer_ready_at IS NULL AND contracted_at IS NULL) OR (phase = 'WRITER_READY' AND writer_contract_version IS NOT NULL AND writer_smoke_sha256 ~ '^[0-9a-f]{64}$' AND approved_by IS NOT NULL AND btrim(approved_by) <> '' AND writer_ready_at IS NOT NULL AND contracted_at IS NULL) OR (phase = 'CONTRACTED' AND writer_contract_version IS NOT NULL AND writer_smoke_sha256 ~ '^[0-9a-f]{64}$' AND approved_by IS NOT NULL AND writer_ready_at IS NOT NULL AND contracted_at IS NOT NULL))
);

INSERT INTO public.lesson_source_region_migration_control (
            control_id, phase
        ) VALUES ('PRIMARY','EXPANDED');

        REVOKE ALL PRIVILEGES ON TABLE
