    CONSTRAINT ck_source_course_label_id_typed CHECK (label_id IS NOT NULL AND ((label_id_type = 'NUMERIC' AND label_id_numeric IS NOT NULL AND label_id_text IS NULL AND label_id = trim_scale(label_id_numeric)::text) OR (label_id_type = 'TEXT' AND label_id_numeric IS NULL AND label_id_text IS NOT NULL AND label_id_text <> '' AND label_id = label_id_text))),
    CONSTRAINT ck_source_course_label_revision CHECK (source_row_revision >= 1),
    CONSTRAINT ck_source_course_label_position CHECK (jsonb_typeof(source_position) = 'object' AND source_position = jsonb_build_object('v',source_position->'v','source_timestamp',source_position->'source_timestamp','record_id_type',source_position->'record_id_type','record_id',source_position->'record_id','source_partition_epoch_id',source_position->'source_partition_epoch_id','topic',source_position->'topic','partition_id',source_position->'partition_id','offset_value',source_position->'offset_value') AND source_position->'v' = '1'::jsonb AND jsonb_typeof(source_position->'source_timestamp') IN ('null','string') AND jsonb_typeof(source_position->'record_id_type') = 'string' AND source_position->>'record_id_type' IN ('none','numeric','text') AND ((source_position->>'record_id_type' = 'none' AND jsonb_typeof(source_position->'record_id') = 'null') OR (source_position->>'record_id_type' IN ('numeric','text') AND jsonb_typeof(source_position->'record_id') = 'string' AND source_position->>'record_id' <> '')) AND jsonb_typeof(source_position->'source_partition_epoch_id') = 'string' AND source_position->>'source_partition_epoch_id' <> '' AND jsonb_typeof(source_position->'topic') = 'string' AND source_position->>'topic' <> '' AND jsonb_typeof(source_position->'partition_id') = 'number' AND (source_position->>'partition_id') ~ '^(0|[1-9][0-9]*)$' AND jsonb_typeof(source_position->'offset_value') = 'number' AND (source_position->>'offset_value') ~ '^(0|[1-9][0-9]*)$'),
    CONSTRAINT ck_source_course_label_source_version CHECK (jsonb_typeof(source_version) = 'object'),
    CONSTRAINT ck_source_course_label_evidence CHECK (evidence_status IN ('CONFIRMED','PENDING_DATA','SOURCE_MISSING') AND ((evidence_status = 'CONFIRMED' AND evidence_error_code IS NULL) OR (evidence_status <> 'CONFIRMED' AND evidence_error_code IS NOT NULL AND btrim(evidence_error_code) <> '')))
);

