    CONSTRAINT ck_source_course_complaint_teacher_typed CHECK (((source_teacher_id IS NULL AND source_teacher_id_type IS NULL AND source_teacher_id_numeric IS NULL AND source_teacher_id_text IS NULL) OR ((source_teacher_id_type = 'NUMERIC' AND source_teacher_id_numeric IS NOT NULL AND source_teacher_id_text IS NULL AND source_teacher_id = trim_scale(source_teacher_id_numeric)::text) OR (source_teacher_id_type = 'TEXT' AND source_teacher_id_numeric IS NULL AND source_teacher_id_text IS NOT NULL AND source_teacher_id_text <> '' AND source_teacher_id = source_teacher_id_text)))),
