    CONSTRAINT ck_source_course_complaint_l2_typed CHECK (((complaint_type_child IS NULL AND complaint_type_child_type IS NULL AND complaint_type_child_numeric IS NULL AND complaint_type_child_text IS NULL) OR ((complaint_type_child_type = 'NUMERIC' AND complaint_type_child_numeric IS NOT NULL AND complaint_type_child_text IS NULL AND complaint_type_child = trim_scale(complaint_type_child_numeric)::text) OR (complaint_type_child_type = 'TEXT' AND complaint_type_child_numeric IS NULL AND complaint_type_child_text IS NOT NULL AND complaint_type_child_text <> '' AND complaint_type_child = complaint_type_child_text)))),
    CONSTRAINT ck_source_course_complaint_l3_typed CHECK (((complaint_type_grandson IS NULL AND complaint_type_grandson_type IS NULL AND complaint_type_grandson_numeric IS NULL AND complaint_type_grandson_text IS NULL) OR ((complaint_type_grandson_type = 'NUMERIC' AND complaint_type_grandson_numeric IS NOT NULL AND complaint_type_grandson_text IS NULL AND complaint_type_grandson = trim_scale(complaint_type_grandson_numeric)::text) OR (complaint_type_grandson_type = 'TEXT' AND complaint_type_grandson_numeric IS NULL AND complaint_type_grandson_text IS NOT NULL AND complaint_type_grandson_text <> '' AND complaint_type_grandson = complaint_type_grandson_text)))),
    CONSTRAINT ck_source_course_complaint_rule_group CHECK (((complaint_rule_id IS NULL AND source_sha256 IS NULL AND severity_rank IS NULL) OR (complaint_rule_id IS NOT NULL AND source_sha256 IS NOT NULL AND source_sha256 ~ '^[0-9a-f]{64}$' AND severity_rank BETWEEN 0 AND 4 AND category_l3_normalized IS NOT NULL AND btrim(category_l3_normalized) <> ''))),
    CONSTRAINT ck_source_course_complaint_evidence CHECK (evidence_status IN ('CONFIRMED','PENDING_DATA','SOURCE_MISSING') AND ((evidence_status = 'CONFIRMED' AND evidence_error_code IS NULL) OR (evidence_status <> 'CONFIRMED' AND evidence_error_code IS NOT NULL AND btrim(evidence_error_code) <> ''))),
    CONSTRAINT ck_source_course_complaint_revision CHECK (source_row_revision >= 1),
    CONSTRAINT ck_source_course_complaint_position CHECK (jsonb_typeof(source_position) = 'object' AND source_position = jsonb_build_object('v',source_position->'v','source_timestamp',source_position->'source_timestamp','record_id_type',source_position->'record_id_type','record_id',source_position->'record_id','source_partition_epoch_id',source_position->'source_partition_epoch_id','topic',source_position->'topic','partition_id',source_position->'partition_id','offset_value',source_position->'offset_value') AND source_position->'v' = '1'::jsonb AND jsonb_typeof(source_position->'source_timestamp') IN ('null','string') AND jsonb_typeof(source_position->'record_id_type') = 'string' AND source_position->>'record_id_type' IN ('none','numeric','text') AND ((source_position->>'record_id_type' = 'none' AND jsonb_typeof(source_position->'record_id') = 'null') OR (source_position->>'record_id_type' IN ('numeric','text') AND jsonb_typeof(source_position->'record_id') = 'string' AND source_position->>'record_id' <> '')) AND jsonb_typeof(source_position->'source_partition_epoch_id') = 'string' AND source_position->>'source_partition_epoch_id' <> '' AND jsonb_typeof(source_position->'topic') = 'string' AND source_position->>'topic' <> '' AND jsonb_typeof(source_position->'partition_id') = 'number' AND (source_position->>'partition_id') ~ '^(0|[1-9][0-9]*)$' AND jsonb_typeof(source_position->'offset_value') = 'number' AND (source_position->>'offset_value') ~ '^(0|[1-9][0-9]*)$'),
    CONSTRAINT ck_source_course_complaint_source_version CHECK (jsonb_typeof(source_version) = 'object')
);

