CREATE TABLE public.source_course_fact_current (
    source_region VARCHAR(8) NOT NULL,
    source_appoint_id VARCHAR(512) NOT NULL,
    current_grading_source_id VARCHAR(512),
    current_grading_source_id_type VARCHAR(16),
    current_grading_source_id_numeric NUMERIC,
    current_grading_source_id_text TEXT,
    grading_classification VARCHAR(32) NOT NULL,
    negative_score NUMERIC,
    grading_evidence_status VARCHAR(32) NOT NULL,
    grading_error_code VARCHAR(160),
    latest_valid_complaint_id VARCHAR(512),
    latest_valid_complaint_id_type VARCHAR(16),
    latest_valid_complaint_id_numeric NUMERIC,
    latest_valid_complaint_id_text TEXT,
    has_complaint BOOLEAN,
    has_valid_complaint BOOLEAN,
    latest_category_l1_snapshot TEXT,
    latest_category_l2_snapshot TEXT,
    latest_category_l3_snapshot TEXT,
    complaint_evidence_status VARCHAR(32) NOT NULL,
    complaint_error_code VARCHAR(160),
    is_camera_off BOOLEAN,
    camera_evidence_status VARCHAR(32) NOT NULL,
    is_cpu_usage_high BOOLEAN,
    cpu_evidence_status VARCHAR(32) NOT NULL,
    is_network_delay_high BOOLEAN,
    network_evidence_status VARCHAR(32) NOT NULL,
    source_version_vector JSONB NOT NULL,
    source_version_hash VARCHAR(64) NOT NULL,
    row_version BIGINT DEFAULT 1 NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT pk_source_course_fact_current PRIMARY KEY (source_region, source_appoint_id),
    CONSTRAINT fk_source_course_fact_course FOREIGN KEY(source_region, source_appoint_id) REFERENCES public.source_courses (source_region, source_appoint_id) ON DELETE RESTRICT DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT fk_source_course_fact_latest_complaint FOREIGN KEY(source_region, latest_valid_complaint_id) REFERENCES public.source_course_complaints (source_region, source_complaint_id) ON DELETE RESTRICT DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT ck_source_course_fact_region CHECK (source_region IN ('dom','ovs')),
    CONSTRAINT ck_source_course_fact_grading_typed CHECK (((current_grading_source_id IS NULL AND current_grading_source_id_type IS NULL AND current_grading_source_id_numeric IS NULL AND current_grading_source_id_text IS NULL) OR ((current_grading_source_id_type = 'NUMERIC' AND current_grading_source_id_numeric IS NOT NULL AND current_grading_source_id_text IS NULL AND current_grading_source_id = trim_scale(current_grading_source_id_numeric)::text) OR (current_grading_source_id_type = 'TEXT' AND current_grading_source_id_numeric IS NULL AND current_grading_source_id_text IS NOT NULL AND current_grading_source_id_text <> '' AND current_grading_source_id = current_grading_source_id_text)))),
    CONSTRAINT ck_source_course_fact_complaint_typed CHECK (((latest_valid_complaint_id IS NULL AND latest_valid_complaint_id_type IS NULL AND latest_valid_complaint_id_numeric IS NULL AND latest_valid_complaint_id_text IS NULL) OR ((latest_valid_complaint_id_type = 'NUMERIC' AND latest_valid_complaint_id_numeric IS NOT NULL AND latest_valid_complaint_id_text IS NULL AND latest_valid_complaint_id = trim_scale(latest_valid_complaint_id_numeric)::text) OR (latest_valid_complaint_id_type = 'TEXT' AND latest_valid_complaint_id_numeric IS NULL AND latest_valid_complaint_id_text IS NOT NULL AND latest_valid_complaint_id_text <> '' AND latest_valid_complaint_id = latest_valid_complaint_id_text)))),
    CONSTRAINT ck_source_course_fact_grading_result CHECK (grading_classification IN ('POSITIVE','NEGATIVE','UNCLASSIFIED','SOURCE_MISSING') AND (grading_classification = 'NEGATIVE' OR negative_score IS NULL) AND (grading_classification <> 'SOURCE_MISSING' OR grading_evidence_status = 'SOURCE_MISSING')),
    CONSTRAINT ck_source_course_fact_grading_evidence CHECK (grading_evidence_status IN ('CONFIRMED','PENDING_DATA','SOURCE_MISSING') AND ((grading_evidence_status = 'CONFIRMED' AND grading_error_code IS NULL) OR (grading_evidence_status <> 'CONFIRMED' AND grading_error_code IS NOT NULL AND btrim(grading_error_code) <> ''))),
    CONSTRAINT ck_source_course_fact_latest_valid CHECK ((latest_valid_complaint_id IS NULL OR has_valid_complaint IS TRUE)),
    CONSTRAINT ck_source_course_fact_complaint_evidence CHECK (complaint_evidence_status IN ('CONFIRMED','PENDING_DATA','SOURCE_MISSING') AND ((complaint_evidence_status = 'CONFIRMED' AND complaint_error_code IS NULL) OR (complaint_evidence_status <> 'CONFIRMED' AND complaint_error_code IS NOT NULL AND btrim(complaint_error_code) <> ''))),
    CONSTRAINT ck_source_course_fact_camera_evidence CHECK (camera_evidence_status IN ('CONFIRMED','PENDING_DATA','SOURCE_MISSING') AND ((camera_evidence_status = 'CONFIRMED' AND is_camera_off IS NOT NULL) OR (camera_evidence_status <> 'CONFIRMED' AND is_camera_off IS NULL))),
    CONSTRAINT ck_source_course_fact_retired_qa_sources CHECK (is_cpu_usage_high IS NULL AND cpu_evidence_status = 'SOURCE_MISSING' AND is_network_delay_high IS NULL AND network_evidence_status = 'SOURCE_MISSING'),
    CONSTRAINT ck_source_course_fact_row_version CHECK (row_version >= 1),
    CONSTRAINT ck_source_course_fact_source_vector CHECK (jsonb_typeof(source_version_vector) = 'object' AND source_version_hash ~ '^[0-9a-f]{64}$' AND source_version_hash = public.dts_canonical_json_sha256_v1(source_version_vector))
);

CREATE TABLE public.source_participation_fact_current (
