    CONSTRAINT ck_source_participation_fact_early CHECK (early_evidence_status IN ('CONFIRMED','PENDING_DATA','SOURCE_MISSING') AND ((early_evidence_status = 'CONFIRMED' AND is_early IS NOT NULL) OR (early_evidence_status <> 'CONFIRMED' AND is_early IS NULL))),
    CONSTRAINT ck_source_participation_fact_penalty_keys CHECK (jsonb_typeof(penalty_source_keys) = 'array' AND penalty_source_keys_hash ~ '^[0-9a-f]{64}$' AND penalty_source_keys_hash = public.dts_canonical_json_sha256_v1(penalty_source_keys)),
    CONSTRAINT ck_source_participation_fact_source_vector CHECK (jsonb_typeof(source_version_vector) = 'object' AND source_version_hash ~ '^[0-9a-f]{64}$' AND source_version_hash = public.dts_canonical_json_sha256_v1(source_version_vector)),
    CONSTRAINT ck_source_participation_fact_row_version CHECK (row_version >= 1)
);

CREATE TABLE public.domain_aggregate_revisions (
