    revision BIGINT NOT NULL,
    last_source_row_revision BIGINT,
    last_source_position JSONB,
    aggregate_state JSONB DEFAULT '{}'::jsonb NOT NULL,
    aggregate_state_sha256 VARCHAR(64) DEFAULT '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a' NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT pk_domain_aggregate_revisions PRIMARY KEY (aggregate_type, aggregate_id),
    CONSTRAINT ck_domain_aggregate_type CHECK (aggregate_type IN ('COURSE','PARTICIPATION','TEACHER','TEACHER_STUDENT','LABEL','COMPLAINT_CATEGORY','COMPLETION_CONFLICT','SOURCE_SCOPE','TASK_PLAN')),
    CONSTRAINT ck_domain_aggregate_canonical_key CHECK (public.dts_domain_aggregate_key_valid_v2(aggregate_type,canonical_key) IS TRUE),
    CONSTRAINT ck_domain_aggregate_id CHECK (canonical_key_sha256 ~ '^[0-9a-f]{64}$' AND canonical_key_sha256 = public.dts_canonical_json_sha256_v1(canonical_key) AND aggregate_id = 'v2:' || aggregate_type || ':' || canonical_key_sha256),
    CONSTRAINT ck_domain_aggregate_revisions CHECK (revision >= 1 AND (last_source_row_revision IS NULL OR last_source_row_revision >= 1)),
    CONSTRAINT ck_domain_aggregate_source_position CHECK (last_source_position IS NULL OR (jsonb_typeof(last_source_position) = 'object' AND last_source_position = jsonb_build_object('v',last_source_position->'v','source_timestamp',last_source_position->'source_timestamp','record_id_type',last_source_position->'record_id_type','record_id',last_source_position->'record_id','source_partition_epoch_id',last_source_position->'source_partition_epoch_id','topic',last_source_position->'topic','partition_id',last_source_position->'partition_id','offset_value',last_source_position->'offset_value') AND last_source_position->'v' = '1'::jsonb AND jsonb_typeof(last_source_position->'source_timestamp') IN ('null','string') AND jsonb_typeof(last_source_position->'record_id_type') = 'string' AND last_source_position->>'record_id_type' IN ('none','numeric','text') AND ((last_source_position->>'record_id_type' = 'none' AND jsonb_typeof(last_source_position->'record_id') = 'null') OR (last_source_position->>'record_id_type' IN ('numeric','text') AND jsonb_typeof(last_source_position->'record_id') = 'string' AND last_source_position->>'record_id' <> '')) AND jsonb_typeof(last_source_position->'source_partition_epoch_id') = 'string' AND last_source_position->>'source_partition_epoch_id' <> '' AND jsonb_typeof(last_source_position->'topic') = 'string' AND last_source_position->>'topic' <> '' AND jsonb_typeof(last_source_position->'partition_id') = 'number' AND (last_source_position->>'partition_id') ~ '^(0|[1-9][0-9]*)$' AND jsonb_typeof(last_source_position->'offset_value') = 'number' AND (last_source_position->>'offset_value') ~ '^(0|[1-9][0-9]*)$')),
    CONSTRAINT ck_domain_aggregate_state_hash CHECK (jsonb_typeof(aggregate_state) = 'object' AND aggregate_state_sha256 ~ '^[0-9a-f]{64}$' AND aggregate_state_sha256 = public.dts_canonical_json_sha256_v1(aggregate_state)),
    CONSTRAINT ck_domain_aggregate_dom_student_token CHECK (aggregate_type <> 'TEACHER_STUDENT' OR canonical_key->>'source_region' = 'ovs' OR canonical_key->>'student_token' ~ '^dom:v1:[0-9a-f]{64}$')
);

REVOKE ALL PRIVILEGES ON TABLE
                public.source_course_labels,
            public.source_course_complaints,
            public.source_course_fact_current,
            public.source_participation_fact_current,
            public.domain_aggregate_revisions
            FROM PUBLIC, tit_growth_app, tit_dts_ingest_runtime;

            DO $$
            BEGIN
                IF to_regrole('tit_growth_app') IS NOT NULL THEN
                    IF EXISTS (
                        SELECT 1
                        FROM pg_roles
                        WHERE rolname = 'tit_growth_app'
                          AND (
                              NOT rolcanlogin OR rolinherit OR rolsuper
                              OR rolcreatedb OR rolcreaterole OR rolreplication
                              OR rolbypassrls
                          )
                    ) THEN
                        RAISE EXCEPTION
                            'tit_growth_app must be a restricted NOINHERIT LOGIN role';
                    END IF;
                    EXECUTE 'REVOKE ALL PRIVILEGES ON TABLE '
                        'public.source_course_labels,public.source_course_complaints,public.source_course_fact_current,public.source_participation_fact_current,public.domain_aggregate_revisions '
                        'FROM tit_growth_app';
                    EXECUTE 'GRANT SELECT,INSERT,UPDATE ON TABLE '
                        'public.source_course_labels,public.source_course_complaints,public.source_course_fact_current,public.source_participation_fact_current '
                        'TO tit_growth_app';
                    EXECUTE 'GRANT SELECT ON TABLE '
                        'public.domain_aggregate_revisions '
                        'TO tit_growth_app';
                    EXECUTE 'GRANT EXECUTE ON FUNCTION '
                        'public.dts_canonical_json_v1(jsonb),'
                        'public.dts_canonical_json_sha256_v1(jsonb) '
                        'TO tit_growth_app';
                END IF;
            END
            $$;

UPDATE alembic_version SET version_num='20260822_81_dts_v2_domain_facts' WHERE alembic_version.version_num = '20260822_80_dts_v2_dirty_queue';

-- Running upgrade 20260822_81_dts_v2_domain_facts -> 20260822_82_v2_runtime_acl

DO $$
        BEGIN
            IF to_regrole('tit_dts_ingest_runtime') IS NULL THEN
                RAISE EXCEPTION 'DTS_V2_DUAL_CAPTURE_RUNTIME_ROLE_MISSING';
            END IF;
            IF to_regclass('public.dts_source_partition_epochs') IS NULL
               OR to_regclass('public.dts_source_row_versions') IS NULL
               OR to_regclass('public.dts_source_rows') IS NULL
               OR to_regclass('public.dts_ingest_events') IS NULL
               OR to_regclass('public.dts_ingest_checkpoints') IS NULL
               OR to_regclass('public.dts_dirty_keys') IS NULL
               OR to_regclass('public.dts_dirty_key_inputs') IS NULL
               OR to_regprocedure(
                    'public.enqueue_dirty_from_source_revision_v2('
                    'text,text,text,bigint,text,text,text)'
                  ) IS NULL THEN
                RAISE EXCEPTION 'DTS_V2_DUAL_CAPTURE_SCHEMA_NOT_READY';
            END IF;
        END
        $$;

        CREATE FUNCTION public.lock_dts_source_partition_epoch_for_ingest_v2(
            p_source_region text,
            p_source_partition_epoch_id text,
            p_topic text,
            p_partition_id integer
        )
        RETURNS boolean
        LANGUAGE plpgsql
        SECURITY DEFINER
        SET search_path = pg_catalog, public
        AS $$
        DECLARE locked_epoch record;
        BEGIN
            IF p_source_region NOT IN ('dom','ovs')
               OR p_source_partition_epoch_id IS NULL
               OR btrim(p_source_partition_epoch_id) = ''
               OR p_topic IS NULL OR btrim(p_topic) = ''
               OR p_partition_id IS NULL OR p_partition_id < 0 THEN
                RAISE EXCEPTION 'DTS_V2_DUAL_CAPTURE_EPOCH_LOCK_INVALID'
                    USING ERRCODE = '22023';
            END IF;
            SELECT epoch_kind,status
            INTO locked_epoch
            FROM public.dts_source_partition_epochs
            WHERE source_region = p_source_region
              AND source_partition_epoch_id = p_source_partition_epoch_id
              AND topic = p_topic
              AND partition_id = p_partition_id
            FOR SHARE;
            IF NOT FOUND
               OR locked_epoch.epoch_kind IS DISTINCT FROM 'BROKER'
               OR locked_epoch.status IS DISTINCT FROM 'ACTIVE' THEN
                RAISE EXCEPTION 'DTS_V2_DUAL_CAPTURE_EPOCH_LOCK_REJECTED'
                    USING ERRCODE = '23503';
            END IF;
            RETURN true;
        END
        $$;

        REVOKE ALL ON FUNCTION
            public.lock_dts_source_partition_epoch_for_ingest_v2(
                text,text,text,integer
            )
        FROM PUBLIC, tit_growth_app, tit_dts_ingest_runtime;

CREATE OR REPLACE FUNCTION public.enqueue_dirty_from_source_revision_v2(
    p_source_region text,
    p_source_table text,
    p_source_key text,
    p_source_row_revision bigint,
    p_key_type text,
    p_key_part_1 text,
    p_key_part_2 text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
    version public.dts_source_row_versions%ROWTYPE;
    current_row public.dts_source_rows%ROWTYPE;
    identity jsonb;
    fingerprint text;
    dirty_region text;
BEGIN
    SELECT * INTO version
    FROM public.dts_source_row_versions
    WHERE source_region = p_source_region
      AND source_table = p_source_table
      AND source_key = p_source_key
      AND source_row_revision = p_source_row_revision
    FOR KEY SHARE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'DIRTY_INPUT_REFERENCE_INVALID'
            USING ERRCODE = '23503';
    END IF;

    SELECT * INTO current_row
    FROM public.dts_source_rows
    WHERE source_region = p_source_region
      AND source_table = p_source_table
      AND source_key = p_source_key
    FOR KEY SHARE;
    IF NOT FOUND
       OR current_row.provenance_state IS DISTINCT FROM 'V2_CONFIRMED'
       OR current_row.source_row_revision IS DISTINCT FROM
            p_source_row_revision
       OR current_row.source_payload_hash IS DISTINCT FROM
            version.protected_source_row_hash THEN
        RAISE EXCEPTION 'DIRTY_INPUT_REFERENCE_INVALID'
            USING ERRCODE = '23503';
    END IF;

    dirty_region := CASE WHEN p_key_type = 'COMPLAINT_CATEGORY' THEN 'dom' ELSE p_source_region END;
    IF p_key_type = 'COMPLAINT_CATEGORY' AND version.source_table NOT IN ('dom_complaint','ovs_complaint','dom_complaint_cate') THEN RAISE EXCEPTION 'DIRTY_INPUT_AUTHORITY_DENIED' USING ERRCODE = '42501'; END IF;

    identity := jsonb_build_object(
        'source_region',p_source_region,
        'source_table',p_source_table,
        'source_key',p_source_key
    );
    fingerprint := public.dts_canonical_json_sha256_v1(
        jsonb_build_object(
            'protocol','dirty-source-v1',
            'identity',identity,
            'revision',p_source_row_revision,
            'version_kind',version.version_kind,
            'operation',version.operation,
            'is_deleted',current_row.is_deleted,
            'protected_source_row_hash',version.protected_source_row_hash
        )
    );
    RETURN public._upsert_dts_dirty_key_input_v2(
        dirty_region,p_key_type,p_key_part_1,p_key_part_2,
        'SOURCE_REVISION',identity,p_source_row_revision,fingerprint
    );
END
$$;

REVOKE ALL ON FUNCTION
            public.enqueue_dirty_from_source_revision_v2(
                text,text,text,bigint,text,text,text
            ),
            public._upsert_dts_dirty_key_input_v2(
