        FROM tit_dts_ingest_runtime;

        GRANT SELECT ON TABLE public.dts_source_partition_epochs
        TO tit_dts_ingest_runtime;
        GRANT SELECT, INSERT ON TABLE public.dts_source_row_versions
        TO tit_dts_ingest_runtime;
