        REVOKE ALL PRIVILEGES ON TABLE
            public.dts_dirty_keys,
            public.dts_dirty_key_inputs,
            public.dts_dirty_key_dependencies,
            public.dts_dirty_key_state_audits
        FROM tit_dts_ingest_runtime;

        -- DOM startup validates privacy state against current lesson and dirty
        -- facts.  Keep this surface read-only; dirty writes still go through
        -- the SECURITY DEFINER functions above.
        GRANT SELECT ON TABLE
            public.dts_dirty_keys,
            public.lesson_source_wide
        TO tit_dts_ingest_runtime;

        DO $$
        BEGIN
            IF to_regrole('tit_teacher_crud') IS NOT NULL THEN
                EXECUTE 'REVOKE ALL ON FUNCTION '
                    'public.lock_dts_source_partition_epoch_for_ingest_v2('
                    'text,text,text,integer) FROM tit_teacher_crud';
            END IF;
            IF to_regrole('tit_growth_app') IS NOT NULL THEN
                EXECUTE 'REVOKE ALL ON FUNCTION '
                    'public.lock_dts_source_partition_epoch_for_ingest_v2('
                    'text,text,text,integer) '
                    'FROM tit_growth_app';
            END IF;
        END
        $$;

        COMMENT ON FUNCTION
            public.lock_dts_source_partition_epoch_for_ingest_v2(
                text,text,text,integer
            ) IS
            'Least-privilege row lock for one ACTIVE broker epoch during an ingest transaction.';

UPDATE alembic_version SET version_num='20260822_82_v2_runtime_acl' WHERE alembic_version.version_num = '20260822_81_dts_v2_domain_facts';

-- Running upgrade 20260822_82_v2_runtime_acl -> 20260822_83_dts_v2_scope

CREATE FUNCTION public.dts_source_table_allowed_v2(
            p_source_region text,
            p_source_table text
        )
        RETURNS boolean
        LANGUAGE sql
        IMMUTABLE
        STRICT
        PARALLEL SAFE
        SET search_path = pg_catalog, public
        AS $$
            SELECT (p_source_region,p_source_table) IN (
                VALUES ('dom','dom_appoint'),('dom','dom_complaint'),('dom','dom_complaint_cate'),('dom','dom_grading_label'),('dom','dom_grading_label_log'),('dom','dom_qa_task_close_camera_record'),('dom','dom_teacher'),('dom','dom_teacher_absent_reason'),('dom','dom_teacher_blacklist'),('dom','dom_teacher_certification'),('dom','dom_teacher_class_schedule'),('dom','dom_teacher_favorite'),('dom','dom_teacher_penalty'),('dom','dom_user_complaint'),('dom','dom_user_teacher_grading'),('ovs','ovs_appoint'),('ovs','ovs_complaint'),('ovs','ovs_grading_label'),('ovs','ovs_grading_label_log'),('ovs','ovs_qa_task_close_camera_record'),('ovs','ovs_teacher_blacklist'),('ovs','ovs_teacher_favorite'),('ovs','ovs_user_complaint'),('ovs','ovs_user_teacher_grading')
            )
        $$;

        CREATE FUNCTION public.dts_source_scope_identity_valid_v2(
            p_source_region text,
            p_source_table text,
            p_scope_kind text,
            p_scope_level text,
            p_scope_key text
        )
        RETURNS boolean
        LANGUAGE sql
        IMMUTABLE
        STRICT
        PARALLEL SAFE
        SET search_path = pg_catalog, public
        AS $$
            SELECT public.dts_source_table_allowed_v2(
                       p_source_region,p_source_table
                   )
               AND p_scope_kind IN ('CURRENT','HISTORY')
               AND (
                    p_scope_kind = 'CURRENT'
                    OR p_source_table IN ('dom_appoint','ovs_appoint','dom_teacher_class_schedule','dom_teacher_favorite','ovs_teacher_favorite','dom_teacher_blacklist','ovs_teacher_blacklist')
               )
               AND p_scope_level IN ('GLOBAL','TEACHER')
               AND (
                    (p_scope_level = 'GLOBAL' AND p_scope_key = '*')
                    OR (
                        p_scope_level = 'TEACHER'
                        AND p_scope_key <> ''
                        AND btrim(p_scope_key) = p_scope_key
                    )
               )
        $$;

        CREATE FUNCTION public.dts_source_key_parts_valid_v2(
            p_source_key text,
            p_source_key_data jsonb,
            p_source_key_type text,
            p_source_key_numeric numeric,
            p_source_key_text text
        )
        RETURNS boolean
        LANGUAGE plpgsql
        IMMUTABLE
        STRICT
        PARALLEL SAFE
        SET search_path = pg_catalog, public
        AS $$
        BEGIN
            IF jsonb_typeof(p_source_key_data) <> 'object'
               OR p_source_key_data <> jsonb_build_object(
                    'id',p_source_key_data->'id'
               ) THEN
                RETURN false;
            END IF;
            IF p_source_key_type = 'NUMERIC' THEN
                RETURN jsonb_typeof(p_source_key_data->'id') = 'number'
                   AND p_source_key_numeric IS NOT NULL
                   AND p_source_key_text IS NULL
                   AND p_source_key_numeric =
                        (p_source_key_data->>'id')::numeric
                   AND p_source_key = trim_scale(p_source_key_numeric)::text;
            ELSIF p_source_key_type = 'TEXT' THEN
                RETURN jsonb_typeof(p_source_key_data->'id') = 'string'
                   AND p_source_key_numeric IS NULL
                   AND p_source_key_text IS NOT NULL
                   AND p_source_key_text <> ''
                   AND btrim(p_source_key_text) = p_source_key_text
                   AND p_source_key_text = p_source_key_data->>'id'
                   AND p_source_key = p_source_key_text;
            END IF;
            RETURN false;
        EXCEPTION
            WHEN invalid_text_representation OR numeric_value_out_of_range THEN
                RETURN false;
        END
        $$;

        CREATE FUNCTION public.dts_dependency_keys_valid_v2(
            p_source_region text,
            p_dependency_keys jsonb
        )
        RETURNS boolean
        LANGUAGE sql
        IMMUTABLE
        STRICT
        PARALLEL SAFE
        SET search_path = pg_catalog, public
        AS $$
            SELECT p_source_region IN ('dom','ovs')
               AND jsonb_typeof(p_dependency_keys) = 'object'
               AND p_dependency_keys = jsonb_build_object(
                    'category_ids',p_dependency_keys->'category_ids',
                    'course_ids',p_dependency_keys->'course_ids',
                    'label_ids',p_dependency_keys->'label_ids',
                    'student_subjects',p_dependency_keys->'student_subjects',
                    'teacher_ids',p_dependency_keys->'teacher_ids'
               )
               AND NOT EXISTS (
                    SELECT 1
                    FROM jsonb_each(p_dependency_keys) AS dependency(k,v)
                    WHERE jsonb_typeof(v) <> 'array'
                       OR EXISTS (
                            SELECT 1
                            FROM jsonb_array_elements(v) AS item(value)
                            WHERE jsonb_typeof(value) <> 'string'
                               OR value #>> '{}' = ''
                               OR btrim(value #>> '{}') <> value #>> '{}'
                               OR (
                                    k = 'student_subjects'
                                    AND p_source_region = 'dom'
                                    AND value #>> '{}'
                                        !~ '^dom:v1:[0-9a-f]{64}$'
                               )
                       )
                       OR jsonb_array_length(v) <> (
                            SELECT count(DISTINCT value)
                            FROM jsonb_array_elements(v) AS item(value)
                       )
               )
        $$;

        CREATE FUNCTION public.dts_normalize_scope_partition_offsets_v2(
            p_offsets jsonb,
            p_source_region text
        )
        RETURNS jsonb
        LANGUAGE plpgsql
        IMMUTABLE
        STRICT
        PARALLEL SAFE
        SET search_path = pg_catalog, public
        AS $$
        DECLARE result jsonb;
        BEGIN
            IF p_source_region NOT IN ('dom','ovs')
               OR jsonb_typeof(p_offsets) <> 'array'
               OR jsonb_array_length(p_offsets) = 0
               OR EXISTS (
                    SELECT 1
                    FROM jsonb_array_elements(p_offsets) AS item(value)
                    WHERE jsonb_typeof(value) <> 'object'
                       OR value <> jsonb_build_object(
                            'source_region',value->'source_region',
                            'source_partition_epoch_id',
                                value->'source_partition_epoch_id',
                            'topic',value->'topic',
                            'partition_id',value->'partition_id',
                            'start_next_offset',value->'start_next_offset',
                            'end_next_offset',value->'end_next_offset'
                       )
                       OR jsonb_typeof(value->'source_region') <> 'string'
                       OR value->>'source_region' <> p_source_region
                       OR jsonb_typeof(
                            value->'source_partition_epoch_id'
                          ) <> 'string'
                       OR btrim(value->>'source_partition_epoch_id') = ''
                       OR jsonb_typeof(value->'topic') <> 'string'
                       OR btrim(value->>'topic') = ''
                       OR jsonb_typeof(value->'partition_id') <> 'number'
                       OR (value->>'partition_id') !~ '^[0-9]+$'
                       OR jsonb_typeof(value->'start_next_offset') <> 'number'
                       OR (value->>'start_next_offset') !~ '^[0-9]+$'
                       OR jsonb_typeof(value->'end_next_offset') <> 'number'
                       OR (value->>'end_next_offset') !~ '^[0-9]+$'
                       OR (value->>'end_next_offset')::numeric <
                            (value->>'start_next_offset')::numeric
               ) THEN
                RAISE EXCEPTION 'SOURCE_SCOPE_FENCE_VECTOR_INVALID'
                    USING ERRCODE = '22023';
            END IF;

            SELECT jsonb_agg(value ORDER BY
                       convert_to(value->>'source_region','UTF8'),
                       convert_to(value->>'source_partition_epoch_id','UTF8'),
                       convert_to(value->>'topic','UTF8'),
                       (value->>'partition_id')::integer)
            INTO result
            FROM jsonb_array_elements(p_offsets) AS item(value);

            IF EXISTS (
                SELECT 1
                FROM jsonb_array_elements(result) AS item(value)
                GROUP BY value->>'source_region',
                         value->>'source_partition_epoch_id',
                         value->>'topic',
                         (value->>'partition_id')::integer
                HAVING count(*) > 1
            ) THEN
                RAISE EXCEPTION 'SOURCE_SCOPE_FENCE_VECTOR_DUPLICATE'
                    USING ERRCODE = '22023';
            END IF;
            RETURN result;
        EXCEPTION
            WHEN invalid_text_representation OR numeric_value_out_of_range THEN
                RAISE EXCEPTION 'SOURCE_SCOPE_FENCE_VECTOR_INVALID'
                    USING ERRCODE = '22023';
        END
        $$;

        REVOKE ALL ON FUNCTION
            public.dts_source_table_allowed_v2(text,text),
            public.dts_source_scope_identity_valid_v2(
                text,text,text,text,text
            ),
            public.dts_source_key_parts_valid_v2(
                text,jsonb,text,numeric,text
            ),
            public.dts_dependency_keys_valid_v2(text,jsonb),
            public.dts_normalize_scope_partition_offsets_v2(jsonb,text)
        FROM PUBLIC;

CREATE TABLE public.dts_source_table_publish_generations (
    source_region VARCHAR(8) NOT NULL,
    source_table VARCHAR(128) NOT NULL,
    current_generation BIGINT DEFAULT 0 NOT NULL,
    current_snapshot_id VARCHAR(160),
    active_candidate_snapshot_id VARCHAR(160),
    candidate_owner VARCHAR(128),
    candidate_lease_token VARCHAR(160),
    candidate_lease_expires_at TIMESTAMP WITH TIME ZONE,
    row_version BIGINT DEFAULT 1 NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT pk_dts_source_table_publish_generations PRIMARY KEY (source_region, source_table),
    CONSTRAINT ck_dts_source_publish_head_table CHECK (public.dts_source_table_allowed_v2(source_region,source_table)),
    CONSTRAINT ck_dts_source_publish_head_generation CHECK (current_generation >= 0 AND row_version >= 1 AND ((current_generation = 0 AND current_snapshot_id IS NULL) OR (current_generation > 0 AND current_snapshot_id IS NOT NULL))),
    CONSTRAINT ck_dts_source_publish_head_candidate CHECK ((active_candidate_snapshot_id IS NULL AND candidate_owner IS NULL AND candidate_lease_token IS NULL AND candidate_lease_expires_at IS NULL) OR (active_candidate_snapshot_id IS NOT NULL AND candidate_owner IS NOT NULL AND btrim(candidate_owner) <> '' AND candidate_lease_token IS NOT NULL AND btrim(candidate_lease_token) <> '' AND candidate_lease_expires_at IS NOT NULL))
);

COMMENT ON TABLE public.dts_source_table_publish_generations IS 'Per-table serial publication head for all GLOBAL and TEACHER source-scope candidates.';

CREATE UNIQUE INDEX uq_dts_source_publish_head_lease_token ON public.dts_source_table_publish_generations (candidate_lease_token) WHERE candidate_lease_token IS NOT NULL;

CREATE TABLE public.dts_source_scope_snapshots (
    snapshot_id VARCHAR(160) NOT NULL,
    source_region VARCHAR(8) NOT NULL,
    source_table VARCHAR(128) NOT NULL,
    scope_kind VARCHAR(16) NOT NULL,
    scope_level VARCHAR(16) NOT NULL,
    scope_key VARCHAR(160) NOT NULL,
    epoch_state VARCHAR(16) NOT NULL,
    snapshot_as_of TIMESTAMP WITH TIME ZONE NOT NULL,
    snapshot_consistency_token TEXT NOT NULL,
    snapshot_consistency_token_hash VARCHAR(64) NOT NULL,
    snapshot_fence_vector JSONB NOT NULL,
    partition_offsets JSONB NOT NULL,
    snapshot_fence_hash VARCHAR(64) NOT NULL,
    row_count BIGINT,
    content_hash VARCHAR(64),
    history_from TIMESTAMP WITH TIME ZONE,
    history_through TIMESTAMP WITH TIME ZONE,
    base_publish_generation BIGINT NOT NULL,
    base_snapshot_id VARCHAR(160),
    published_generation BIGINT,
    generation_diff_count BIGINT,
    generation_diff_hash VARCHAR(64),
    begin_request_hash VARCHAR(64) NOT NULL,
    verify_request_hash VARCHAR(64),
    publish_request_hash VARCHAR(64),
    terminal_request_hash VARCHAR(64),
    error_code VARCHAR(128),
    created_by VARCHAR(128) NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    verified_at TIMESTAMP WITH TIME ZONE,
    completed_at TIMESTAMP WITH TIME ZONE,
    failed_at TIMESTAMP WITH TIME ZONE,
    invalidated_at TIMESTAMP WITH TIME ZONE,
    row_version BIGINT DEFAULT 1 NOT NULL,
    CONSTRAINT pk_dts_source_scope_snapshots PRIMARY KEY (snapshot_id),
    CONSTRAINT uq_dts_source_scope_snapshot_identity UNIQUE (snapshot_id, source_region, source_table, scope_kind, scope_level, scope_key),
    CONSTRAINT uq_dts_source_scope_snapshot_table_identity UNIQUE (source_region, source_table, snapshot_id),
    CONSTRAINT uq_dts_source_scope_snapshot_generation_identity UNIQUE (source_region, source_table, published_generation, snapshot_id),
    CONSTRAINT ck_dts_source_scope_snapshot_identity CHECK (public.dts_source_scope_identity_valid_v2(source_region,source_table,scope_kind,scope_level,scope_key)),
    CONSTRAINT ck_dts_source_scope_snapshot_state CHECK (epoch_state IN ('LOADING','VERIFYING','COMPLETE','FAILED','STALE','SUPERSEDED')),
    CONSTRAINT ck_dts_source_scope_snapshot_hashes CHECK (snapshot_consistency_token_hash ~ '^[0-9a-f]{64}$' AND snapshot_fence_hash ~ '^[0-9a-f]{64}$' AND begin_request_hash ~ '^[0-9a-f]{64}$' AND (verify_request_hash IS NULL OR verify_request_hash ~ '^[0-9a-f]{64}$') AND (publish_request_hash IS NULL OR publish_request_hash ~ '^[0-9a-f]{64}$') AND (terminal_request_hash IS NULL OR terminal_request_hash ~ '^[0-9a-f]{64}$')),
    CONSTRAINT ck_dts_source_scope_snapshot_fence CHECK (jsonb_typeof(snapshot_fence_vector) = 'array' AND jsonb_array_length(snapshot_fence_vector) > 0 AND partition_offsets = snapshot_fence_vector),
    CONSTRAINT ck_dts_source_scope_snapshot_history CHECK ((scope_kind = 'CURRENT' AND history_from IS NULL AND history_through IS NULL) OR (scope_kind = 'HISTORY' AND history_from IS NOT NULL AND history_through IS NOT NULL AND history_from <= history_through)),
    CONSTRAINT ck_dts_source_scope_snapshot_versions CHECK (base_publish_generation >= 0 AND row_version >= 1 AND (published_generation IS NULL OR published_generation >= 1) AND (generation_diff_count IS NULL OR generation_diff_count >= 0)),
    CONSTRAINT ck_dts_source_scope_snapshot_lifecycle CHECK ((epoch_state = 'LOADING' AND row_count IS NULL AND content_hash IS NULL AND verified_at IS NULL AND published_generation IS NULL AND completed_at IS NULL AND failed_at IS NULL AND error_code IS NULL) OR (epoch_state = 'VERIFYING' AND row_count >= 0 AND content_hash ~ '^[0-9a-f]{64}$' AND verified_at IS NOT NULL AND published_generation IS NULL AND completed_at IS NULL AND failed_at IS NULL AND error_code IS NULL) OR (epoch_state = 'COMPLETE' AND row_count >= 0 AND content_hash ~ '^[0-9a-f]{64}$' AND verified_at IS NOT NULL AND completed_at IS NOT NULL AND published_generation >= 1 AND generation_diff_count >= 0 AND generation_diff_hash ~ '^[0-9a-f]{64}$' AND error_code IS NULL) OR (epoch_state = 'FAILED' AND failed_at IS NOT NULL AND error_code IS NOT NULL AND btrim(error_code) <> '' AND published_generation IS NULL) OR (epoch_state = 'STALE' AND invalidated_at IS NOT NULL AND published_generation IS NOT NULL) OR (epoch_state = 'SUPERSEDED' AND invalidated_at IS NOT NULL AND published_generation IS NOT NULL AND completed_at IS NOT NULL))
);

COMMENT ON TABLE public.dts_source_scope_snapshots IS 'Immutable source-scope snapshot epochs with relationally verified fence and publication evidence.';

CREATE UNIQUE INDEX uq_dts_source_scope_snapshot_published_generation ON public.dts_source_scope_snapshots (source_region, source_table, published_generation) WHERE published_generation IS NOT NULL;

CREATE TABLE public.dts_source_snapshot_fences (
    snapshot_id VARCHAR(160) NOT NULL,
    source_region VARCHAR(8) NOT NULL,
    source_table VARCHAR(128) NOT NULL,
    scope_kind VARCHAR(16) NOT NULL,
    scope_level VARCHAR(16) NOT NULL,
    scope_key VARCHAR(160) NOT NULL,
    source_partition_epoch_id VARCHAR(160) NOT NULL,
    topic VARCHAR(512) NOT NULL,
    partition_id INTEGER NOT NULL,
    start_next_offset BIGINT NOT NULL,
    end_next_offset BIGINT NOT NULL,
    CONSTRAINT pk_dts_source_snapshot_fences PRIMARY KEY (snapshot_id, source_partition_epoch_id, topic, partition_id),
    CONSTRAINT fk_dts_source_snapshot_fence_snapshot FOREIGN KEY(snapshot_id, source_region, source_table, scope_kind, scope_level, scope_key) REFERENCES public.dts_source_scope_snapshots (snapshot_id, source_region, source_table, scope_kind, scope_level, scope_key) ON DELETE RESTRICT,
    CONSTRAINT fk_dts_source_snapshot_fence_epoch FOREIGN KEY(source_region, source_partition_epoch_id, topic, partition_id) REFERENCES public.dts_source_partition_epochs (source_region, source_partition_epoch_id, topic, partition_id) ON DELETE RESTRICT,
    CONSTRAINT ck_dts_source_snapshot_fence_offsets CHECK (partition_id >= 0 AND start_next_offset >= 0 AND end_next_offset >= start_next_offset)
);

COMMENT ON TABLE public.dts_source_snapshot_fences IS 'Typed per-epoch half-open broker next-offset fences for one source-scope snapshot.';

CREATE TABLE public.dts_source_snapshot_rows (
    snapshot_id VARCHAR(160) NOT NULL,
    source_region VARCHAR(8) NOT NULL,
    source_table VARCHAR(128) NOT NULL,
    scope_kind VARCHAR(16) NOT NULL,
    scope_level VARCHAR(16) NOT NULL,
    scope_key VARCHAR(160) NOT NULL,
    source_key VARCHAR(512) NOT NULL,
    source_key_data JSONB NOT NULL,
    source_key_type VARCHAR(16) NOT NULL,
    source_key_numeric NUMERIC,
    source_key_text TEXT,
    dependency_keys JSONB NOT NULL,
    protected_source_row JSONB NOT NULL,
    snapshot_row_hash VARCHAR(64) NOT NULL,
    base_source_row_revision BIGINT,
    base_row_hash VARCHAR(64),
    snapshot_as_of TIMESTAMP WITH TIME ZONE NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT pk_dts_source_snapshot_rows PRIMARY KEY (snapshot_id, source_region, source_table, scope_kind, scope_level, scope_key, source_key),
    CONSTRAINT fk_dts_source_snapshot_row_snapshot FOREIGN KEY(snapshot_id, source_region, source_table, scope_kind, scope_level, scope_key) REFERENCES public.dts_source_scope_snapshots (snapshot_id, source_region, source_table, scope_kind, scope_level, scope_key) ON DELETE RESTRICT,
    CONSTRAINT ck_dts_source_snapshot_row_key CHECK (public.dts_source_key_parts_valid_v2(source_key,source_key_data,source_key_type,source_key_numeric,source_key_text)),
    CONSTRAINT ck_dts_source_snapshot_row_dependencies CHECK (public.dts_dependency_keys_valid_v2(source_region,dependency_keys)),
    CONSTRAINT ck_dts_source_snapshot_row_payload CHECK (jsonb_typeof(protected_source_row) = 'object' AND snapshot_row_hash ~ '^[0-9a-f]{64}$' AND snapshot_row_hash = public.dts_canonical_json_sha256_v1(protected_source_row) AND (source_region <> 'dom' OR public.dom_student_json_is_safe_v1(protected_source_row))),
    CONSTRAINT ck_dts_source_snapshot_row_base CHECK ((base_source_row_revision IS NULL OR base_source_row_revision >= 1) AND (base_row_hash IS NULL OR base_row_hash ~ '^[0-9a-f]{64}$'))
);

COMMENT ON TABLE public.dts_source_snapshot_rows IS 'Candidate-only protected staging rows with typed keys and frozen live-current base evidence.';

CREATE TABLE public.dts_source_scope_states (
    source_region VARCHAR(8) NOT NULL,
    source_table VARCHAR(128) NOT NULL,
    scope_kind VARCHAR(16) NOT NULL,
    scope_level VARCHAR(16) NOT NULL,
    scope_key VARCHAR(160) NOT NULL,
    state VARCHAR(16) NOT NULL,
    active_snapshot_id VARCHAR(160),
    candidate_snapshot_id VARCHAR(160),
    completed_at TIMESTAMP WITH TIME ZONE,
    invalidated_at TIMESTAMP WITH TIME ZONE,
    last_invalidation_hash VARCHAR(64),
    row_version BIGINT DEFAULT 1 NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT pk_dts_source_scope_states PRIMARY KEY (source_region, source_table, scope_kind, scope_level, scope_key),
    CONSTRAINT fk_dts_source_scope_state_active_snapshot FOREIGN KEY(active_snapshot_id, source_region, source_table, scope_kind, scope_level, scope_key) REFERENCES public.dts_source_scope_snapshots (snapshot_id, source_region, source_table, scope_kind, scope_level, scope_key) ON DELETE RESTRICT DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT fk_dts_source_scope_state_candidate_snapshot FOREIGN KEY(candidate_snapshot_id, source_region, source_table, scope_kind, scope_level, scope_key) REFERENCES public.dts_source_scope_snapshots (snapshot_id, source_region, source_table, scope_kind, scope_level, scope_key) ON DELETE RESTRICT DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT ck_dts_source_scope_state_identity CHECK (public.dts_source_scope_identity_valid_v2(source_region,source_table,scope_kind,scope_level,scope_key)),
    CONSTRAINT ck_dts_source_scope_state_value CHECK (state IN ('INCOMPLETE','LOADING','VERIFYING','COMPLETE','FAILED','STALE') AND row_version >= 1),
    CONSTRAINT ck_dts_source_scope_state_shape CHECK ((state = 'INCOMPLETE' AND active_snapshot_id IS NULL AND candidate_snapshot_id IS NULL AND completed_at IS NULL) OR (state IN ('LOADING','VERIFYING') AND candidate_snapshot_id IS NOT NULL) OR (state = 'COMPLETE' AND active_snapshot_id IS NOT NULL AND candidate_snapshot_id IS NULL AND completed_at IS NOT NULL AND invalidated_at IS NULL) OR (state = 'FAILED' AND candidate_snapshot_id IS NOT NULL) OR (state = 'STALE' AND active_snapshot_id IS NOT NULL AND candidate_snapshot_id IS NULL AND invalidated_at IS NOT NULL)),
    CONSTRAINT ck_dts_source_scope_state_invalidation_hash CHECK (last_invalidation_hash IS NULL OR last_invalidation_hash ~ '^[0-9a-f]{64}$')
);

COMMENT ON TABLE public.dts_source_scope_states IS 'Authoritative scope completeness state; only COMPLETE plus a COMPLETE active snapshot proves empty/false/zero.';

CREATE TABLE public.dts_source_scope_memberships (
    source_region VARCHAR(8) NOT NULL,
    source_table VARCHAR(128) NOT NULL,
    scope_kind VARCHAR(16) NOT NULL,
    scope_level VARCHAR(16) NOT NULL,
    scope_key VARCHAR(160) NOT NULL,
    source_key VARCHAR(512) NOT NULL,
    source_key_data JSONB NOT NULL,
    source_key_type VARCHAR(16) NOT NULL,
    source_key_numeric NUMERIC,
    source_key_text TEXT,
    active_snapshot_id VARCHAR(160) NOT NULL,
    snapshot_is_present BOOLEAN NOT NULL,
    snapshot_row_hash VARCHAR(64),
    dependency_keys JSONB NOT NULL,
    cdc_overlay_is_present BOOLEAN,
    cdc_overlay_row_hash VARCHAR(64),
    last_cdc_source_revision BIGINT,
    effective_is_present BOOLEAN GENERATED ALWAYS AS (coalesce(cdc_overlay_is_present,snapshot_is_present)) STORED NOT NULL,
    membership_revision BIGINT DEFAULT 1 NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT pk_dts_source_scope_memberships PRIMARY KEY (source_region, source_table, scope_kind, scope_level, scope_key, source_key),
    CONSTRAINT fk_dts_source_scope_membership_snapshot FOREIGN KEY(active_snapshot_id, source_region, source_table, scope_kind, scope_level, scope_key) REFERENCES public.dts_source_scope_snapshots (snapshot_id, source_region, source_table, scope_kind, scope_level, scope_key) ON DELETE RESTRICT,
    CONSTRAINT ck_dts_source_scope_membership_identity CHECK (public.dts_source_scope_identity_valid_v2(source_region,source_table,scope_kind,scope_level,scope_key)),
    CONSTRAINT ck_dts_source_scope_membership_key CHECK (public.dts_source_key_parts_valid_v2(source_key,source_key_data,source_key_type,source_key_numeric,source_key_text)),
    CONSTRAINT ck_dts_source_scope_membership_dependencies CHECK (public.dts_dependency_keys_valid_v2(source_region,dependency_keys)),
    CONSTRAINT ck_dts_source_scope_membership_evidence CHECK (((snapshot_is_present AND snapshot_row_hash ~ '^[0-9a-f]{64}$') OR (NOT snapshot_is_present AND snapshot_row_hash IS NULL)) AND ((cdc_overlay_is_present IS NULL AND cdc_overlay_row_hash IS NULL AND last_cdc_source_revision IS NULL) OR (cdc_overlay_is_present IS TRUE AND cdc_overlay_row_hash ~ '^[0-9a-f]{64}$' AND last_cdc_source_revision >= 1) OR (cdc_overlay_is_present IS FALSE AND cdc_overlay_row_hash IS NULL AND last_cdc_source_revision >= 1)) AND membership_revision >= 1)
);

COMMENT ON TABLE public.dts_source_scope_memberships IS 'Published snapshot baseline plus nullable CDC overlay for one typed source key in a source scope.';

CREATE INDEX ix_dts_source_scope_memberships_source_key ON public.dts_source_scope_memberships (source_region, source_table, source_key);

CREATE TABLE public.dts_source_scope_commands (
    command_id VARCHAR(160) NOT NULL,
    command_type VARCHAR(24) NOT NULL,
    request_hash VARCHAR(64) NOT NULL,
    snapshot_id VARCHAR(160),
    scope_identity JSONB NOT NULL,
    response_payload JSONB NOT NULL,
    executed_by VARCHAR(128) NOT NULL,
    executed_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT pk_dts_source_scope_commands PRIMARY KEY (command_id),
    CONSTRAINT ck_dts_source_scope_command_shape CHECK (command_type IN ('BEGIN','HEARTBEAT','VERIFY','ABORT','TAKEOVER','PUBLISH','INVALIDATE') AND request_hash ~ '^[0-9a-f]{64}$' AND jsonb_typeof(scope_identity) = 'object' AND jsonb_typeof(response_payload) = 'object')
);

COMMENT ON TABLE public.dts_source_scope_commands IS 'Append-only command idempotency ledger for response-lost-safe source-scope state transitions.';

CREATE TABLE public.dts_source_scope_transition_audits (
    audit_id BIGSERIAL NOT NULL,
    command_id VARCHAR(160) NOT NULL,
    snapshot_id VARCHAR(160),
    source_region VARCHAR(8) NOT NULL,
    source_table VARCHAR(128) NOT NULL,
    scope_kind VARCHAR(16) NOT NULL,
    scope_level VARCHAR(16) NOT NULL,
    scope_key VARCHAR(160) NOT NULL,
    from_state VARCHAR(16),
    to_state VARCHAR(16) NOT NULL,
    scope_row_version BIGINT NOT NULL,
    detail JSONB NOT NULL,
    occurred_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    actor VARCHAR(128) NOT NULL,
    CONSTRAINT pk_dts_source_scope_transition_audits PRIMARY KEY (audit_id),
    CONSTRAINT uq_dts_source_scope_transition_command UNIQUE (command_id),
    CONSTRAINT fk_dts_source_scope_transition_command FOREIGN KEY(command_id) REFERENCES public.dts_source_scope_commands (command_id) ON DELETE RESTRICT,
    CONSTRAINT ck_dts_source_scope_transition_shape CHECK (public.dts_source_scope_identity_valid_v2(source_region,source_table,scope_kind,scope_level,scope_key) AND to_state IN ('LOADING','VERIFYING','COMPLETE','FAILED','STALE') AND (from_state IS NULL OR from_state IN ('INCOMPLETE','LOADING','VERIFYING','COMPLETE','FAILED','STALE')) AND scope_row_version >= 1 AND jsonb_typeof(detail) = 'object')
);

COMMENT ON TABLE public.dts_source_scope_transition_audits IS 'Append-only source-scope state transition audit tied to one idempotent command.';

ALTER TABLE public.dts_source_table_publish_generations ADD CONSTRAINT fk_dts_source_publish_head_current_snapshot FOREIGN KEY(source_region, source_table, current_generation, current_snapshot_id) REFERENCES public.dts_source_scope_snapshots (source_region, source_table, published_generation, snapshot_id) ON DELETE RESTRICT DEFERRABLE INITIALLY DEFERRED;

ALTER TABLE public.dts_source_table_publish_generations ADD CONSTRAINT fk_dts_source_publish_head_candidate_snapshot FOREIGN KEY(source_region, source_table, active_candidate_snapshot_id) REFERENCES public.dts_source_scope_snapshots (source_region, source_table, snapshot_id) ON DELETE RESTRICT DEFERRABLE INITIALLY DEFERRED;

