                row_version=row_version+1,updated_at=clock_timestamp()
            WHERE control_id='PRIMARY' AND phase='WRITER_READY';
            IF NOT FOUND THEN
                RAISE EXCEPTION 'COMPAT_WRITER_NOT_READY';
            END IF;
        END
        $$;

