CREATE TABLE public.ops_case_recovery_events (
    recovery_event_id VARCHAR(160) NOT NULL,
    case_id VARCHAR(768) NOT NULL,
    source_ref VARCHAR(768) NOT NULL,
    event_id VARCHAR(512) NOT NULL,
    recovery_count BIGINT NOT NULL,
    work_status VARCHAR(24) NOT NULL,
    outbox_payload_sha256 VARCHAR(64) NOT NULL,
    outbox_row_version BIGINT NOT NULL,
    published_at TIMESTAMP WITH TIME ZONE NOT NULL,
    case_status_before VARCHAR(32) NOT NULL,
    case_status_after VARCHAR(32) NOT NULL,
    case_revision_after INTEGER NOT NULL,
    evidence JSONB NOT NULL,
    evidence_sha256 VARCHAR(64) NOT NULL,
    recorded_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT pk_ops_case_recovery_events PRIMARY KEY (recovery_event_id),
    CONSTRAINT uq_ops_case_recovery_work_generation UNIQUE (case_id, event_id, recovery_count),
    CONSTRAINT fk_ops_case_recovery_case FOREIGN KEY(case_id) REFERENCES public.ops_cases (case_id) ON DELETE RESTRICT,
    CONSTRAINT ck_ops_case_recovery_versions CHECK (recovery_count >= 1 AND outbox_row_version >= 1 AND case_revision_after >= 1),
    CONSTRAINT ck_ops_case_recovery_work_status CHECK (work_status='PUBLISHED'),
    CONSTRAINT ck_ops_case_recovery_hashes CHECK (outbox_payload_sha256 ~ '^[0-9a-f]{64}$' AND evidence_sha256 ~ '^[0-9a-f]{64}$' AND evidence_sha256=public.dts_canonical_json_sha256_v1(evidence))
);

COMMENT ON TABLE public.ops_case_recovery_events IS 'Append-only evidence that the original DTS v2 work reached PUBLISHED; DEAD to PENDING alone never creates this row.';

CREATE UNIQUE INDEX uq_ops_cases_source_ref_v2
        ON public.ops_cases(source_ref)
        WHERE source_ref IS NOT NULL;
        CREATE UNIQUE INDEX uq_ops_cases_completion_course_v2
