DROP TRIGGER IF EXISTS trg_task_assignment_write
          ON public.task_assignments;

        UPDATE public.task_assignments assignment
        SET materialization_seed_kind='LEGACY_FROZEN',
            materialization_seed_key=
              'legacy-assignment:' || assignment.assignment_id,
            materialization_seed_revision=0,
            materialization_template_revision=template.revision,
            materialization_plan_revision=0,
            eligibility_generation=0,
            eligible_since_at=assignment.assigned_at,
            teacher_copy_version_id=NULL,
            teacher_copy_config_key=NULL,
            teacher_execution_variant='LEGACY_FROZEN',
            plan_evidence_hash=public.dts_canonical_json_sha256_v1(
              jsonb_build_object(
                'protocol_version','legacy-assignment-evidence-v1',
                'assignment_id',assignment.assignment_id,
                'evidence_snapshot',assignment.evidence_snapshot,
                'eligibility_time_source','LEGACY_ASSIGNED_AT'
              )
            ),
            materialization_seed_payload_hash=
              public.dts_canonical_json_sha256_v1(
                jsonb_build_object(
                  'why',assignment.why,
                  'display_title',assignment.display_title,
                  'evidence_snapshot',assignment.evidence_snapshot,
                  'template_version_id',assignment.template_version_id,
                  'template_revision',template.revision,
                  'teacher_execution_variant','LEGACY_FROZEN',
                  'eligibility_generation',0,
                  'eligible_since_at',to_char(
                    assignment.assigned_at AT TIME ZONE 'UTC',
                    'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'
                  ),
                  'due_at',CASE WHEN assignment.due_at IS NULL THEN NULL ELSE
                    to_char(assignment.due_at AT TIME ZONE 'UTC',
                      'YYYY-MM-DD"T"HH24:MI:SS.US"Z"') END,
                  'timezone_used',assignment.timezone_used,
                  'timezone_source',assignment.timezone_source,
                  'timezone_verified_at',CASE
                    WHEN assignment.timezone_verified_at IS NULL THEN NULL ELSE
                      to_char(assignment.timezone_verified_at AT TIME ZONE 'UTC',
                        'YYYY-MM-DD"T"HH24:MI:SS.US"Z"') END,
                  'teacher_copy_version_id',NULL,
                  'teacher_copy_config_key',NULL
                )
              )
        FROM public.task_templates template
        WHERE assignment.task_kind='PERSONALIZED_IMPROVEMENT'
          AND template.row_id=assignment.template_version_id;

ALTER TABLE public.task_assignments ADD CONSTRAINT ck_task_assignment_materialization_contract_v2 CHECK ((task_kind='FIXED_GROWTH' AND materialization_seed_kind IS NULL AND materialization_seed_key IS NULL AND materialization_seed_revision IS NULL AND materialization_seed_payload_hash IS NULL AND materialization_template_revision IS NULL AND materialization_plan_revision IS NULL AND eligibility_generation IS NULL AND eligible_since_at IS NULL AND teacher_copy_version_id IS NULL AND teacher_copy_config_key IS NULL AND teacher_execution_variant IS NULL AND plan_evidence_hash IS NULL) OR (task_kind='PERSONALIZED_IMPROVEMENT' AND materialization_seed_kind IN ('LEGACY_FROZEN','LEGACY_COMPAT','MATCH') AND btrim(materialization_seed_key)<>'' AND materialization_seed_revision>=0 AND materialization_seed_payload_hash ~ '^[0-9a-f]{64}$' AND materialization_template_revision>=1 AND materialization_plan_revision>=0 AND eligibility_generation>=0 AND eligible_since_at IS NOT NULL AND teacher_execution_variant IN ('LEGACY_FROZEN','GENERAL','TEACHING_ENVIRONMENT_PHOTO') AND plan_evidence_hash ~ '^[0-9a-f]{64}$' AND ((materialization_seed_kind='LEGACY_FROZEN' AND materialization_seed_revision=0 AND materialization_plan_revision=0 AND eligibility_generation=0 AND teacher_execution_variant='LEGACY_FROZEN' AND teacher_copy_version_id IS NULL AND teacher_copy_config_key IS NULL) OR (materialization_seed_kind IN ('LEGACY_COMPAT','MATCH') AND teacher_copy_version_id IS NOT NULL AND teacher_copy_config_key='teacher_personalized_copy'))) );

CREATE INDEX ix_task_assignment_materialization_seed_v2 ON public.task_assignments (materialization_seed_kind, materialization_seed_key);

