CREATE FUNCTION public.append_dts_v2_notification_lifecycle_event_v1(
          p_notification_id text,p_delivery_status text,p_transition text,
          p_trigger_match_id text,p_triggering_event_id text,
          p_plan_evidence_hash text
        ) RETURNS void
        LANGUAGE plpgsql
        SECURITY DEFINER
        SET search_path=pg_catalog,public
        AS $$
        DECLARE event_payload jsonb;
        DECLARE request_hash_value text;
        DECLARE event_id_value text;
        DECLARE inserted_count integer;
        BEGIN
          IF p_delivery_status NOT IN ('STORED','CANCELLED')
             OR p_transition NOT IN (
               'CREATED_STORED','SOURCE_CANCELLED','SOURCE_RESTORED'
             )
             OR nullif(btrim(p_notification_id),'') IS NULL
             OR nullif(btrim(p_trigger_match_id),'') IS NULL
             OR nullif(btrim(p_triggering_event_id),'') IS NULL
             OR p_plan_evidence_hash !~ '^[0-9a-f]{64}$' THEN
            RAISE EXCEPTION 'DTS_V2_NOTIFICATION_EVENT_INVALID'
              USING ERRCODE='22023';
          END IF;
          event_payload:=jsonb_build_object(
            'protocol_version','notification-lifecycle-v2',
            'transition',p_transition,
            'trigger_match_id',p_trigger_match_id,
            'triggering_event_id',p_triggering_event_id,
            'plan_evidence_hash',p_plan_evidence_hash,
            'actor','DTS_V2_OUTBOX'
          );
          request_hash_value:=public.dts_canonical_json_sha256_v1(
            event_payload
          );
          event_id_value:='v2nevt:' || encode(sha256(convert_to(
            p_notification_id || ':' || request_hash_value,'UTF8'
          )),'hex');
          INSERT INTO public.notification_events(
            notification_event_id,notification_id,delivery_status,
            occurred_at,failure_reason,request_hash,payload
          ) VALUES (
            event_id_value,p_notification_id,p_delivery_status,
            transaction_timestamp(),NULL,request_hash_value,event_payload
          ) ON CONFLICT DO NOTHING;
          GET DIAGNOSTICS inserted_count=ROW_COUNT;
          IF inserted_count=0 AND NOT EXISTS(
            SELECT 1 FROM public.notification_events
            WHERE notification_event_id=event_id_value
              AND notification_id=p_notification_id
              AND delivery_status=p_delivery_status
              AND request_hash=request_hash_value
              AND payload=event_payload
          ) THEN
            RAISE EXCEPTION 'DTS_V2_NOTIFICATION_EVENT_CONFLICT'
              USING ERRCODE='23514';
          END IF;
        END
        $$;

        CREATE FUNCTION public.append_dts_v2_case_lifecycle_audit_v1(
          p_case_id text,p_teacher_id text,p_event_type text,
          p_previous_status text,p_status text,p_trigger_match_id text,
          p_triggering_event_id text,p_plan_evidence_hash text
        ) RETURNS void
        LANGUAGE plpgsql
        SECURITY DEFINER
        SET search_path=pg_catalog,public
        AS $$
        DECLARE audit_payload jsonb;
        DECLARE audit_hash text;
        DECLARE audit_id text;
        DECLARE inserted_count integer;
        BEGIN
          IF p_event_type NOT IN (
               'DTS_V2_SEVERE_COMPLAINT_CASE_CREATED',
               'DTS_V2_SEVERE_COMPLAINT_CASE_SOURCE_CANCELLED',
               'DTS_V2_SEVERE_COMPLAINT_CASE_SOURCE_RESTORED'
             )
             OR nullif(btrim(p_case_id),'') IS NULL
             OR nullif(btrim(p_teacher_id),'') IS NULL
             OR nullif(btrim(p_status),'') IS NULL
             OR nullif(btrim(p_trigger_match_id),'') IS NULL
             OR nullif(btrim(p_triggering_event_id),'') IS NULL
             OR p_plan_evidence_hash !~ '^[0-9a-f]{64}$' THEN
            RAISE EXCEPTION 'DTS_V2_CASE_AUDIT_INVALID'
              USING ERRCODE='22023';
          END IF;
          audit_payload:=jsonb_build_object(
            'protocol_version','non-task-case-lifecycle-v1',
            'case_id',p_case_id,
            'previous_status',p_previous_status,
            'status',p_status,
            'trigger_match_id',p_trigger_match_id,
            'triggering_event_id',p_triggering_event_id,
            'plan_evidence_hash',p_plan_evidence_hash
          );
          audit_hash:=public.dts_canonical_json_sha256_v1(audit_payload);
          audit_id:='audit:v2-output:' || audit_hash;
          INSERT INTO public.audit_events(
            event_id,event_type,teacher_id,task_id,case_id,occurred_at,
            actor_type,payload_hash,payload
          ) VALUES (
            audit_id,p_event_type,p_teacher_id,NULL,p_case_id,
            transaction_timestamp(),'DTS_V2_OUTBOX',audit_hash,audit_payload
          ) ON CONFLICT DO NOTHING;
          GET DIAGNOSTICS inserted_count=ROW_COUNT;
          IF inserted_count=0 AND NOT EXISTS(
            SELECT 1 FROM public.audit_events
            WHERE event_id=audit_id AND event_type=p_event_type
              AND teacher_id=p_teacher_id AND case_id=p_case_id
              AND payload_hash=audit_hash AND payload=audit_payload
          ) THEN
            RAISE EXCEPTION 'DTS_V2_CASE_AUDIT_CONFLICT'
              USING ERRCODE='23514';
          END IF;
        END
        $$;

        REVOKE ALL ON FUNCTION
          public.append_dts_v2_notification_lifecycle_event_v1(
            text,text,text,text,text,text
          ),
          public.append_dts_v2_case_lifecycle_audit_v1(
            text,text,text,text,text,text,text,text
          )
        FROM PUBLIC;

CREATE FUNCTION public.reconcile_course_non_task_outputs_v2(
          p_source_region text,p_source_appoint_id text,
          p_expected_course_aggregate_revision bigint,
          p_projection_generation bigint,p_triggering_event_id text,
          p_expected_command_sha256 text
        ) RETURNS jsonb
        LANGUAGE plpgsql
        SECURITY DEFINER
        SET search_path=pg_catalog,public
        AS $$
        DECLARE guarded_generation bigint;
        DECLARE aggregate_row public.domain_aggregate_revisions%ROWTYPE;
        DECLARE command_payload jsonb;
        DECLARE command_hash text;
        DECLARE match_row public.personalized_trigger_matches%ROWTYPE;
        DECLARE notification_row public.notifications%ROWTYPE;
        DECLARE case_row public.ops_cases%ROWTYPE;
        DECLARE output_found boolean;
        DECLARE output_id_value text;
        DECLARE output_payload jsonb;
        DECLARE lifecycle_payload jsonb;
        DECLARE priority_value text;
        DECLARE transitioned boolean;
        DECLARE notifications_created integer:=0;
        DECLARE notifications_cancelled integer:=0;
        DECLARE notifications_restored integer:=0;
        DECLARE cases_created integer:=0;
        DECLARE cases_cancelled integer:=0;
        DECLARE cases_restored integer:=0;
        DECLARE matches_linked integer:=0;
        DECLARE unchanged_count integer:=0;
        BEGIN
          guarded_generation:=public.dts_v2_runtime_primary_guard_v1(
            'COURSE'
          );
          IF guarded_generation IS NULL
             OR guarded_generation<>p_projection_generation THEN
            RAISE EXCEPTION 'DTS_V2_NON_TASK_OUTPUT_GENERATION_CHANGED'
              USING ERRCODE='40001';
          END IF;
          IF p_source_region NOT IN ('dom','ovs')
             OR nullif(btrim(p_source_appoint_id),'') IS NULL
             OR p_expected_course_aggregate_revision<1
             OR p_projection_generation<1
             OR nullif(btrim(p_triggering_event_id),'') IS NULL
             OR p_expected_command_sha256 !~ '^[0-9a-f]{64}$' THEN
            RAISE EXCEPTION 'DTS_V2_NON_TASK_OUTPUT_REQUEST_INVALID'
              USING ERRCODE='22023';
          END IF;
          command_payload:=jsonb_build_object(
            'protocol_version','course-non-task-output-command-v1',
            'source_region',p_source_region,
            'source_appoint_id',p_source_appoint_id,
            'aggregate_revision',p_expected_course_aggregate_revision,
            'projection_generation',p_projection_generation,
            'triggering_event_id',p_triggering_event_id
          );
          command_hash:=public.dts_canonical_json_sha256_v1(command_payload);
          IF command_hash<>p_expected_command_sha256 THEN
            RAISE EXCEPTION 'DTS_V2_NON_TASK_OUTPUT_COMMAND_HASH_MISMATCH'
              USING ERRCODE='23514';
          END IF;

          SELECT * INTO aggregate_row
          FROM public.domain_aggregate_revisions
          WHERE aggregate_type='COURSE'
            AND canonical_key=jsonb_build_object(
              'source_region',p_source_region,
              'source_appoint_id',p_source_appoint_id
            )
          FOR SHARE;
          IF NOT FOUND
             OR aggregate_row.revision<>
                  p_expected_course_aggregate_revision THEN
            RAISE EXCEPTION 'DTS_V2_NON_TASK_OUTPUT_COURSE_REVISION_CHANGED'
              USING ERRCODE='40001';
          END IF;
          IF NOT EXISTS(
            SELECT 1 FROM public.outbox_events event
            WHERE event.event_id=p_triggering_event_id
              AND event.aggregate_type='COURSE'
              AND event.aggregate_id=aggregate_row.aggregate_id
              AND event.event_type='source_wide.changed.v2'
              AND (event.payload->>'aggregate_revision')::bigint=
                    p_expected_course_aggregate_revision
          ) THEN
            RAISE EXCEPTION 'DTS_V2_NON_TASK_OUTPUT_EVENT_MISMATCH'
              USING ERRCODE='23503';
          END IF;

          FOR match_row IN
            SELECT * FROM public.personalized_trigger_matches match
            WHERE match.source_region=p_source_region
              AND match.source_appoint_id=p_source_appoint_id
              AND match.match_kind IN (
                'COMPLAINT_NETWORK_NOTIFICATION','SEVERE_COMPLAINT',
                'CAMERA_OFF_NOTIFICATION'
              )
            ORDER BY match.dedupe_key_sort_bytes
            FOR UPDATE
          LOOP
            transitioned:=false;
            IF match_row.materialization_origin<>'V2_LIVE'
               OR match_row.created_projection_generation<1
               OR match_row.plan_evidence_hash !~ '^[0-9a-f]{64}$'
               OR public.dts_canonical_json_sha256_v1(
                    match_row.plan_evidence
                  )<>match_row.plan_evidence_hash
               OR match_row.output_key IS NULL
               OR nullif(btrim(match_row.output_key),'') IS NULL THEN
              RAISE EXCEPTION 'DTS_V2_NON_TASK_OUTPUT_MATCH_INVALID'
                USING ERRCODE='23514';
            END IF;
            IF match_row.match_kind='SEVERE_COMPLAINT' THEN
              IF match_row.output_type<>'OPS_CASE'
                 OR match_row.output_key NOT LIKE 'complaint-case:%' THEN
                RAISE EXCEPTION 'DTS_V2_NON_TASK_OUTPUT_MATCH_INVALID'
                  USING ERRCODE='23514';
              END IF;
            ELSIF match_row.output_type<>'NOTIFICATION'
               OR NOT (
                 (match_row.match_kind='COMPLAINT_NETWORK_NOTIFICATION'
                  AND match_row.output_key LIKE 'complaint-notification:%')
                 OR
                 (match_row.match_kind='CAMERA_OFF_NOTIFICATION'
                  AND match_row.output_key LIKE 'camera-notification:%')
               ) THEN
              RAISE EXCEPTION 'DTS_V2_NON_TASK_OUTPUT_MATCH_INVALID'
                USING ERRCODE='23514';
            END IF;

            PERFORM pg_advisory_xact_lock(hashtextextended(
              'DTS_V2_NON_TASK_OUTPUT:' || match_row.output_key,0
            ));
            IF match_row.match_status IN ('MATCHED','MATERIALIZED') THEN
              IF match_row.output_type='NOTIFICATION' THEN
                output_id_value:=match_row.notification_id;
                output_found:=false;
                IF output_id_value IS NOT NULL THEN
                  SELECT * INTO notification_row
                  FROM public.notifications
                  WHERE notification_id=output_id_value FOR UPDATE;
                  output_found:=FOUND;
                ELSE
                  SELECT * INTO notification_row
                  FROM public.notifications
                  WHERE source_ref=match_row.output_key FOR UPDATE;
                  output_found:=FOUND;
                  IF output_found THEN
                    output_id_value:=notification_row.notification_id;
                  END IF;
                END IF;
                IF NOT output_found THEN
                  output_id_value:='v2notif:' || encode(sha256(convert_to(
                    match_row.output_key,'UTF8'
                  )),'hex');
                  IF EXISTS(
                    SELECT 1 FROM public.notifications
                    WHERE notification_id=output_id_value
                  ) THEN
                    RAISE EXCEPTION 'DTS_V2_NOTIFICATION_ID_CONFLICT'
                      USING ERRCODE='23514';
                  END IF;
                  lifecycle_payload:=jsonb_build_object(
                    'auto_cancelled',false,
                    'trigger_match_id',match_row.trigger_match_id,
                    'source_ref',match_row.output_key
                  );
                  output_payload:=jsonb_build_object(
                    'protocol_version','dts-v2-taskless-notification-v1',
                    'title','In-Class Quality Alert',
                    'body',CASE match_row.match_kind
                      WHEN 'CAMERA_OFF_NOTIFICATION' THEN
                        'Evidence: the camera was off for this lesson. Please review the class setup and keep the camera on as required.'
                      ELSE
                        'Evidence: this lesson received a network or device complaint. Please review the class setup and connection quality.'
                      END,
                    'source_ref',match_row.output_key,
                    'rule_code',match_row.trigger_code,
                    'trigger_match_id',match_row.trigger_match_id,
                    'plan_evidence',match_row.plan_evidence,
                    'plan_evidence_hash',match_row.plan_evidence_hash,
                    'materialization_origin','DTS_V2',
                    'projection_generation',p_projection_generation,
                    'source_lifecycle',lifecycle_payload
                  );
                  INSERT INTO public.notifications(
                    notification_id,task_id,source_ref,teacher_id,channel,
                    priority,status,requested_at,stored_at,read_at,
                    clicked_at,response_due_at,failure_reason,payload
                  ) VALUES (
                    output_id_value,NULL,match_row.output_key,
                    match_row.teacher_id,'IN_APP','P1','STORED',
                    transaction_timestamp(),transaction_timestamp(),
                    NULL,NULL,NULL,NULL,output_payload
                  );
                  PERFORM public.append_dts_v2_notification_lifecycle_event_v1(
                    output_id_value,'STORED','CREATED_STORED',
                    match_row.trigger_match_id,p_triggering_event_id,
                    match_row.plan_evidence_hash
                  );
                  notifications_created:=notifications_created+1;
                  transitioned:=true;
                  SELECT * INTO notification_row
                  FROM public.notifications
                  WHERE notification_id=output_id_value;
                END IF;
                IF notification_row.source_ref IS DISTINCT FROM
                     match_row.output_key
                   OR notification_row.teacher_id IS DISTINCT FROM
                     match_row.teacher_id
                   OR notification_row.task_id IS NOT NULL THEN
                  RAISE EXCEPTION 'DTS_V2_NOTIFICATION_IDENTITY_CONFLICT'
                    USING ERRCODE='23514';
                END IF;
                IF notification_row.status='CANCELLED'
                   AND notification_row.payload->'source_lifecycle'
                         ->>'auto_cancelled'='true'
                   AND notification_row.payload->'source_lifecycle'
                         ->>'trigger_match_id'=match_row.trigger_match_id
                   AND notification_row.payload->'source_lifecycle'
                         ->>'source_ref'=match_row.output_key THEN
                  lifecycle_payload:=
                    notification_row.payload->'source_lifecycle' ||
                    jsonb_build_object(
                      'auto_cancelled',false,
                      'restored_at',transaction_timestamp(),
                      'restored_by_event_id',p_triggering_event_id
                    );
                  UPDATE public.notifications
                  SET status='STORED',failure_reason=NULL,
                      payload=payload || jsonb_build_object(
                        'source_lifecycle',lifecycle_payload
                      )
                  WHERE notification_id=output_id_value;
                  PERFORM public.append_dts_v2_notification_lifecycle_event_v1(
                    output_id_value,'STORED','SOURCE_RESTORED',
                    match_row.trigger_match_id,p_triggering_event_id,
                    match_row.plan_evidence_hash
                  );
                  notifications_restored:=notifications_restored+1;
                  transitioned:=true;
                END IF;
                IF match_row.notification_id IS NULL
                   OR match_row.match_status<>'MATERIALIZED' THEN
                  UPDATE public.personalized_trigger_matches
                  SET notification_id=output_id_value,
                      match_status='MATERIALIZED',
                      materialized_at=coalesce(
                        materialized_at,transaction_timestamp()
                      ),match_revision=match_revision+1,
                      last_transition_at=transaction_timestamp(),
                      updated_at=transaction_timestamp()
                  WHERE trigger_match_id=match_row.trigger_match_id;
                  matches_linked:=matches_linked+1;
                  transitioned:=true;
                END IF;
              ELSE
                output_id_value:=match_row.ops_case_id;
                output_found:=false;
                IF output_id_value IS NOT NULL THEN
                  SELECT * INTO case_row FROM public.ops_cases
                  WHERE case_id=output_id_value FOR UPDATE;
                  output_found:=FOUND;
                ELSE
                  SELECT * INTO case_row FROM public.ops_cases
                  WHERE source_ref=match_row.output_key FOR UPDATE;
                  output_found:=FOUND;
                  IF output_found THEN output_id_value:=case_row.case_id;
                  END IF;
                END IF;
                IF NOT output_found THEN
                  output_id_value:='v2case:' || encode(sha256(convert_to(
                    match_row.output_key,'UTF8'
                  )),'hex');
                  IF EXISTS(
                    SELECT 1 FROM public.ops_cases
                    WHERE case_id=output_id_value
                  ) THEN
                    RAISE EXCEPTION 'DTS_V2_CASE_ID_CONFLICT'
                      USING ERRCODE='23514';
                  END IF;
                  priority_value:=CASE
                    WHEN match_row.plan_evidence->>'severity_rank'='0'
                      THEN 'P0' ELSE 'P1' END;
                  lifecycle_payload:=jsonb_build_object(
                    'auto_cancelled',false,
                    'trigger_match_id',match_row.trigger_match_id,
                    'source_ref',match_row.output_key
                  );
                  output_payload:=jsonb_build_object(
                    'protocol_version','dts-v2-severe-complaint-case-v1',
                    'title','Severe Complaint Review',
                    'summary','A severe complaint requires operations review.',
                    'source_ref',match_row.output_key,
                    'rule_code',match_row.trigger_code,
                    'trigger_match_id',match_row.trigger_match_id,
                    'plan_evidence',match_row.plan_evidence,
                    'plan_evidence_hash',match_row.plan_evidence_hash,
                    'materialization_origin','DTS_V2',
                    'projection_generation',p_projection_generation,
                    'source_lifecycle',lifecycle_payload
                  );
                  INSERT INTO public.ops_cases(
                    case_id,case_type,teacher_id,task_id,priority,status,
                    source_reason,external_action_status,created_at,payload,
                    updated_at,source_ref,source_region,source_appoint_id,
                    case_revision,row_version,evidence_fingerprint,
                    recovery_evidence_count,last_recovery_event_id,
                    last_recovery_count,last_recovered_at
                  ) VALUES (
                    output_id_value,'SEVERE_COMPLAINT',
                    match_row.teacher_id,NULL,priority_value,'OPEN',
                    match_row.trigger_code,'OPS_REVIEW_REQUIRED',
                    transaction_timestamp(),output_payload,
                    transaction_timestamp(),match_row.output_key,
                    p_source_region,p_source_appoint_id,1,1,
                    match_row.plan_evidence_hash,0,NULL,NULL,NULL
                  );
                  PERFORM public.append_dts_v2_case_lifecycle_audit_v1(
                    output_id_value,match_row.teacher_id,
                    'DTS_V2_SEVERE_COMPLAINT_CASE_CREATED',NULL,'OPEN',
                    match_row.trigger_match_id,p_triggering_event_id,
                    match_row.plan_evidence_hash
                  );
                  cases_created:=cases_created+1;
                  transitioned:=true;
                  SELECT * INTO case_row FROM public.ops_cases
                  WHERE case_id=output_id_value;
                END IF;
                IF case_row.source_ref IS DISTINCT FROM match_row.output_key
                   OR case_row.case_type<>'SEVERE_COMPLAINT'
                   OR case_row.teacher_id IS DISTINCT FROM
                        match_row.teacher_id
                   OR case_row.source_region IS DISTINCT FROM p_source_region
                   OR case_row.source_appoint_id IS DISTINCT FROM
                        p_source_appoint_id THEN
                  RAISE EXCEPTION 'DTS_V2_CASE_IDENTITY_CONFLICT'
                    USING ERRCODE='23514';
                END IF;
                IF case_row.status='CANCELLED'
                   AND case_row.external_action_status=
                         'SOURCE_EVIDENCE_SUPERSEDED'
                   AND case_row.payload->'source_lifecycle'
                         ->>'auto_cancelled'='true'
                   AND case_row.payload->'source_lifecycle'
                         ->>'trigger_match_id'=match_row.trigger_match_id THEN
                  lifecycle_payload:=case_row.payload->'source_lifecycle' ||
                    jsonb_build_object(
                      'auto_cancelled',false,
                      'restored_at',transaction_timestamp(),
                      'restored_by_event_id',p_triggering_event_id
                    );
                  UPDATE public.ops_cases
                  SET status='OPEN',
                      external_action_status='OPS_REVIEW_REQUIRED',
                      payload=payload || jsonb_build_object(
                        'source_lifecycle',lifecycle_payload
                      ),case_revision=case_revision+1,
                      row_version=row_version+1,
                      updated_at=transaction_timestamp()
                  WHERE case_id=output_id_value;
                  PERFORM public.append_dts_v2_case_lifecycle_audit_v1(
                    output_id_value,match_row.teacher_id,
                    'DTS_V2_SEVERE_COMPLAINT_CASE_SOURCE_RESTORED',
                    'CANCELLED','OPEN',match_row.trigger_match_id,
                    p_triggering_event_id,match_row.plan_evidence_hash
                  );
                  cases_restored:=cases_restored+1;
                  transitioned:=true;
                END IF;
                IF match_row.ops_case_id IS NULL
                   OR match_row.match_status<>'MATERIALIZED' THEN
                  UPDATE public.personalized_trigger_matches
                  SET ops_case_id=output_id_value,
                      match_status='MATERIALIZED',
                      materialized_at=coalesce(
                        materialized_at,transaction_timestamp()
                      ),match_revision=match_revision+1,
                      last_transition_at=transaction_timestamp(),
                      updated_at=transaction_timestamp()
                  WHERE trigger_match_id=match_row.trigger_match_id;
                  matches_linked:=matches_linked+1;
                  transitioned:=true;
                END IF;
              END IF;
            ELSIF match_row.match_status='SUPPRESSED' THEN
              IF match_row.output_type='NOTIFICATION'
                 AND match_row.notification_id IS NOT NULL THEN
                SELECT * INTO notification_row
                FROM public.notifications
                WHERE notification_id=match_row.notification_id FOR UPDATE;
                IF NOT FOUND
                   OR notification_row.source_ref IS DISTINCT FROM
                        match_row.output_key
                   OR notification_row.teacher_id IS DISTINCT FROM
                        match_row.teacher_id
                   OR notification_row.task_id IS NOT NULL THEN
                  RAISE EXCEPTION 'DTS_V2_NOTIFICATION_IDENTITY_CONFLICT'
                    USING ERRCODE='23514';
                END IF;
                IF notification_row.status='STORED' THEN
                  lifecycle_payload:=coalesce(
                    notification_row.payload->'source_lifecycle',
                    '{}'::jsonb
                  ) || jsonb_build_object(
                    'auto_cancelled',true,
                    'cancelled_at',transaction_timestamp(),
                    'cancelled_by_event_id',p_triggering_event_id,
                    'trigger_match_id',match_row.trigger_match_id,
                    'source_ref',match_row.output_key
                  );
                  UPDATE public.notifications
                  SET status='CANCELLED',payload=payload ||
                    jsonb_build_object('source_lifecycle',lifecycle_payload)
                  WHERE notification_id=match_row.notification_id;
                  PERFORM public.append_dts_v2_notification_lifecycle_event_v1(
                    match_row.notification_id,'CANCELLED',
                    'SOURCE_CANCELLED',match_row.trigger_match_id,
                    p_triggering_event_id,match_row.plan_evidence_hash
                  );
                  notifications_cancelled:=notifications_cancelled+1;
                  transitioned:=true;
                END IF;
              ELSIF match_row.output_type='OPS_CASE'
                 AND match_row.ops_case_id IS NOT NULL THEN
                SELECT * INTO case_row FROM public.ops_cases
                WHERE case_id=match_row.ops_case_id FOR UPDATE;
                IF NOT FOUND
                   OR case_row.source_ref IS DISTINCT FROM match_row.output_key
                   OR case_row.case_type<>'SEVERE_COMPLAINT'
                   OR case_row.teacher_id IS DISTINCT FROM
                        match_row.teacher_id
                   OR case_row.source_region IS DISTINCT FROM p_source_region
                   OR case_row.source_appoint_id IS DISTINCT FROM
                        p_source_appoint_id THEN
                  RAISE EXCEPTION 'DTS_V2_CASE_IDENTITY_CONFLICT'
                    USING ERRCODE='23514';
                END IF;
                IF case_row.status='OPEN' THEN
                  lifecycle_payload:=coalesce(
                    case_row.payload->'source_lifecycle','{}'::jsonb
                  ) || jsonb_build_object(
                    'auto_cancelled',true,
                    'cancelled_at',transaction_timestamp(),
                    'cancelled_by_event_id',p_triggering_event_id,
                    'trigger_match_id',match_row.trigger_match_id,
                    'source_ref',match_row.output_key
                  );
                  UPDATE public.ops_cases
                  SET status='CANCELLED',
                      external_action_status=
                        'SOURCE_EVIDENCE_SUPERSEDED',
                      payload=payload || jsonb_build_object(
                        'source_lifecycle',lifecycle_payload
                      ),case_revision=case_revision+1,
                      row_version=row_version+1,
                      updated_at=transaction_timestamp()
                  WHERE case_id=match_row.ops_case_id;
                  PERFORM public.append_dts_v2_case_lifecycle_audit_v1(
                    match_row.ops_case_id,match_row.teacher_id,
                    'DTS_V2_SEVERE_COMPLAINT_CASE_SOURCE_CANCELLED',
                    'OPEN','CANCELLED',match_row.trigger_match_id,
                    p_triggering_event_id,match_row.plan_evidence_hash
                  );
                  cases_cancelled:=cases_cancelled+1;
                  transitioned:=true;
                END IF;
              END IF;
            ELSE
              RAISE EXCEPTION 'DTS_V2_NON_TASK_OUTPUT_MATCH_STATUS_INVALID'
                USING ERRCODE='23514';
            END IF;
            IF NOT transitioned THEN
              unchanged_count:=unchanged_count+1;
            END IF;
          END LOOP;

          RETURN jsonb_build_object(
            'protocol_version','course-non-task-output-v1',
            'command_sha256',command_hash,
            'counts',jsonb_build_object(
              'notifications_created',notifications_created,
              'notifications_cancelled',notifications_cancelled,
              'notifications_restored',notifications_restored,
              'cases_created',cases_created,
              'cases_cancelled',cases_cancelled,
              'cases_restored',cases_restored,
              'matches_linked',matches_linked,
              'unchanged',unchanged_count
            )
          );
        END
        $$;

        REVOKE ALL ON FUNCTION
          public.reconcile_course_non_task_outputs_v2(
            text,text,bigint,bigint,text,text
          ) FROM PUBLIC;
        GRANT EXECUTE ON FUNCTION
          public.reconcile_course_non_task_outputs_v2(
            text,text,bigint,bigint,text,text
          ) TO tit_growth_app;

        -- personalized_trigger_matches, notifications, ops_cases and
        -- audit_events belong to the existing tit_growth_app CRUD contract.
        -- Only the append-only notification history remains non-writable.
        REVOKE UPDATE,DELETE,TRUNCATE ON TABLE public.notification_events
        FROM tit_growth_app;

UPDATE alembic_version SET version_num='20260822_93_non_task_outputs' WHERE alembic_version.version_num = '20260822_92_runtime_course_health';

-- Running upgrade 20260822_93_non_task_outputs -> 20260822_94_complaint_catalog_fanout

DO $$
        DECLARE relation_name text;
        BEGIN
          FOREACH relation_name IN ARRAY ARRAY[
            'complaint_rule_imports','complaint_category_rules',
            'source_course_complaints','personalized_trigger_matches',
            'domain_aggregate_revisions','outbox_events','dts_dirty_keys',
            'dts_dirty_key_inputs','audit_events'
          ] LOOP
            IF to_regclass('public.' || relation_name) IS NULL THEN
              RAISE EXCEPTION
                'DTS_V2_COMPLAINT_CATALOG_PREREQUISITE_MISSING:%',
                relation_name;
            END IF;
          END LOOP;
          IF to_regprocedure(
               'public.dts_canonical_json_sha256_v1(jsonb)'
             ) IS NULL
             OR to_regprocedure(
               'public._upsert_dts_dirty_key_input_v2('
               'text,text,text,text,text,jsonb,bigint,text)'
             ) IS NULL
             OR to_regrole('tit_growth_app') IS NULL THEN
            RAISE EXCEPTION
              'DTS_V2_COMPLAINT_CATALOG_PREREQUISITE_MISSING';
          END IF;
          IF to_regprocedure(
               'public.publish_complaint_rule_import_v2(text,bigint,text)'
             ) IS NOT NULL
             OR to_regprocedure(
               'public.enqueue_complaint_category_course_fanout_v2('
               'text,bigint,text,text)'
             ) IS NOT NULL THEN
            RAISE EXCEPTION 'DTS_V2_COMPLAINT_CATALOG_ALREADY_INSTALLED';
          END IF;
          IF (SELECT count(*) FROM public.complaint_rule_imports)>1 THEN
            RAISE EXCEPTION
              'DTS_V2_COMPLAINT_CATALOG_LEGACY_ACTIVE_AMBIGUOUS';
          END IF;
        END
        $$;

        DO $$
        BEGIN
          IF to_regrole('tit_growth_app') IS NULL THEN
            RAISE EXCEPTION
              'required application role is missing: tit_growth_app';
          END IF;
          IF EXISTS (
            SELECT 1 FROM pg_roles WHERE rolname='tit_growth_app'
              AND (NOT rolcanlogin OR rolinherit OR rolsuper OR rolcreatedb
                   OR rolcreaterole OR rolreplication OR rolbypassrls)
          ) THEN
            RAISE EXCEPTION
              'tit_growth_app must be a restricted NOINHERIT LOGIN role';
          END IF;
        END
        $$;

        LOCK TABLE public.complaint_rule_imports,
          public.complaint_category_rules,
          public.source_course_complaints,
          public.personalized_trigger_matches
        IN SHARE ROW EXCLUSIVE MODE;

ALTER TABLE public.complaint_rule_imports ADD COLUMN status VARCHAR(16);

ALTER TABLE public.complaint_rule_imports ADD COLUMN publication_revision BIGINT;

ALTER TABLE public.complaint_rule_imports ADD COLUMN activation_generation BIGINT;

ALTER TABLE public.complaint_rule_imports ADD COLUMN row_count INTEGER;

ALTER TABLE public.complaint_rule_imports ADD COLUMN content_hash VARCHAR(64);

ALTER TABLE public.complaint_rule_imports ADD COLUMN published_at TIMESTAMP WITH TIME ZONE;

ALTER TABLE public.complaint_rule_imports ADD COLUMN retired_at TIMESTAMP WITH TIME ZONE;

ALTER TABLE public.personalized_trigger_matches ADD COLUMN complaint_rule_source_sha256 VARCHAR(64);

ALTER TABLE public.personalized_trigger_matches DROP CONSTRAINT fk_personalized_trigger_match_complaint_rule;

ALTER TABLE public.source_course_complaints DROP CONSTRAINT fk_source_course_complaint_rule_version;

CREATE TEMP TABLE complaint_rule_id_rekey_v94(
          old_rule_id text PRIMARY KEY,
          new_rule_id text NOT NULL UNIQUE,
          source_sha256 text NOT NULL
        ) ON COMMIT DROP;
        INSERT INTO complaint_rule_id_rekey_v94(
          old_rule_id,new_rule_id,source_sha256
        )
        SELECT rule_id,
          'complaint-rule:' || lower(source_sha256) || ':' ||
            source_row_number::text,
          lower(source_sha256)
        FROM public.complaint_category_rules;

        UPDATE public.complaint_category_rules rule
        SET rule_id=mapping.new_rule_id,
            source_sha256=lower(rule.source_sha256)
        FROM complaint_rule_id_rekey_v94 mapping
        WHERE rule.rule_id=mapping.old_rule_id;

        UPDATE public.source_course_complaints complaint
        SET complaint_rule_id=mapping.new_rule_id,
            source_sha256=mapping.source_sha256
        FROM complaint_rule_id_rekey_v94 mapping
        WHERE complaint.complaint_rule_id=mapping.old_rule_id;

        UPDATE public.personalized_trigger_matches match
        SET complaint_rule_id=mapping.new_rule_id,
            complaint_rule_source_sha256=mapping.source_sha256
        FROM complaint_rule_id_rekey_v94 mapping
        WHERE match.complaint_rule_id=mapping.old_rule_id;

ALTER TABLE public.complaint_category_rules ADD CONSTRAINT ck_complaint_rule_deterministic_identity_v2 CHECK (source_sha256 ~ '^[0-9a-f]{64}$' AND source_row_number>=1 AND rule_id='complaint-rule:' || lower(source_sha256) || ':' || source_row_number::text);

ALTER TABLE public.complaint_category_rules ADD CONSTRAINT uq_complaint_rule_source_row_v2 UNIQUE (source_sha256, source_row_number);

ALTER TABLE public.source_course_complaints ADD CONSTRAINT fk_source_course_complaint_rule_version FOREIGN KEY(complaint_rule_id, source_sha256) REFERENCES public.complaint_category_rules (rule_id, source_sha256) ON DELETE RESTRICT DEFERRABLE INITIALLY DEFERRED;

ALTER TABLE public.personalized_trigger_matches ADD CONSTRAINT fk_trigger_match_complaint_rule_version_v2 FOREIGN KEY(complaint_rule_id, complaint_rule_source_sha256) REFERENCES public.complaint_category_rules (rule_id, source_sha256) ON DELETE RESTRICT DEFERRABLE INITIALLY DEFERRED;

ALTER TABLE public.personalized_trigger_matches ADD CONSTRAINT ck_trigger_match_complaint_rule_version_v2 CHECK ((complaint_rule_id IS NULL AND complaint_rule_source_sha256 IS NULL) OR (complaint_rule_id IS NOT NULL AND complaint_rule_source_sha256 ~ '^[0-9a-f]{64}$'));

CREATE INDEX ix_trigger_match_complaint_rule_version_v2 ON public.personalized_trigger_matches (complaint_rule_id, complaint_rule_source_sha256);

CREATE INDEX ix_source_course_complaints_rule_category_reverse_v2 ON public.source_course_complaints (category_l3_normalized, source_region, source_appoint_id) WHERE NOT is_deleted;

CREATE FUNCTION public.complaint_rule_catalog_content_v1(
          p_source_sha256 text
        ) RETURNS jsonb
        LANGUAGE sql STABLE SECURITY DEFINER
        SET search_path=pg_catalog,public
        AS $$
          SELECT jsonb_build_object(
            'protocol_version','complaint-rule-catalog-content-v1',
            'source_sha256',imported.source_sha256,
            'raw_rows',imported.raw_rows,
            'rules',coalesce((
              SELECT jsonb_agg(jsonb_build_object(
                'rule_id',rule.rule_id,
                'source_sha256',rule.source_sha256,
                'source_row_number',rule.source_row_number,
                'category_l1',rule.category_l1,
                'category_l2',rule.category_l2,
                'category_l3',rule.category_l3,
                'category_l3_normalized',rule.category_l3_normalized,
                'source_level',rule.source_level,
                'severity_rank',rule.severity_rank,
                'default_route',rule.default_route
              ) ORDER BY rule.source_row_number)
              FROM public.complaint_category_rules rule
              WHERE rule.source_sha256=imported.source_sha256
            ),'[]'::jsonb)
          )
          FROM public.complaint_rule_imports imported
          WHERE imported.source_sha256=p_source_sha256
        $$;

        CREATE FUNCTION public.complaint_rule_catalog_content_hash_v1(
          p_source_sha256 text
        ) RETURNS text
        LANGUAGE sql STABLE SECURITY DEFINER
        SET search_path=pg_catalog,public
        AS $$
          SELECT public.dts_canonical_json_sha256_v1(
            public.complaint_rule_catalog_content_v1(p_source_sha256)
          )
        $$;
        REVOKE ALL ON FUNCTION
          public.complaint_rule_catalog_content_v1(text),
          public.complaint_rule_catalog_content_hash_v1(text)
        FROM PUBLIC;

        UPDATE public.complaint_rule_imports imported
        SET status='PUBLISHED',publication_revision=1,
            activation_generation=1,
            row_count=jsonb_array_length(imported.raw_rows),
            content_hash=public.complaint_rule_catalog_content_hash_v1(
              imported.source_sha256
            ),
            published_at=imported.imported_at,retired_at=NULL;

        DO $$
        DECLARE invalid_sha text;
        BEGIN
          SELECT imported.source_sha256 INTO invalid_sha
          FROM public.complaint_rule_imports imported
          WHERE jsonb_typeof(imported.raw_rows)<>'array'
             OR imported.row_count<>jsonb_array_length(imported.raw_rows)
             OR imported.row_count<>(
               SELECT count(*) FROM public.complaint_category_rules rule
               WHERE rule.source_sha256=imported.source_sha256
             )
             OR imported.content_hash IS DISTINCT FROM
               public.complaint_rule_catalog_content_hash_v1(
                 imported.source_sha256
               )
          LIMIT 1;
          IF invalid_sha IS NOT NULL THEN
            RAISE EXCEPTION
              'DTS_V2_COMPLAINT_CATALOG_LEGACY_CONTENT_INVALID:%',
              invalid_sha;
          END IF;
        END
        $$;

ALTER TABLE public.complaint_rule_imports ALTER COLUMN status SET NOT NULL;

ALTER TABLE public.complaint_rule_imports ALTER COLUMN publication_revision SET NOT NULL;

ALTER TABLE public.complaint_rule_imports ALTER COLUMN row_count SET NOT NULL;

ALTER TABLE public.complaint_rule_imports ALTER COLUMN content_hash SET NOT NULL;

ALTER TABLE public.complaint_rule_imports ADD CONSTRAINT ck_complaint_rule_import_lifecycle_v2 CHECK (status IN ('DRAFT','PUBLISHED','RETIRED') AND publication_revision>=1 AND row_count>=1 AND jsonb_typeof(raw_rows)='array' AND row_count=jsonb_array_length(raw_rows) AND content_hash ~ '^[0-9a-f]{64}$' AND ((status='DRAFT' AND activation_generation IS NULL AND published_at IS NULL AND retired_at IS NULL) OR (status='PUBLISHED' AND activation_generation>=1 AND published_at IS NOT NULL AND retired_at IS NULL) OR (status='RETIRED' AND activation_generation>=1 AND published_at IS NOT NULL AND retired_at IS NOT NULL AND retired_at>=published_at)));

CREATE UNIQUE INDEX uq_complaint_rule_import_published_v2 ON public.complaint_rule_imports (status) WHERE status='PUBLISHED';

CREATE UNIQUE INDEX uq_complaint_rule_activation_generation_v2 ON public.complaint_rule_imports (activation_generation) WHERE activation_generation IS NOT NULL;

CREATE FUNCTION public.guard_complaint_rule_import_v2()
        RETURNS trigger
        LANGUAGE plpgsql SECURITY DEFINER
        SET search_path=pg_catalog,public
        AS $$
        DECLARE publication_context boolean :=
          current_setting('tit.complaint_catalog_publication_v2',true)='on';
        BEGIN
          IF TG_OP='DELETE' THEN
            IF OLD.status IN ('PUBLISHED','RETIRED') THEN
              RAISE EXCEPTION 'COMPLAINT_RULE_IMPORT_IMMUTABLE'
                USING ERRCODE='23514';
            END IF;
            RETURN OLD;
          END IF;
          IF TG_OP='INSERT' THEN
            IF NEW.status<>'DRAFT' OR NEW.publication_revision<>1
               OR NEW.activation_generation IS NOT NULL
               OR NEW.published_at IS NOT NULL OR NEW.retired_at IS NOT NULL
            THEN
              RAISE EXCEPTION 'COMPLAINT_RULE_IMPORT_DRAFT_REQUIRED'
                USING ERRCODE='23514';
            END IF;
            RETURN NEW;
          END IF;
          IF NEW.source_sha256 IS DISTINCT FROM OLD.source_sha256
             OR NEW.source_filename IS DISTINCT FROM OLD.source_filename
             OR NEW.imported_at IS DISTINCT FROM OLD.imported_at THEN
            RAISE EXCEPTION 'COMPLAINT_RULE_IMPORT_IDENTITY_IMMUTABLE'
              USING ERRCODE='23514';
          END IF;
          IF OLD.status IN ('PUBLISHED','RETIRED') AND (
               NEW.raw_rows IS DISTINCT FROM OLD.raw_rows
               OR NEW.row_count IS DISTINCT FROM OLD.row_count
               OR NEW.content_hash IS DISTINCT FROM OLD.content_hash
               OR NEW.activation_generation IS DISTINCT FROM
                    OLD.activation_generation
               OR NEW.published_at IS DISTINCT FROM OLD.published_at
          ) THEN
            RAISE EXCEPTION 'COMPLAINT_RULE_IMPORT_IMMUTABLE'
              USING ERRCODE='23514';
          END IF;
          IF OLD.status='RETIRED' AND ROW(NEW.*) IS DISTINCT FROM ROW(OLD.*)
          THEN
            RAISE EXCEPTION 'COMPLAINT_RULE_IMPORT_RETIRED_TERMINAL'
              USING ERRCODE='23514';
          END IF;
          IF NEW.status IS DISTINCT FROM OLD.status THEN
            IF NOT publication_context
               OR NOT ((OLD.status='DRAFT' AND NEW.status='PUBLISHED')
                 OR (OLD.status='PUBLISHED' AND NEW.status='RETIRED'))
               OR NEW.publication_revision<>OLD.publication_revision+1
            THEN
              RAISE EXCEPTION 'COMPLAINT_RULE_PUBLICATION_COMMAND_REQUIRED'
                USING ERRCODE='42501';
            END IF;
          ELSIF NEW.publication_revision IS DISTINCT FROM
                  OLD.publication_revision THEN
            RAISE EXCEPTION 'COMPLAINT_RULE_PUBLICATION_REVISION_INVALID'
              USING ERRCODE='23514';
          END IF;
          RETURN NEW;
        END
        $$;

        CREATE FUNCTION public.guard_complaint_category_rule_v2()
        RETURNS trigger
        LANGUAGE plpgsql SECURITY DEFINER
        SET search_path=pg_catalog,public
        AS $$
        DECLARE parent_status text;
        DECLARE old_parent_status text;
        BEGIN
          IF TG_OP='DELETE' THEN
            SELECT status INTO parent_status
            FROM public.complaint_rule_imports
            WHERE source_sha256=OLD.source_sha256;
            IF parent_status IN ('PUBLISHED','RETIRED') THEN
              RAISE EXCEPTION 'COMPLAINT_RULE_CHILD_IMMUTABLE'
                USING ERRCODE='23514';
            END IF;
            RETURN OLD;
          END IF;
          IF TG_OP='UPDATE' THEN
            SELECT status INTO old_parent_status
            FROM public.complaint_rule_imports
            WHERE source_sha256=OLD.source_sha256 FOR KEY SHARE;
            IF old_parent_status IN ('PUBLISHED','RETIRED')
               AND ROW(NEW.*) IS DISTINCT FROM ROW(OLD.*) THEN
              RAISE EXCEPTION 'COMPLAINT_RULE_CHILD_IMMUTABLE'
                USING ERRCODE='23514';
            END IF;
          END IF;
          SELECT status INTO parent_status
          FROM public.complaint_rule_imports
          WHERE source_sha256=NEW.source_sha256 FOR KEY SHARE;
          IF NOT FOUND THEN
            RAISE EXCEPTION 'COMPLAINT_RULE_IMPORT_MISSING'
              USING ERRCODE='23503';
          END IF;
          IF parent_status IN ('PUBLISHED','RETIRED') AND
             (TG_OP='INSERT' OR ROW(NEW.*) IS DISTINCT FROM ROW(OLD.*)) THEN
            RAISE EXCEPTION 'COMPLAINT_RULE_CHILD_IMMUTABLE'
              USING ERRCODE='23514';
          END IF;
          RETURN NEW;
        END
        $$;

        CREATE FUNCTION public.freeze_trigger_match_complaint_rule_v2()
        RETURNS trigger
        LANGUAGE plpgsql SECURITY DEFINER
        SET search_path=pg_catalog,public
        AS $$
        DECLARE expected_sha text;
        BEGIN
          IF TG_OP='DELETE' THEN RETURN OLD; END IF;
          IF NEW.complaint_rule_id IS NULL THEN
            NEW.complaint_rule_source_sha256:=NULL;
            RETURN NEW;
          END IF;
          SELECT source_sha256 INTO expected_sha
          FROM public.complaint_category_rules
          WHERE rule_id=NEW.complaint_rule_id FOR KEY SHARE;
          IF NOT FOUND THEN
            RAISE EXCEPTION 'COMPLAINT_RULE_REFERENCE_INVALID'
              USING ERRCODE='23503';
          END IF;
          IF nullif(NEW.plan_evidence->>'source_sha256','') IS NOT NULL
             AND NEW.plan_evidence->>'source_sha256'<>expected_sha THEN
            RAISE EXCEPTION 'COMPLAINT_RULE_VERSION_MISMATCH'
              USING ERRCODE='23514';
          END IF;
          NEW.complaint_rule_source_sha256:=expected_sha;
          RETURN NEW;
        END
        $$;

        REVOKE ALL ON FUNCTION
          public.guard_complaint_rule_import_v2(),
          public.guard_complaint_category_rule_v2(),
          public.freeze_trigger_match_complaint_rule_v2()
        FROM PUBLIC;
        CREATE TRIGGER trg_guard_complaint_rule_import_v2
        BEFORE INSERT OR UPDATE OR DELETE ON public.complaint_rule_imports
        FOR EACH ROW EXECUTE FUNCTION public.guard_complaint_rule_import_v2();
        CREATE TRIGGER trg_guard_complaint_category_rule_v2
        BEFORE INSERT OR UPDATE OR DELETE ON public.complaint_category_rules
        FOR EACH ROW EXECUTE FUNCTION public.guard_complaint_category_rule_v2();
        CREATE TRIGGER trg_aa_freeze_trigger_match_complaint_rule_v2
        BEFORE INSERT OR UPDATE ON public.personalized_trigger_matches
        FOR EACH ROW
        EXECUTE FUNCTION public.freeze_trigger_match_complaint_rule_v2();

CREATE TABLE public.complaint_rule_publication_audits (
    publication_audit_id VARCHAR(160) NOT NULL,
    idempotency_key VARCHAR(128) NOT NULL,
    request_hash VARCHAR(64) NOT NULL,
    source_sha256 VARCHAR(64) NOT NULL,
    previous_source_sha256 VARCHAR(64),
    expected_catalog_generation BIGINT NOT NULL,
    activation_generation BIGINT NOT NULL,
    publication_revision BIGINT NOT NULL,
    content_hash VARCHAR(64) NOT NULL,
    affected_categories JSONB NOT NULL,
    affected_category_count INTEGER NOT NULL,
    course_count INTEGER NOT NULL,
    response_payload JSONB NOT NULL,
    response_hash VARCHAR(64) NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT pk_complaint_rule_publication_audits PRIMARY KEY (publication_audit_id),
    CONSTRAINT uq_complaint_rule_publication_idempotency UNIQUE (idempotency_key),
    CONSTRAINT uq_complaint_rule_publication_generation UNIQUE (activation_generation),
    CONSTRAINT fk_complaint_rule_publication_source FOREIGN KEY(source_sha256) REFERENCES public.complaint_rule_imports (source_sha256) ON DELETE RESTRICT,
    CONSTRAINT fk_complaint_rule_publication_previous FOREIGN KEY(previous_source_sha256) REFERENCES public.complaint_rule_imports (source_sha256) ON DELETE RESTRICT,
    CONSTRAINT ck_complaint_rule_publication_audit_v2 CHECK (request_hash ~ '^[0-9a-f]{64}$' AND content_hash ~ '^[0-9a-f]{64}$' AND response_hash ~ '^[0-9a-f]{64}$' AND response_hash=public.dts_canonical_json_sha256_v1(response_payload) AND jsonb_typeof(affected_categories)='array' AND affected_category_count=jsonb_array_length(affected_categories) AND expected_catalog_generation>=0 AND activation_generation=expected_catalog_generation+1 AND publication_revision>=2 AND course_count>=0)
);

CREATE FUNCTION public.guard_complaint_rule_publication_audit_v2()
        RETURNS trigger
        LANGUAGE plpgsql SECURITY DEFINER
        SET search_path=pg_catalog,public
        AS $$
        BEGIN
          IF TG_OP IN ('UPDATE','DELETE') THEN
            RAISE EXCEPTION 'COMPLAINT_RULE_PUBLICATION_AUDIT_IMMUTABLE'
              USING ERRCODE='42501';
          END IF;
          RETURN NEW;
        END
        $$;
        REVOKE ALL ON FUNCTION
          public.guard_complaint_rule_publication_audit_v2()
        FROM PUBLIC;
        CREATE TRIGGER trg_guard_complaint_rule_publication_audit_v2
        BEFORE UPDATE OR DELETE
        ON public.complaint_rule_publication_audits
        FOR EACH ROW
        EXECUTE FUNCTION public.guard_complaint_rule_publication_audit_v2();

CREATE FUNCTION public.enqueue_dirty_from_catalog_revision_v2(
          p_source_region text,p_source_appoint_id text,
          p_activation_generation bigint,p_source_sha256 text,
          p_content_hash text
        ) RETURNS jsonb
        LANGUAGE plpgsql SECURITY DEFINER
        SET search_path=pg_catalog,public
        AS $$
        DECLARE actor_name text:=coalesce(
          nullif(current_setting('role',true),'none'),session_user
        );
        DECLARE publication
          public.complaint_rule_publication_audits%ROWTYPE;
        DECLARE identity jsonb;
        DECLARE fingerprint text;
        BEGIN
          IF actor_name<>current_user AND actor_name<>
               'tit_growth_app' THEN
            RAISE EXCEPTION 'COMPLAINT_RULE_CATALOG_CALLER_FORBIDDEN'
              USING ERRCODE='42501';
          END IF;
          SELECT * INTO publication
          FROM public.complaint_rule_publication_audits
          WHERE activation_generation=p_activation_generation
            AND source_sha256=p_source_sha256
            AND content_hash=p_content_hash
          FOR SHARE;
          IF NOT FOUND OR p_source_region NOT IN ('dom','ovs')
             OR p_source_appoint_id IS NULL
             OR btrim(p_source_appoint_id)='' OR
             NOT EXISTS(
               SELECT 1 FROM public.complaint_rule_imports imported
               WHERE imported.source_sha256=p_source_sha256
                 AND imported.status='PUBLISHED'
                 AND imported.activation_generation=p_activation_generation
                 AND imported.content_hash=p_content_hash
             ) OR NOT EXISTS(
               SELECT 1 FROM public.source_course_complaints complaint
               WHERE complaint.source_region=p_source_region
                 AND complaint.source_appoint_id=p_source_appoint_id
                 AND NOT complaint.is_deleted
                 AND complaint.category_l3_normalized IN (
                   SELECT jsonb_array_elements_text(
                     publication.affected_categories
                   )
                 )
             ) THEN
            RAISE EXCEPTION 'DIRTY_INPUT_REFERENCE_INVALID'
              USING ERRCODE='23503';
          END IF;
          identity:=jsonb_build_object(
            'catalog_type','COMPLAINT_RULE_SET',
            'catalog_key','ACTIVE_COMPLAINT_RULE_SET'
          );
          fingerprint:=public.dts_canonical_json_sha256_v1(
            jsonb_build_object(
              'protocol','dirty-catalog-v1','identity',identity,
              'revision',p_activation_generation,
              'version_id',p_source_sha256,
              'payload_hash',p_content_hash
            )
          );
          RETURN public._upsert_dts_dirty_key_input_v2(
            p_source_region,'COURSE',p_source_appoint_id,'',
            'CATALOG_REVISION',identity,p_activation_generation,
            fingerprint
          );
        END
        $$;
        REVOKE ALL ON FUNCTION
          public.enqueue_dirty_from_catalog_revision_v2(
            text,text,bigint,text,text
          )
        FROM PUBLIC;

CREATE FUNCTION public.enqueue_complaint_category_course_fanout_v2(
          p_category_id text,p_expected_aggregate_revision bigint,
          p_triggering_event_id text,p_expected_command_sha256 text
        ) RETURNS jsonb
        LANGUAGE plpgsql SECURITY DEFINER
        SET search_path=pg_catalog,public
        AS $$
        DECLARE actor_name text:=coalesce(
          nullif(current_setting('role',true),'none'),session_user
        );
        DECLARE aggregate_row public.domain_aggregate_revisions%ROWTYPE;
        DECLARE event_row public.outbox_events%ROWTYPE;
        DECLARE request_document jsonb;
        DECLARE request_hash text;
        DECLARE dependency_identity jsonb;
        DECLARE dependency_fingerprint text;
        DECLARE linked_course record;
        DECLARE dirty_result jsonb;
        DECLARE seen_count integer:=0;
        DECLARE enqueued_count integer:=0;
        DECLARE noop_count integer:=0;
        BEGIN
          IF actor_name<>current_user AND actor_name<>
               'tit_growth_app' THEN
            RAISE EXCEPTION
              'DTS_V2_COMPLAINT_CATEGORY_FANOUT_CALLER_FORBIDDEN'
              USING ERRCODE='42501';
          END IF;
          IF p_category_id IS NULL OR btrim(p_category_id)=''
             OR p_category_id<>btrim(p_category_id)
             OR p_expected_aggregate_revision<1
             OR p_triggering_event_id IS NULL
             OR btrim(p_triggering_event_id)=''
             OR p_expected_command_sha256 !~ '^[0-9a-f]{64}$' THEN
            RAISE EXCEPTION
              'DTS_V2_COMPLAINT_CATEGORY_FANOUT_REQUEST_INVALID'
              USING ERRCODE='22023';
          END IF;
          PERFORM pg_advisory_xact_lock_shared(
            hashtextextended('tit:dts-v2-cutover',0)
          );
          request_document:=jsonb_build_object(
            'protocol_version',
              'complaint-category-course-fanout-command-v1',
            'category_id',p_category_id,
            'aggregate_revision',p_expected_aggregate_revision,
            'triggering_event_id',p_triggering_event_id
          );
          request_hash:=public.dts_canonical_json_sha256_v1(
            request_document
          );
          IF request_hash<>p_expected_command_sha256 THEN
            RAISE EXCEPTION
              'DTS_V2_COMPLAINT_CATEGORY_FANOUT_HASH_MISMATCH'
              USING ERRCODE='23514';
          END IF;
          SELECT * INTO aggregate_row
          FROM public.domain_aggregate_revisions
          WHERE aggregate_type='COMPLAINT_CATEGORY'
            AND canonical_key=jsonb_build_object(
              'source_region','dom','category_id',p_category_id
            )
          FOR SHARE;
          IF NOT FOUND OR aggregate_row.revision<>
               p_expected_aggregate_revision THEN
            RAISE EXCEPTION
              'DTS_V2_COMPLAINT_CATEGORY_REVISION_CHANGED'
              USING ERRCODE='40001';
          END IF;
          SELECT * INTO event_row FROM public.outbox_events
          WHERE event_id=p_triggering_event_id FOR SHARE;
          IF NOT FOUND OR event_row.aggregate_type<>'COMPLAINT_CATEGORY'
             OR event_row.aggregate_id<>aggregate_row.aggregate_id
             OR event_row.event_type<>'source_wide.changed.v2'
             OR (event_row.payload->>'aggregate_revision')::bigint
                  IS DISTINCT FROM
                  p_expected_aggregate_revision
             OR event_row.payload->'aggregate_key' IS DISTINCT FROM
                  aggregate_row.canonical_key THEN
            RAISE EXCEPTION
              'DTS_V2_COMPLAINT_CATEGORY_EVENT_INVALID'
              USING ERRCODE='23514';
          END IF;
          dependency_identity:=jsonb_build_object(
            'dependency_type','COMPLAINT_CATEGORY',
            'dependency_region','dom','dependency_key',p_category_id
          );
          dependency_fingerprint:=public.dts_canonical_json_sha256_v1(
            jsonb_build_object(
              'protocol','dirty-dependency-v1',
              'identity',dependency_identity,
              'revision',p_expected_aggregate_revision,
              'dependency_hash',aggregate_row.aggregate_state_sha256
            )
          );
          FOR linked_course IN
            SELECT source_region,source_appoint_id FROM (
              SELECT source_region,source_appoint_id
              FROM public.source_course_complaints
              WHERE complaint_type_type IN ('NUMERIC','TEXT')
                AND complaint_type=p_category_id AND NOT is_deleted
              UNION
              SELECT source_region,source_appoint_id
              FROM public.source_course_complaints
              WHERE complaint_type_child_type IN ('NUMERIC','TEXT')
                AND complaint_type_child=p_category_id AND NOT is_deleted
              UNION
              SELECT source_region,source_appoint_id
              FROM public.source_course_complaints
              WHERE complaint_type_grandson_type IN ('NUMERIC','TEXT')
                AND complaint_type_grandson=p_category_id AND NOT is_deleted
            ) linked
            ORDER BY convert_to(source_region,'UTF8'),
              convert_to(source_appoint_id,'UTF8')
          LOOP
            seen_count:=seen_count+1;
            dirty_result:=public._upsert_dts_dirty_key_input_v2(
              linked_course.source_region,'COURSE',
              linked_course.source_appoint_id,'','DEPENDENCY_WAKE',
              dependency_identity,p_expected_aggregate_revision,
              dependency_fingerprint
            );
            IF dirty_result->>'status'='ENQUEUED' THEN
              enqueued_count:=enqueued_count+1;
            ELSIF dirty_result->>'status' IN ('NOOP','NOOP_OLDER') THEN
              noop_count:=noop_count+1;
            ELSE
              RAISE EXCEPTION
                'DTS_V2_COMPLAINT_CATEGORY_FANOUT_RESULT_INVALID'
                USING ERRCODE='23514';
            END IF;
          END LOOP;
          RETURN jsonb_build_object(
            'protocol_version','complaint-category-course-fanout-v1',
            'command_sha256',request_hash,
            'counts',jsonb_build_object(
              'courses_seen',seen_count,
              'courses_enqueued',enqueued_count,
              'courses_noop',noop_count
            )
          );
        END
        $$;
        REVOKE ALL ON FUNCTION
          public.enqueue_complaint_category_course_fanout_v2(
            text,bigint,text,text
          )
        FROM PUBLIC;

CREATE FUNCTION public.publish_complaint_rule_import_v2(
          p_source_sha256 text,p_expected_revision bigint,
          p_idempotency_key text
        ) RETURNS jsonb
        LANGUAGE plpgsql SECURITY DEFINER
        SET search_path=pg_catalog,public
        AS $$
        DECLARE actor_name text:=coalesce(
          nullif(current_setting('role',true),'none'),session_user
        );
        DECLARE request_document jsonb;
        DECLARE request_hash text;
        DECLARE replay
          public.complaint_rule_publication_audits%ROWTYPE;
        DECLARE target public.complaint_rule_imports%ROWTYPE;
        DECLARE previous public.complaint_rule_imports%ROWTYPE;
        DECLARE previous_found boolean:=false;
        DECLARE current_generation bigint:=0;
        DECLARE next_generation bigint;
        DECLARE actual_raw_count integer;
        DECLARE actual_rule_count integer;
        DECLARE actual_content_hash text;
        DECLARE affected_categories jsonb;
        DECLARE affected_count integer;
        DECLARE course_count integer;
        DECLARE course_row record;
        DECLARE dirty_result jsonb;
        DECLARE enqueued_count integer:=0;
        DECLARE noop_count integer:=0;
        DECLARE publication_revision bigint;
        DECLARE publication_audit_id text;
        DECLARE response_document jsonb;
        DECLARE response_hash text;
        DECLARE audit_event_id text;
        DECLARE audit_payload jsonb;
        BEGIN
          IF actor_name<>current_user AND actor_name<>
               'tit_growth_app' THEN
            RAISE EXCEPTION 'COMPLAINT_RULE_CATALOG_CALLER_FORBIDDEN'
              USING ERRCODE='42501';
          END IF;
          IF p_source_sha256 !~ '^[0-9a-f]{64}$'
             OR p_expected_revision<0
             OR p_idempotency_key IS NULL
             OR p_idempotency_key !~ '^[A-Za-z0-9._:-]{1,128}$' THEN
            RAISE EXCEPTION 'COMPLAINT_RULE_PUBLICATION_REQUEST_INVALID'
              USING ERRCODE='22023';
          END IF;
          request_document:=jsonb_build_object(
            'protocol_version','complaint-rule-publication-command-v2',
            'source_sha256',p_source_sha256,
            'expected_revision',p_expected_revision
          );
          request_hash:=public.dts_canonical_json_sha256_v1(
            request_document
          );
          PERFORM pg_advisory_xact_lock_shared(
            hashtextextended('tit:dts-v2-cutover',0)
          );
          PERFORM pg_advisory_xact_lock(
            hashtextextended('tit:catalog:COMPLAINT_RULE_SET:ACTIVE_COMPLAINT_RULE_SET',0)
          );
          SELECT * INTO replay
          FROM public.complaint_rule_publication_audits
          WHERE idempotency_key=p_idempotency_key FOR SHARE;
          IF FOUND THEN
            IF replay.request_hash<>request_hash
               OR replay.source_sha256<>p_source_sha256
               OR replay.expected_catalog_generation<>p_expected_revision
               OR replay.response_hash<>
                  public.dts_canonical_json_sha256_v1(
                    replay.response_payload
                  ) THEN
              RAISE EXCEPTION 'COMPLAINT_RULE_PUBLICATION_CONFLICT'
                USING ERRCODE='23505';
            END IF;
            RETURN replay.response_payload ||
              jsonb_build_object('replay_status','REPLAYED');
          END IF;
          SELECT * INTO previous
          FROM public.complaint_rule_imports
          WHERE status='PUBLISHED' FOR UPDATE;
          previous_found:=FOUND;
          SELECT coalesce(max(activation_generation),0)
          INTO current_generation
          FROM public.complaint_rule_imports;
          IF (previous_found AND previous.activation_generation
                IS DISTINCT FROM current_generation)
             OR (NOT previous_found AND current_generation<>0) THEN
            RAISE EXCEPTION 'COMPLAINT_RULE_PUBLICATION_CONFLICT'
              USING ERRCODE='40001';
          END IF;
          IF current_generation<>p_expected_revision THEN
            RAISE EXCEPTION 'COMPLAINT_RULE_PUBLICATION_CONFLICT'
              USING ERRCODE='40001';
          END IF;
          SELECT * INTO target FROM public.complaint_rule_imports
          WHERE source_sha256=p_source_sha256 FOR UPDATE;
          IF NOT FOUND OR target.status<>'DRAFT'
             OR target.publication_revision<>1 THEN
            RAISE EXCEPTION 'COMPLAINT_RULE_PUBLICATION_CONFLICT'
              USING ERRCODE='40001';
          END IF;
          actual_raw_count:=jsonb_array_length(target.raw_rows);
          SELECT count(*) INTO actual_rule_count
          FROM public.complaint_category_rules
          WHERE source_sha256=p_source_sha256;
          actual_content_hash:=
            public.complaint_rule_catalog_content_hash_v1(
              p_source_sha256
            );
          IF actual_raw_count<>target.row_count
             OR actual_rule_count<>target.row_count
             OR actual_content_hash<>target.content_hash
             OR EXISTS(
               SELECT 1 FROM public.complaint_category_rules rule
               WHERE rule.source_sha256=p_source_sha256
                 AND rule.rule_id<>'complaint-rule:' ||
                   lower(p_source_sha256) || ':' ||
                   rule.source_row_number::text
             ) THEN
            RAISE EXCEPTION 'COMPLAINT_RULE_PUBLICATION_CONTENT_INVALID'
              USING ERRCODE='23514';
          END IF;
          SELECT coalesce(jsonb_agg(name ORDER BY convert_to(name,'UTF8')),
                          '[]'::jsonb)
          INTO affected_categories
          FROM (
            SELECT coalesce(new_rule.category_l3_normalized,
                            old_rule.category_l3_normalized) AS name
            FROM (
              SELECT * FROM public.complaint_category_rules
              WHERE source_sha256=p_source_sha256
            ) new_rule
            FULL JOIN (
              SELECT * FROM public.complaint_category_rules
              WHERE source_sha256=previous.source_sha256
            ) old_rule USING (category_l3_normalized)
            WHERE ROW(new_rule.category_l1,new_rule.category_l2,
                      new_rule.category_l3,new_rule.source_level,
                      new_rule.severity_rank,new_rule.default_route)
              IS DISTINCT FROM
                  ROW(old_rule.category_l1,old_rule.category_l2,
                      old_rule.category_l3,old_rule.source_level,
                      old_rule.severity_rank,old_rule.default_route)
          ) changed;
          affected_count:=jsonb_array_length(affected_categories);
          SELECT count(*) INTO course_count FROM (
            SELECT DISTINCT complaint.source_region,
              complaint.source_appoint_id
            FROM public.source_course_complaints complaint
            WHERE NOT complaint.is_deleted
              AND complaint.category_l3_normalized IN (
                SELECT jsonb_array_elements_text(affected_categories)
              )
          ) affected_course;
          next_generation:=current_generation+1;
          PERFORM set_config(
            'tit.complaint_catalog_publication_v2','on',true
          );
          IF previous.source_sha256 IS NOT NULL THEN
            UPDATE public.complaint_rule_imports imported
            SET status='RETIRED',
                publication_revision=imported.publication_revision+1,
                retired_at=transaction_timestamp()
            WHERE imported.source_sha256=previous.source_sha256
              AND imported.status='PUBLISHED'
              AND imported.activation_generation=current_generation;
            IF NOT FOUND THEN
              RAISE EXCEPTION 'COMPLAINT_RULE_PUBLICATION_CONFLICT'
                USING ERRCODE='40001';
            END IF;
          END IF;
          UPDATE public.complaint_rule_imports imported
          SET status='PUBLISHED',
              publication_revision=imported.publication_revision+1,
              activation_generation=next_generation,
              published_at=transaction_timestamp(),retired_at=NULL
          WHERE imported.source_sha256=p_source_sha256
            AND imported.status='DRAFT'
            AND imported.publication_revision=1
          RETURNING imported.publication_revision
          INTO publication_revision;
          IF NOT FOUND THEN
            RAISE EXCEPTION 'COMPLAINT_RULE_PUBLICATION_CONFLICT'
              USING ERRCODE='40001';
          END IF;
          publication_audit_id:='complaint-rule-publication:' ||
            encode(sha256(convert_to(p_idempotency_key,'UTF8')),'hex');
          response_document:=jsonb_build_object(
            'protocol_version','complaint-rule-publication-result-v2',
            'status','PUBLISHED','replay_status','APPLIED',
            'source_sha256',p_source_sha256,
            'previous_source_sha256',previous.source_sha256,
            'activation_generation',next_generation,
            'publication_revision',publication_revision,
            'content_hash',actual_content_hash,
            'affected_category_count',affected_count,
            'courses_seen',course_count,
            'courses_enqueued',course_count,
            'courses_noop',0,
            'publication_audit_id',publication_audit_id
          );
          response_hash:=public.dts_canonical_json_sha256_v1(
            response_document
          );
          INSERT INTO public.complaint_rule_publication_audits(
            publication_audit_id,idempotency_key,request_hash,
            source_sha256,previous_source_sha256,
            expected_catalog_generation,activation_generation,
            publication_revision,content_hash,affected_categories,
            affected_category_count,course_count,response_payload,
            response_hash
          ) VALUES (
            publication_audit_id,p_idempotency_key,request_hash,
            p_source_sha256,previous.source_sha256,p_expected_revision,
            next_generation,publication_revision,actual_content_hash,
            affected_categories,affected_count,course_count,
            response_document,response_hash
          );
          FOR course_row IN
            SELECT affected_course.source_region,
              affected_course.source_appoint_id
            FROM (
              SELECT DISTINCT complaint.source_region,
                complaint.source_appoint_id
              FROM public.source_course_complaints complaint
              WHERE NOT complaint.is_deleted
                AND complaint.category_l3_normalized IN (
                  SELECT jsonb_array_elements_text(affected_categories)
                )
            ) affected_course
            ORDER BY convert_to(affected_course.source_region,'UTF8'),
              convert_to(affected_course.source_appoint_id,'UTF8')
          LOOP
            dirty_result:=public.enqueue_dirty_from_catalog_revision_v2(
              course_row.source_region,course_row.source_appoint_id,
              next_generation,p_source_sha256,actual_content_hash
            );
            IF dirty_result->>'status'='ENQUEUED' THEN
              enqueued_count:=enqueued_count+1;
            ELSIF dirty_result->>'status' IN ('NOOP','NOOP_OLDER') THEN
              noop_count:=noop_count+1;
            ELSE
              RAISE EXCEPTION 'COMPLAINT_RULE_PUBLICATION_FANOUT_INVALID'
                USING ERRCODE='23514';
            END IF;
          END LOOP;
          IF enqueued_count<>course_count OR noop_count<>0 THEN
            RAISE EXCEPTION 'COMPLAINT_RULE_PUBLICATION_FANOUT_INVALID'
              USING ERRCODE='23514';
          END IF;
          audit_event_id:='audit:complaint-rule-publication:' ||
            encode(sha256(convert_to(p_idempotency_key,'UTF8')),'hex');
          audit_payload:=jsonb_build_object(
            'protocol_version','complaint-rule-publication-audit-v2',
            'source_sha256',p_source_sha256,
            'previous_source_sha256',previous.source_sha256,
            'activation_generation',next_generation,
            'publication_revision',publication_revision,
            'content_hash',actual_content_hash,
            'affected_category_count',affected_count,
            'course_count',course_count,
            'request_hash',request_hash
          );
          INSERT INTO public.audit_events(
            event_id,event_type,teacher_id,task_id,case_id,occurred_at,
            actor_type,payload_hash,payload
          ) VALUES (
            audit_event_id,'COMPLAINT_RULE_CATALOG_PUBLISHED_V2',
            NULL,NULL,NULL,transaction_timestamp(),
            'COMPLAINT_RULE_CATALOG',
            public.dts_canonical_json_sha256_v1(audit_payload),audit_payload
          );
          RETURN response_document;
        END
        $$;
        REVOKE ALL ON FUNCTION
          public.publish_complaint_rule_import_v2(text,bigint,text)
        FROM PUBLIC;

CREATE FUNCTION public.dts_v2_complaint_catalog_health_v1()
        RETURNS jsonb
        LANGUAGE plpgsql VOLATILE SECURITY DEFINER
        SET search_path=pg_catalog,public
        AS $$
        DECLARE active_count integer;
        DECLARE active_row public.complaint_rule_imports%ROWTYPE;
        DECLARE actual_rule_count integer;
        DECLARE actual_hash text;
        BEGIN
          PERFORM pg_advisory_xact_lock_shared(
            hashtextextended('tit:dts-v2-cutover',0)
          );
          PERFORM pg_advisory_xact_lock_shared(
            hashtextextended(
              'tit:catalog:COMPLAINT_RULE_SET:ACTIVE_COMPLAINT_RULE_SET',0
            )
          );
          SELECT count(*) INTO active_count
          FROM public.complaint_rule_imports WHERE status='PUBLISHED';
          SELECT * INTO active_row FROM public.complaint_rule_imports
          WHERE status='PUBLISHED' FOR SHARE;
          IF active_count=1 THEN
            SELECT count(*) INTO actual_rule_count
            FROM public.complaint_category_rules
            WHERE source_sha256=active_row.source_sha256;
            actual_hash:=public.complaint_rule_catalog_content_hash_v1(
              active_row.source_sha256
            );
          ELSE
            actual_rule_count:=0; actual_hash:=NULL;
          END IF;
          RETURN jsonb_build_object(
            'protocol_version','dts-v2-complaint-catalog-health-v1',
            'ready',active_count=1
              AND active_row.activation_generation>=1
              AND active_row.row_count=actual_rule_count
              AND active_row.content_hash=actual_hash,
            'active_count',active_count,
            'source_sha256',active_row.source_sha256,
            'activation_generation',active_row.activation_generation,
            'row_count',active_row.row_count,
            'content_hash',active_row.content_hash
          );
        END
        $$;
        REVOKE ALL ON FUNCTION
          public.dts_v2_complaint_catalog_health_v1()
        FROM PUBLIC;

REVOKE ALL PRIVILEGES ON TABLE
          public.complaint_rule_imports,
          public.complaint_rule_publication_audits
        FROM PUBLIC,tit_growth_app;
        REVOKE ALL PRIVILEGES ON TABLE public.complaint_category_rules
        FROM PUBLIC;
        REVOKE ALL PRIVILEGES ON TABLE
          public.dts_dirty_keys,public.dts_dirty_key_inputs
        FROM tit_growth_app,tit_growth_app;
        GRANT SELECT ON TABLE public.dts_dirty_key_inputs
        TO tit_growth_app;
        REVOKE ALL ON FUNCTION
          public.complaint_rule_catalog_content_v1(text),
          public.complaint_rule_catalog_content_hash_v1(text),
          public._upsert_dts_dirty_key_input_v2(
            text,text,text,text,text,jsonb,bigint,text
          )
        FROM PUBLIC,tit_growth_app,tit_growth_app;
        GRANT USAGE ON SCHEMA public TO tit_growth_app;
        GRANT EXECUTE ON FUNCTION
          public.publish_complaint_rule_import_v2(text,bigint,text),
          public.enqueue_dirty_from_catalog_revision_v2(
            text,text,bigint,text,text
          ),
          public.dts_v2_complaint_catalog_health_v1()
        TO tit_growth_app;
        GRANT EXECUTE ON FUNCTION
          public.enqueue_complaint_category_course_fanout_v2(
            text,bigint,text,text
          ),
          public.dts_v2_complaint_catalog_health_v1()
        TO tit_growth_app;

        DO $$
        DECLARE role_name text;
        BEGIN
          FOREACH role_name IN ARRAY ARRAY[
            'tit_teacher_crud','tit_dts_ingest_runtime',
            'tide_support_ticket_owner'
          ] LOOP
            IF to_regrole(role_name) IS NOT NULL THEN
              EXECUTE format(
                'REVOKE ALL ON FUNCTION '
                'public.publish_complaint_rule_import_v2(text,bigint,text),'
                'public.enqueue_dirty_from_catalog_revision_v2('
                'text,text,bigint,text,text),'
                'public.enqueue_complaint_category_course_fanout_v2('
                'text,bigint,text,text) FROM %I',role_name
              );
            END IF;
          END LOOP;
        END
        $$;

        COMMENT ON FUNCTION
          public.publish_complaint_rule_import_v2(text,bigint,text) IS
          'Catalog-CAS publication for one immutable complaint rule import.';
        COMMENT ON FUNCTION
          public.enqueue_complaint_category_course_fanout_v2(
            text,bigint,text,text
          ) IS
          'Indexed DOM complaint-category reverse fanout across DOM and OVS courses.';

UPDATE alembic_version SET version_num='20260822_94_complaint_catalog_fanout' WHERE alembic_version.version_num = '20260822_93_non_task_outputs';

-- Running upgrade 20260822_94_complaint_catalog_fanout -> 20260822_95_projection_cutover

DO $$
        DECLARE relation_name text;
        BEGIN
          FOREACH relation_name IN ARRAY ARRAY[
            'dts_pipeline_control','dts_pipeline_bootstrap_audits',
            'dts_ingest_checkpoints','dts_source_partition_epochs',
            'dts_source_rows','dts_dirty_keys','dts_ingest_issues',
            'dts_source_scope_states','outbox_events',
            'course_favorite_observations','personalized_trigger_matches',
            'task_assignments','notifications','ops_cases','task_templates',
            'complaint_rule_imports','teacher_scorecard_current',
            'teacher_lesson_score_current',
            'teacher_scorecard_v1_compat_v1','teacher_scorecard_v2_v1',
            'teacher_lesson_score_v1_compat_v1',
            'teacher_lesson_score_v2_v1'
          ] LOOP
            IF to_regclass('public.' || relation_name) IS NULL THEN
              RAISE EXCEPTION
                'DTS_V2_PROJECTION_CUTOVER_PREREQUISITE_MISSING:%',
                relation_name;
            END IF;
          END LOOP;
          IF to_regprocedure(
               'public.dts_canonical_json_sha256_v1(jsonb)'
             ) IS NULL
             OR to_regprocedure(
               'public.dts_v2_json_has_forbidden_student_key(jsonb)'
             ) IS NULL THEN
            RAISE EXCEPTION
              'DTS_V2_PROJECTION_CUTOVER_PREREQUISITE_MISSING';
          END IF;
          IF to_regclass('public.dts_projection_read_routes') IS NOT NULL
             OR to_regprocedure(
               'public.switch_dts_projection_mode_v2(text,bigint,bigint,text)'
             ) IS NOT NULL THEN
            RAISE EXCEPTION 'DTS_V2_PROJECTION_CUTOVER_ALREADY_INSTALLED';
          END IF;
        END
        $$;

        DO $$
        BEGIN
          IF to_regrole('tit_growth_app') IS NULL THEN
            RAISE EXCEPTION
              'required application role is missing: tit_growth_app';
          END IF;
          IF EXISTS (
            SELECT 1 FROM pg_roles WHERE rolname='tit_growth_app'
              AND (NOT rolcanlogin OR rolinherit OR rolsuper OR rolcreatedb
                   OR rolcreaterole OR rolreplication OR rolbypassrls)
          ) THEN
            RAISE EXCEPTION
              'tit_growth_app must be a restricted NOINHERIT LOGIN role';
          END IF;
        END
        $$;

CREATE TABLE public.dts_projection_read_routes (
    route_id VARCHAR(16) NOT NULL,
    active_projection VARCHAR(16) NOT NULL,
    route_contract_version VARCHAR(64) NOT NULL,
    row_version BIGINT DEFAULT 1 NOT NULL,
    switched_by_run_id VARCHAR(128),
    switched_at TIMESTAMP WITH TIME ZONE,
    switched_by VARCHAR(128) NOT NULL,
    CONSTRAINT pk_dts_projection_read_routes PRIMARY KEY (route_id),
    CONSTRAINT ck_dts_projection_read_route_singleton CHECK (route_id='PRIMARY'),
    CONSTRAINT ck_dts_projection_read_route_state CHECK (active_projection IN ('V1_COMPAT','V2') AND row_version>=1),
    CONSTRAINT ck_dts_projection_read_route_contract CHECK (route_contract_version='teacher-read-route-v1'),
    CONSTRAINT ck_dts_projection_read_route_switch_shape CHECK ((row_version=1 AND active_projection='V1_COMPAT' AND switched_by_run_id IS NULL AND switched_at IS NULL) OR (row_version>1 AND switched_by_run_id IS NOT NULL AND switched_at IS NOT NULL))
);

CREATE TABLE public.dts_source_profile_approvals_v2 (
    manifest_sha256 VARCHAR(64) NOT NULL,
    manifest_version INTEGER NOT NULL,
    profile_vector JSONB NOT NULL,
    profile_vector_hash VARCHAR(64) NOT NULL,
    status VARCHAR(16) NOT NULL,
    approved_by_change_id VARCHAR(160) NOT NULL,
    approved_at TIMESTAMP WITH TIME ZONE DEFAULT clock_timestamp() NOT NULL,
    approved_by VARCHAR(128) NOT NULL,
    CONSTRAINT pk_dts_source_profile_approvals_v2 PRIMARY KEY (manifest_sha256),
    CONSTRAINT ck_dts_source_profile_approval_shape_v2 CHECK (manifest_sha256 ~ '^[0-9a-f]{64}$' AND profile_vector_hash=manifest_sha256 AND manifest_version=1 AND status='APPROVED' AND jsonb_typeof(profile_vector)='array' AND btrim(approved_by_change_id)<>'' AND btrim(approved_by)<>'')
);

CREATE TABLE public.dts_v2_reconciliation_runs (
    run_id VARCHAR(128) NOT NULL,
    request_hash VARCHAR(64) NOT NULL,
    base_mode VARCHAR(32) NOT NULL,
    base_control_version BIGINT NOT NULL,
    base_route_version BIGINT NOT NULL,
    target_projection_generation BIGINT NOT NULL,
    source_profile_manifest_version INTEGER NOT NULL,
    source_profile_manifest_sha256 VARCHAR(64) NOT NULL,
    source_profile_vector JSONB NOT NULL,
    source_profile_vector_hash VARCHAR(64) NOT NULL,
    source_fence_vector JSONB NOT NULL,
    source_fence_hash VARCHAR(64) NOT NULL,
    full_reconciliation_manifest JSONB NOT NULL,
    full_reconciliation_manifest_hash VARCHAR(64) NOT NULL,
    v1_result_manifest JSONB NOT NULL,
    v1_result_manifest_hash VARCHAR(64) NOT NULL,
    v2_result_manifest JSONB NOT NULL,
    v2_result_manifest_hash VARCHAR(64) NOT NULL,
    legacy_output_manifest JSONB NOT NULL,
    legacy_output_manifest_hash VARCHAR(64) NOT NULL,
    technical_gate_manifest JSONB NOT NULL,
    technical_gate_manifest_hash VARCHAR(64) NOT NULL,
    evaluation_as_of TIMESTAMP WITH TIME ZONE NOT NULL,
    evaluation_business_date_beijing DATE NOT NULL,
    result_status VARCHAR(16) NOT NULL,
    recorded_at TIMESTAMP WITH TIME ZONE DEFAULT clock_timestamp() NOT NULL,
    recorded_by VARCHAR(128) NOT NULL,
    CONSTRAINT pk_dts_v2_reconciliation_runs PRIMARY KEY (run_id),
    CONSTRAINT ck_dts_v2_reconciliation_run_shape CHECK (request_hash ~ '^[0-9a-f]{64}$' AND source_profile_manifest_sha256 ~ '^[0-9a-f]{64}$' AND source_profile_vector_hash ~ '^[0-9a-f]{64}$' AND source_fence_hash ~ '^[0-9a-f]{64}$' AND full_reconciliation_manifest_hash ~ '^[0-9a-f]{64}$' AND v1_result_manifest_hash ~ '^[0-9a-f]{64}$' AND v2_result_manifest_hash ~ '^[0-9a-f]{64}$' AND legacy_output_manifest_hash ~ '^[0-9a-f]{64}$' AND technical_gate_manifest_hash ~ '^[0-9a-f]{64}$' AND base_control_version>=1 AND base_route_version>=1 AND target_projection_generation>=1 AND source_profile_manifest_version=1 AND base_mode IN ('V1_COMPAT_DUAL_CAPTURE','ROLLED_BACK') AND result_status='PASS')
);

CREATE TABLE public.dts_projection_switch_audits (
    switch_run_id VARCHAR(128) NOT NULL,
    request_hash VARCHAR(64) NOT NULL,
    reconciliation_run_id VARCHAR(128),
    from_mode VARCHAR(32) NOT NULL,
    to_mode VARCHAR(32) NOT NULL,
    from_projection VARCHAR(16) NOT NULL,
    to_projection VARCHAR(16) NOT NULL,
    projection_generation BIGINT NOT NULL,
    before_control_version BIGINT NOT NULL,
    after_control_version BIGINT NOT NULL,
    before_route_version BIGINT NOT NULL,
    after_route_version BIGINT NOT NULL,
    source_fence_hash VARCHAR(64) NOT NULL,
    response_payload JSONB NOT NULL,
    response_hash VARCHAR(64) NOT NULL,
    result_status VARCHAR(16) NOT NULL,
    occurred_at TIMESTAMP WITH TIME ZONE DEFAULT clock_timestamp() NOT NULL,
    occurred_by VARCHAR(128) NOT NULL,
    CONSTRAINT pk_dts_projection_switch_audits PRIMARY KEY (switch_run_id),
    CONSTRAINT fk_dts_projection_switch_reconciliation FOREIGN KEY(reconciliation_run_id) REFERENCES public.dts_v2_reconciliation_runs (run_id) ON DELETE RESTRICT,
    CONSTRAINT ck_dts_projection_switch_audit_shape CHECK (request_hash ~ '^[0-9a-f]{64}$' AND source_fence_hash ~ '^[0-9a-f]{64}$' AND response_hash ~ '^[0-9a-f]{64}$' AND projection_generation>=0 AND after_control_version=before_control_version+1 AND after_route_version=before_route_version+1 AND result_status='APPLIED' AND ((to_mode='V2_PRIMARY' AND to_projection='V2' AND reconciliation_run_id=switch_run_id) OR (to_mode='ROLLED_BACK' AND to_projection='V1_COMPAT' AND reconciliation_run_id IS NULL)))
);

CREATE FUNCTION public.dts_v2_source_profile_vector_valid_v1(
          p_vector jsonb
        ) RETURNS boolean
        LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
        SET search_path=pg_catalog,public
        AS $$
          WITH expected(position,source_region,source_table) AS (
            VALUES (1,'dom','dom_appoint'),(2,'dom','dom_complaint'),(3,'dom','dom_complaint_cate'),(4,'dom','dom_grading_label'),(5,'dom','dom_grading_label_log'),(6,'dom','dom_qa_task_close_camera_record'),(7,'dom','dom_teacher'),(8,'dom','dom_teacher_absent_reason'),(9,'dom','dom_teacher_blacklist'),(10,'dom','dom_teacher_certification'),(11,'dom','dom_teacher_class_schedule'),(12,'dom','dom_teacher_favorite'),(13,'dom','dom_teacher_penalty'),(14,'dom','dom_user_complaint'),(15,'dom','dom_user_teacher_grading'),(16,'ovs','ovs_appoint'),(17,'ovs','ovs_complaint'),(18,'ovs','ovs_grading_label'),(19,'ovs','ovs_grading_label_log'),(20,'ovs','ovs_qa_task_close_camera_record'),(21,'ovs','ovs_teacher_blacklist'),(22,'ovs','ovs_teacher_favorite'),(23,'ovs','ovs_user_complaint'),(24,'ovs','ovs_user_teacher_grading')
          ), supplied AS (
            SELECT ordinal::integer AS position,value
            FROM jsonb_array_elements(p_vector) WITH ORDINALITY item(
              value,ordinal
            )
          )
          SELECT jsonb_typeof(p_vector)='array'
             AND jsonb_array_length(p_vector)=24
             AND NOT EXISTS (
               SELECT 1 FROM expected
               LEFT JOIN supplied USING(position)
               WHERE supplied.value IS NULL
                  OR jsonb_typeof(supplied.value)<>'object'
                  OR supplied.value<>jsonb_build_object(
                       'source_region',expected.source_region,
                       'source_table',expected.source_table,
                       'source_schema_profile_id',
                         supplied.value->>'source_schema_profile_id'
                     )
                  OR supplied.value->>'source_region'<>
                       expected.source_region
                  OR supplied.value->>'source_table'<>
                       expected.source_table
                  OR supplied.value->>'source_schema_profile_id'
                       !~ '^dts-source-schema:v2:[0-9a-f]{64}$'
             )
        $$;

        CREATE FUNCTION public.dts_v2_result_manifest_valid_v1(
          p_manifest jsonb
        ) RETURNS boolean
        LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
        SET search_path=pg_catalog,public
        AS $$
          WITH expected(position,result_type) AS (
            VALUES (1,'TEACHER_WIDE'),(2,'LESSON_SCORE'),(3,'LESSON_COMPONENT_SETTLEMENT'),(4,'FAVORITE_OBSERVATION'),(5,'FAVORITE_ATTRIBUTION'),(6,'TRIGGER_MATCH'),(7,'TASK_PLAN'),(8,'CASE_PLAN'),(9,'NOTIFICATION_PLAN'),(10,'SCORE_ACCOUNT'),(11,'SCORE_COMPONENT_ACCOUNT'),(12,'SCORE_ENTRY_PLAN'),(13,'QUALIFICATION'),(14,'OUTBOX_COVERAGE')
          ), supplied AS (
            SELECT ordinal::integer AS position,value
            FROM jsonb_array_elements(p_manifest) WITH ORDINALITY item(
              value,ordinal
            )
          )
          SELECT jsonb_typeof(p_manifest)='array'
             AND jsonb_array_length(p_manifest)=14
             AND NOT EXISTS (
               SELECT 1 FROM expected
               LEFT JOIN supplied USING(position)
               WHERE supplied.value IS NULL
                  OR jsonb_typeof(supplied.value)<>'object'
                  OR supplied.value<>jsonb_build_object(
                       'result_type',expected.result_type,
                       'row_count',(supplied.value->>'row_count')::numeric,
                       'content_hash',supplied.value->>'content_hash'
                     )
                  OR supplied.value->>'result_type'<>expected.result_type
                  OR supplied.value->>'row_count' !~ '^(0|[1-9][0-9]*)$'
                  OR (supplied.value->>'row_count')::numeric>
                       9223372036854775807
                  OR supplied.value->>'content_hash'
                       !~ '^[0-9a-f]{64}$'
             )
        $$;

        CREATE FUNCTION public.dts_v2_current_fence_vector_v1()
        RETURNS jsonb
        LANGUAGE plpgsql STABLE SECURITY DEFINER
        SET search_path=pg_catalog,public
        AS $$
        DECLARE control_row public.dts_pipeline_control%ROWTYPE;
        DECLARE route_count integer;
        DECLARE fence_vector jsonb;
        BEGIN
          SELECT * INTO STRICT control_row
          FROM public.dts_pipeline_control WHERE control_id='PRIMARY';
          route_count:=jsonb_array_length(control_row.initial_h0_vector);
          IF route_count<1
             OR (SELECT count(*) FROM public.dts_ingest_checkpoints)<>
                  route_count
             OR EXISTS (
               SELECT 1 FROM jsonb_array_elements(
                 control_row.initial_h0_vector
               ) initial(value)
               LEFT JOIN public.dts_ingest_checkpoints checkpoint
                 ON checkpoint.source_region=initial.value->>'source_region'
                AND checkpoint.topic=initial.value->>'topic'
                AND checkpoint.partition_id=
                    (initial.value->>'partition_id')::integer
               LEFT JOIN public.dts_source_partition_epochs epoch
                 ON epoch.source_region=checkpoint.source_region
                AND epoch.source_partition_epoch_id=
                    checkpoint.source_partition_epoch_id
                AND epoch.topic=checkpoint.topic
                AND epoch.partition_id=checkpoint.partition_id
               WHERE checkpoint.source_region IS NULL
                  OR checkpoint.source_partition_epoch_id IS NULL
                  OR checkpoint.consumer_group IS DISTINCT FROM
                       initial.value->>'consumer_group'
                  OR checkpoint.checkpoint_row_version IS NULL
                  OR checkpoint.checkpoint_row_version<1
                  OR checkpoint.is_current_epoch IS DISTINCT FROM true
                  OR checkpoint.next_offset<
                       (initial.value->>'current_next_offset')::bigint
                  OR epoch.source_region IS NULL
                  OR epoch.epoch_kind<>'BROKER' OR epoch.status<>'ACTIVE'
                  OR epoch.stream_generation_id IS DISTINCT FROM
                       initial.value->>'stream_generation_id'
                  OR epoch.epoch_opening_id IS DISTINCT FROM
                       initial.value->>'epoch_opening_id'
             ) THEN
            RAISE EXCEPTION 'DTS_V2_SOURCE_FENCE_UNAVAILABLE'
              USING ERRCODE='23514';
          END IF;
          SELECT jsonb_agg(jsonb_build_object(
                   'source_region',checkpoint.source_region,
                   'topic',checkpoint.topic,
                   'partition_id',checkpoint.partition_id,
                   'source_partition_epoch_id',
                     checkpoint.source_partition_epoch_id,
                   'consumer_group',checkpoint.consumer_group,
                   'stream_generation_id',epoch.stream_generation_id,
                   'epoch_opening_id',epoch.epoch_opening_id,
                   'current_next_offset',checkpoint.next_offset,
                   'checkpoint_row_version',checkpoint.checkpoint_row_version
                 ) ORDER BY checkpoint.source_region COLLATE "C",
                   checkpoint.topic COLLATE "C",checkpoint.partition_id)
          INTO fence_vector
          FROM public.dts_ingest_checkpoints checkpoint
          JOIN public.dts_source_partition_epochs epoch
            ON epoch.source_region=checkpoint.source_region
           AND epoch.source_partition_epoch_id=
               checkpoint.source_partition_epoch_id
           AND epoch.topic=checkpoint.topic
           AND epoch.partition_id=checkpoint.partition_id;
          RETURN fence_vector;
        EXCEPTION WHEN no_data_found OR too_many_rows THEN
          RAISE EXCEPTION 'DTS_V2_SOURCE_FENCE_UNAVAILABLE'
            USING ERRCODE='23514';
        END
        $$;

        CREATE FUNCTION public.dts_v2_source_rows_match_profile_v1(
          p_vector jsonb
        ) RETURNS boolean
        LANGUAGE sql STABLE SECURITY DEFINER
        SET search_path=pg_catalog,public
        AS $$
          SELECT public.dts_v2_source_profile_vector_valid_v1(p_vector)
             AND NOT EXISTS (
               SELECT 1
               FROM public.dts_source_rows source
               JOIN jsonb_array_elements(p_vector) profile(value)
                 ON profile.value->>'source_region'=source.source_region
                AND profile.value->>'source_table'=source.source_table
               WHERE source.provenance_state IS DISTINCT FROM 'V2_CONFIRMED'
                  OR source.source_schema_profile_id IS DISTINCT FROM
                       profile.value->>'source_schema_profile_id'
             )
        $$;

        REVOKE ALL ON FUNCTION
          public.dts_v2_source_profile_vector_valid_v1(jsonb),
          public.dts_v2_result_manifest_valid_v1(jsonb),
          public.dts_v2_current_fence_vector_v1(),
          public.dts_v2_source_rows_match_profile_v1(jsonb)
        FROM PUBLIC;

CREATE FUNCTION public.dts_v2_legacy_output_mapping_manifest_v1()
        RETURNS jsonb
        LANGUAGE sql STABLE SECURITY DEFINER
        SET search_path=pg_catalog,public
        AS $$
          WITH candidates AS (
            SELECT match.trigger_match_id,match.output_type,
              match.output_key,match.output_id,
              CASE match.output_type
                WHEN 'TEACHER_TASK' THEN match.task_assignment_id
                WHEN 'OPS_CASE' THEN match.ops_case_id
                WHEN 'NOTIFICATION' THEN match.notification_id
              END AS typed_output_id,
              CASE match.output_type
                WHEN 'TEACHER_TASK' THEN match.assignment_dedupe_key
                ELSE match.output_key
              END AS canonical_output_key,
              CASE match.output_type
                WHEN 'TEACHER_TASK' THEN assignment.dedupe_key
                WHEN 'OPS_CASE' THEN case_row.source_ref
                WHEN 'NOTIFICATION' THEN notification.source_ref
              END AS physical_output_key,
              CASE match.output_type
                WHEN 'TEACHER_TASK' THEN assignment.assignment_id
                WHEN 'OPS_CASE' THEN case_row.case_id
                WHEN 'NOTIFICATION' THEN notification.notification_id
              END AS physical_output_id,
              match.match_status,match.materialization_origin
            FROM public.personalized_trigger_matches match
            LEFT JOIN public.task_assignments assignment
              ON assignment.assignment_id=match.task_assignment_id
            LEFT JOIN public.ops_cases case_row
              ON case_row.case_id=match.ops_case_id
            LEFT JOIN public.notifications notification
              ON notification.notification_id=match.notification_id
            WHERE match.output_type IN (
              'TEACHER_TASK','OPS_CASE','NOTIFICATION'
            ) AND (
              match.materialization_origin='LEGACY_REUSED'
              OR match.output_id IS NOT NULL
              OR match.task_assignment_id IS NOT NULL
              OR match.ops_case_id IS NOT NULL
              OR match.notification_id IS NOT NULL
              OR match.match_status='MATERIALIZED'
            )
          ), issues AS (
            SELECT count(*) FILTER (WHERE
              output_id IS NULL OR typed_output_id IS NULL
              OR physical_output_id IS NULL
              OR output_id<>typed_output_id
              OR typed_output_id<>physical_output_id
              OR canonical_output_key IS NULL
              OR physical_output_key IS DISTINCT FROM canonical_output_key
            )::bigint AS missing_count,
            (SELECT count(*) FROM (
              SELECT output_type,canonical_output_key
              FROM candidates
              WHERE canonical_output_key IS NOT NULL
                AND typed_output_id IS NOT NULL
              GROUP BY output_type,canonical_output_key
              HAVING count(DISTINCT typed_output_id)>1
            ) conflict)::bigint AS conflict_count,
            (SELECT count(*) FROM (
              SELECT output_type,typed_output_id
              FROM candidates WHERE typed_output_id IS NOT NULL
              GROUP BY output_type,typed_output_id
              HAVING count(DISTINCT canonical_output_key)>1
            ) duplicate)::bigint AS duplicate_count,
            count(*)::bigint AS candidate_count,
            count(*) FILTER (WHERE
              typed_output_id IS NOT NULL
              AND physical_output_id=typed_output_id
              AND output_id=typed_output_id
              AND physical_output_key IS NOT DISTINCT FROM
                  canonical_output_key
            )::bigint AS mapped_count
            FROM candidates
          ), mapping AS (
            SELECT coalesce(jsonb_agg(jsonb_build_object(
              'trigger_match_id',trigger_match_id,
              'output_type',output_type,
              'canonical_output_key',canonical_output_key,
              'typed_output_id',typed_output_id,
              'physical_output_key',physical_output_key,
              'match_status',match_status,
              'materialization_origin',materialization_origin
            ) ORDER BY output_type COLLATE "C",
              canonical_output_key COLLATE "C",
              trigger_match_id COLLATE "C"),'[]'::jsonb) AS value
            FROM candidates
          )
          SELECT jsonb_build_object(
            'protocol_version','dts-v2-legacy-output-mapping-v1',
            'candidate_count',issues.candidate_count,
            'mapped_count',issues.mapped_count,
            'missing_count',issues.missing_count,
            'conflict_count',issues.conflict_count,
            'duplicate_count',issues.duplicate_count,
            'issue_count',issues.missing_count+issues.conflict_count+
              issues.duplicate_count,
            'mapping_hash',public.dts_canonical_json_sha256_v1(mapping.value)
          ) FROM issues,mapping
        $$;

        CREATE FUNCTION public.dts_v2_cutover_technical_gate_manifest_v1(
          p_evaluation_as_of timestamptz
        ) RETURNS jsonb
        LANGUAGE plpgsql STABLE SECURITY DEFINER
        SET search_path=pg_catalog,public
        AS $$
        DECLARE compat_provider text:='UNAVAILABLE';
        DECLARE compat_count bigint;
        DECLARE full_provider text:='UNAVAILABLE';
        DECLARE dirty_count bigint;
        DECLARE outbox_pending bigint;
        DECLARE outbox_dead bigint;
        DECLARE issue_count bigint;
        DECLARE incomplete_scope bigint;
        DECLARE favorite_count bigint;
        DECLARE legacy_count bigint;
        DECLARE catalog_count bigint;
        DECLARE template_count bigint;
        BEGIN
          IF p_evaluation_as_of IS NULL
             OR p_evaluation_as_of>clock_timestamp() THEN
            RAISE EXCEPTION 'DTS_V2_TECHNICAL_GATE_TIME_INVALID'
              USING ERRCODE='22023';
          END IF;
          IF to_regprocedure('public.dts_v1_compat_dirty_not_complete_count_v1()') IS NOT NULL THEN
            EXECUTE
              'SELECT public.dts_v1_compat_dirty_not_complete_count_v1()'
              INTO compat_count;
            IF compat_count IS NULL OR compat_count<0 THEN
              RAISE EXCEPTION 'DTS_V1_COMPAT_DIRTY_PROVIDER_INVALID'
                USING ERRCODE='23514';
            END IF;
            compat_provider:='AVAILABLE';
          END IF;
          IF to_regprocedure('public.dts_v2_full_reconciliation_manifest_v1(timestamptz)') IS NOT NULL THEN
            full_provider:='AVAILABLE';
          END IF;
          SELECT count(*) INTO dirty_count
          FROM public.dts_dirty_keys WHERE status<>'COMPLETED';
          SELECT count(*) FILTER (WHERE status='PENDING'),
                 count(*) FILTER (WHERE status='DEAD_LETTER')
          INTO outbox_pending,outbox_dead
          FROM public.outbox_events
          WHERE event_type IN (
            'source_wide.changed.v2','task.materialization.requested.v2'
          ) AND status<>'PUBLISHED';
          SELECT count(*) INTO issue_count
          FROM public.dts_ingest_issues WHERE status='OPEN';
          WITH required(source_region,source_table) AS (
            VALUES ('dom','dom_appoint'),('dom','dom_complaint'),('dom','dom_complaint_cate'),('dom','dom_grading_label'),('dom','dom_grading_label_log'),('dom','dom_qa_task_close_camera_record'),('dom','dom_teacher'),('dom','dom_teacher_absent_reason'),('dom','dom_teacher_blacklist'),('dom','dom_teacher_certification'),('dom','dom_teacher_class_schedule'),('dom','dom_teacher_favorite'),('dom','dom_teacher_penalty'),('dom','dom_user_complaint'),('dom','dom_user_teacher_grading'),('ovs','ovs_appoint'),('ovs','ovs_complaint'),('ovs','ovs_grading_label'),('ovs','ovs_grading_label_log'),('ovs','ovs_qa_task_close_camera_record'),('ovs','ovs_teacher_blacklist'),('ovs','ovs_teacher_favorite'),('ovs','ovs_user_complaint'),('ovs','ovs_user_teacher_grading')
          )
          SELECT count(*) INTO incomplete_scope
          FROM required
          LEFT JOIN public.dts_source_scope_states scope
            ON scope.source_region=required.source_region
           AND scope.source_table=required.source_table
           AND scope.scope_kind='CURRENT'
           AND scope.scope_level='GLOBAL' AND scope.scope_key='*'
           AND scope.state='COMPLETE'
           AND scope.active_snapshot_id IS NOT NULL
          WHERE scope.source_region IS NULL;
          SELECT count(*) INTO favorite_count
          FROM public.course_favorite_observations
          WHERE observed_at<=p_evaluation_as_of
            AND status NOT IN (
              'CONFIRMED_TRUE','CONFIRMED_FALSE','INVALIDATED','VOIDED'
            );
          legacy_count:=(
            public.dts_v2_legacy_output_mapping_manifest_v1()
              ->>'issue_count'
          )::bigint;
          SELECT count(*) INTO catalog_count
          FROM public.complaint_rule_imports WHERE status='PUBLISHED';
          SELECT count(*) INTO template_count
          FROM public.task_templates WHERE status='PUBLISHED';
          RETURN jsonb_build_object(
            'protocol_version','dts-v2-cutover-technical-gate-v1',
            'full_reconciliation_provider',full_provider,
            'compat_dirty_provider',compat_provider,
            'dirty_not_complete_count',dirty_count,
            'compat_dirty_not_complete_count',compat_count,
            'v2_outbox_pending_count',outbox_pending,
            'v2_outbox_dead_letter_count',outbox_dead,
            'open_ingest_issue_count',issue_count,
            'incomplete_source_scope_count',incomplete_scope,
            'due_favorite_unsettled_count',favorite_count,
            'legacy_output_issue_count',legacy_count,
            'published_complaint_catalog_count',catalog_count,
            'published_task_template_count',template_count
          );
        END
        $$;

        CREATE FUNCTION public.dts_v2_technical_gate_passes_v1(
          p_manifest jsonb
        ) RETURNS boolean
        LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
        SET search_path=pg_catalog,public
        AS $$
          SELECT p_manifest=jsonb_build_object(
            'protocol_version','dts-v2-cutover-technical-gate-v1',
            'full_reconciliation_provider','AVAILABLE',
            'compat_dirty_provider','AVAILABLE',
            'dirty_not_complete_count',0,
            'compat_dirty_not_complete_count',0,
            'v2_outbox_pending_count',0,
            'v2_outbox_dead_letter_count',0,
            'open_ingest_issue_count',0,
            'incomplete_source_scope_count',0,
            'due_favorite_unsettled_count',0,
            'legacy_output_issue_count',0,
            'published_complaint_catalog_count',1,
            'published_task_template_count',14
          )
        $$;

        REVOKE ALL ON FUNCTION
          public.dts_v2_legacy_output_mapping_manifest_v1(),
          public.dts_v2_cutover_technical_gate_manifest_v1(timestamptz),
          public.dts_v2_technical_gate_passes_v1(jsonb)
        FROM PUBLIC;

CREATE FUNCTION public.dts_v2_read_full_reconciliation_manifest_v1(
          p_evaluation_as_of timestamptz,
          p_source_fence_hash text,
          p_source_profile_manifest_sha256 text
        ) RETURNS jsonb
        LANGUAGE plpgsql STABLE SECURITY DEFINER
        SET search_path=pg_catalog,public
        AS $$
        DECLARE manifest jsonb;
        BEGIN
          IF to_regprocedure('public.dts_v2_full_reconciliation_manifest_v1(timestamptz)') IS NULL THEN
            RAISE EXCEPTION 'DTS_V2_FULL_RECONCILIATION_UNAVAILABLE'
              USING ERRCODE='55000';
          END IF;
          EXECUTE
            'SELECT public.dts_v2_full_reconciliation_manifest_v1($1)'
            INTO manifest USING p_evaluation_as_of;
          IF jsonb_typeof(manifest)<>'object'
             OR manifest<>jsonb_build_object(
               'protocol_version',
                 'dts-v2-full-reconciliation-manifest-v1',
               'evaluation_as_of',manifest->>'evaluation_as_of',
               'source_fence_hash',manifest->>'source_fence_hash',
               'source_profile_manifest_sha256',
                 manifest->>'source_profile_manifest_sha256',
               'result_types',manifest->'result_types',
               'v1_result_manifest',manifest->'v1_result_manifest',
               'v2_result_manifest',manifest->'v2_result_manifest'
             )
             OR manifest->>'evaluation_as_of'<>to_char(
                  p_evaluation_as_of AT TIME ZONE 'UTC',
                  'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'
                )
             OR manifest->>'source_fence_hash'<>p_source_fence_hash
             OR manifest->>'source_profile_manifest_sha256'<>
                  p_source_profile_manifest_sha256
             OR manifest->'result_types'<>to_jsonb(
                  ARRAY['TEACHER_WIDE','LESSON_SCORE','LESSON_COMPONENT_SETTLEMENT','FAVORITE_OBSERVATION','FAVORITE_ATTRIBUTION','TRIGGER_MATCH','TASK_PLAN','CASE_PLAN','NOTIFICATION_PLAN','SCORE_ACCOUNT','SCORE_COMPONENT_ACCOUNT','SCORE_ENTRY_PLAN','QUALIFICATION','OUTBOX_COVERAGE']::text[]
                )
             OR NOT public.dts_v2_result_manifest_valid_v1(
                  manifest->'v1_result_manifest'
                )
             OR NOT public.dts_v2_result_manifest_valid_v1(
                  manifest->'v2_result_manifest'
                )
             OR manifest->'v1_result_manifest'<>
                  manifest->'v2_result_manifest' THEN
            RAISE EXCEPTION 'DTS_V2_FULL_RECONCILIATION_INVALID'
              USING ERRCODE='23514';
          END IF;
          RETURN manifest;
        END
        $$;
        REVOKE ALL ON FUNCTION
          public.dts_v2_read_full_reconciliation_manifest_v1(
            timestamptz,text,text
          )
        FROM PUBLIC;

CREATE FUNCTION public.guard_dts_projection_route_v1()
        RETURNS trigger
        LANGUAGE plpgsql
        SET search_path=pg_catalog,public
        AS $$
        BEGIN
          IF current_setting('tit.dts_projection_switch_v1',true)<>'on' THEN
            RAISE EXCEPTION 'DTS_PROJECTION_ROUTE_COMMAND_REQUIRED'
              USING ERRCODE='42501';
          END IF;
          IF TG_OP='DELETE' THEN
            RAISE EXCEPTION 'DTS_PROJECTION_ROUTE_DELETE_FORBIDDEN'
              USING ERRCODE='42501';
          ELSIF TG_OP='INSERT' THEN
            RETURN NEW;
          END IF;
          IF NEW.route_id IS DISTINCT FROM OLD.route_id
             OR NEW.route_contract_version IS DISTINCT FROM
                  OLD.route_contract_version
             OR NEW.row_version<>OLD.row_version+1 THEN
            RAISE EXCEPTION 'DTS_PROJECTION_ROUTE_VERSION_INVALID'
              USING ERRCODE='23514';
          END IF;
          RETURN NEW;
        END
        $$;

        CREATE FUNCTION public.guard_dts_source_profile_approval_v2()
        RETURNS trigger
        LANGUAGE plpgsql
        SET search_path=pg_catalog,public
        AS $$
        BEGIN
          IF TG_OP<>'INSERT' THEN
            RAISE EXCEPTION 'DTS_SOURCE_PROFILE_APPROVAL_IMMUTABLE'
              USING ERRCODE='42501';
          END IF;
          IF current_setting(
               'tit.dts_source_profile_approval_migration',true
             )<>'on' THEN
            RAISE EXCEPTION 'DTS_SOURCE_PROFILE_APPROVAL_MIGRATION_REQUIRED'
              USING ERRCODE='42501';
          END IF;
          IF NOT public.dts_v2_source_profile_vector_valid_v1(
               NEW.profile_vector
             )
             OR NEW.profile_vector_hash<>public.dts_canonical_json_sha256_v1(
                  NEW.profile_vector
                ) THEN
            RAISE EXCEPTION 'DTS_SOURCE_PROFILE_APPROVAL_INVALID'
              USING ERRCODE='23514';
          END IF;
          RETURN NEW;
        END
        $$;

        CREATE FUNCTION public.guard_dts_projection_cutover_evidence_v1()
        RETURNS trigger
        LANGUAGE plpgsql
        SET search_path=pg_catalog,public
        AS $$
        BEGIN
          IF TG_OP<>'INSERT' OR current_setting(
               'tit.dts_projection_cutover_evidence_v1',true
             )<>'on' THEN
            RAISE EXCEPTION 'DTS_PROJECTION_CUTOVER_EVIDENCE_IMMUTABLE'
              USING ERRCODE='42501';
          END IF;
          RETURN NEW;
        END
        $$;

        REVOKE ALL ON FUNCTION
          public.guard_dts_projection_route_v1(),
          public.guard_dts_source_profile_approval_v2(),
          public.guard_dts_projection_cutover_evidence_v1()
        FROM PUBLIC;

        CREATE TRIGGER trg_guard_dts_projection_route_v1
        BEFORE INSERT OR UPDATE OR DELETE
        ON public.dts_projection_read_routes
        FOR EACH ROW EXECUTE FUNCTION public.guard_dts_projection_route_v1();
        CREATE TRIGGER trg_guard_dts_source_profile_approval_v2
        BEFORE INSERT OR UPDATE OR DELETE
        ON public.dts_source_profile_approvals_v2
        FOR EACH ROW
        EXECUTE FUNCTION public.guard_dts_source_profile_approval_v2();
        CREATE TRIGGER trg_guard_dts_v2_reconciliation_run_v1
        BEFORE INSERT OR UPDATE OR DELETE
        ON public.dts_v2_reconciliation_runs
        FOR EACH ROW
        EXECUTE FUNCTION public.guard_dts_projection_cutover_evidence_v1();
        CREATE TRIGGER trg_guard_dts_projection_switch_audit_v1
        BEFORE INSERT OR UPDATE OR DELETE
        ON public.dts_projection_switch_audits
        FOR EACH ROW
        EXECUTE FUNCTION public.guard_dts_projection_cutover_evidence_v1();

        SELECT set_config('tit.dts_projection_switch_v1','on',true);
        INSERT INTO public.dts_projection_read_routes(
          route_id,active_projection,route_contract_version,row_version,
          switched_by_run_id,switched_at,switched_by
        ) VALUES (
          'PRIMARY','V1_COMPAT','teacher-read-route-v1',1,
          NULL,NULL,'alembic:20260822_95_projection_cutover'
        );
        SELECT set_config('tit.dts_projection_switch_v1','off',true);

CREATE FUNCTION public.dts_projection_cutover_actor_allowed_v1()
        RETURNS boolean
        LANGUAGE sql STABLE SECURITY DEFINER
        SET search_path=pg_catalog,public
        AS $$
          SELECT coalesce(
                   nullif(current_setting('role',true),'none'),session_user
                 )='tit_growth_app'
              OR coalesce(
                   nullif(current_setting('role',true),'none'),session_user
                 )=(
                   SELECT pg_get_userbyid(relowner) FROM pg_class
                   WHERE oid='public.dts_projection_read_routes'::regclass
                 )
        $$;
        REVOKE ALL ON FUNCTION
          public.dts_projection_cutover_actor_allowed_v1()
        FROM PUBLIC;

        CREATE FUNCTION public.preview_dts_v2_reconciliation_evidence_v1(
          p_evaluation_as_of timestamptz,
          p_source_profile_manifest_sha256 text
        ) RETURNS jsonb
        LANGUAGE plpgsql VOLATILE SECURITY DEFINER
        SET search_path=pg_catalog,public
        AS $$
        DECLARE control_row public.dts_pipeline_control%ROWTYPE;
        DECLARE route_row public.dts_projection_read_routes%ROWTYPE;
        DECLARE approval_row public.dts_source_profile_approvals_v2%ROWTYPE;
        DECLARE fence_vector jsonb;
        DECLARE fence_hash text;
        DECLARE full_manifest jsonb;
        DECLARE legacy_manifest jsonb;
        DECLARE technical_manifest jsonb;
        BEGIN
          IF NOT public.dts_projection_cutover_actor_allowed_v1() THEN
            RAISE EXCEPTION 'DTS_PROJECTION_CUTOVER_ROLE_REQUIRED'
              USING ERRCODE='42501';
          END IF;
          PERFORM pg_advisory_xact_lock_shared(
            hashtextextended('tit:dts-v2-cutover',0)
          );
          SELECT * INTO STRICT control_row
          FROM public.dts_pipeline_control WHERE control_id='PRIMARY';
          SELECT * INTO STRICT route_row
          FROM public.dts_projection_read_routes WHERE route_id='PRIMARY';
          IF control_row.mode NOT IN (
               'V1_COMPAT_DUAL_CAPTURE','ROLLED_BACK'
             ) OR route_row.active_projection<>'V1_COMPAT'
             OR control_row.time_catchup_status='PENDING'
             OR p_evaluation_as_of IS NULL
             OR p_evaluation_as_of>clock_timestamp() THEN
            RAISE EXCEPTION 'DTS_V2_RECONCILIATION_BASE_STATE_INVALID'
              USING ERRCODE='55000';
          END IF;
          SELECT * INTO STRICT approval_row
          FROM public.dts_source_profile_approvals_v2
          WHERE manifest_sha256=p_source_profile_manifest_sha256
            AND status='APPROVED';
          IF approval_row.manifest_version<>1
             OR approval_row.profile_vector_hash<>
                  public.dts_canonical_json_sha256_v1(
                    approval_row.profile_vector
                  )
             OR NOT public.dts_v2_source_profile_vector_valid_v1(
                  approval_row.profile_vector
                )
             OR NOT public.dts_v2_source_rows_match_profile_v1(
                  approval_row.profile_vector
                ) THEN
            RAISE EXCEPTION 'DTS_V2_SOURCE_PROFILE_NOT_APPROVED'
              USING ERRCODE='55000';
          END IF;
          fence_vector:=public.dts_v2_current_fence_vector_v1();
          fence_hash:=public.dts_canonical_json_sha256_v1(fence_vector);
          full_manifest:=
            public.dts_v2_read_full_reconciliation_manifest_v1(
              p_evaluation_as_of,fence_hash,
              approval_row.manifest_sha256
            );
          legacy_manifest:=
            public.dts_v2_legacy_output_mapping_manifest_v1();
          technical_manifest:=
            public.dts_v2_cutover_technical_gate_manifest_v1(
              p_evaluation_as_of
            );
          RETURN jsonb_build_object(
            'protocol_version','dts-v2-reconciliation-pass-v1',
            'base_control_version',control_row.row_version,
            'base_route_version',route_row.row_version,
            'target_projection_generation',
              control_row.projection_generation+1,
            'source_profile_manifest_version',
              approval_row.manifest_version,
            'source_profile_manifest_sha256',
              approval_row.manifest_sha256,
            'source_profile_vector',approval_row.profile_vector,
            'source_fence_hash',fence_hash,
            'v1_result_manifest',full_manifest->'v1_result_manifest',
            'v2_result_manifest',full_manifest->'v2_result_manifest',
            'legacy_output_manifest',legacy_manifest,
            'technical_gate_manifest',technical_manifest,
            'evaluation_as_of',to_char(
              p_evaluation_as_of AT TIME ZONE 'UTC',
              'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'
            )
          );
        EXCEPTION WHEN no_data_found OR too_many_rows THEN
          RAISE EXCEPTION 'DTS_V2_RECONCILIATION_BASE_STATE_UNAVAILABLE'
            USING ERRCODE='55000';
        END
        $$;

        CREATE FUNCTION public.record_dts_v2_reconciliation_pass_v1(
          p_run_id text,p_request jsonb,p_expected_request_hash text
        ) RETURNS jsonb
        LANGUAGE plpgsql VOLATILE SECURITY DEFINER
        SET search_path=pg_catalog,public
        AS $$
        DECLARE actor_name text:=coalesce(
          nullif(current_setting('role',true),'none'),session_user
        );
        DECLARE existing public.dts_v2_reconciliation_runs%ROWTYPE;
        DECLARE control_row public.dts_pipeline_control%ROWTYPE;
        DECLARE route_row public.dts_projection_read_routes%ROWTYPE;
        DECLARE approval_row public.dts_source_profile_approvals_v2%ROWTYPE;
        DECLARE request_hash_value text;
        DECLARE expected_request jsonb;
        DECLARE evaluation_value timestamptz;
        DECLARE fence_vector jsonb;
        DECLARE fence_hash text;
        DECLARE full_manifest jsonb;
        DECLARE legacy_manifest jsonb;
        DECLARE technical_manifest jsonb;
        BEGIN
          IF NOT public.dts_projection_cutover_actor_allowed_v1() THEN
            RAISE EXCEPTION 'DTS_PROJECTION_CUTOVER_ROLE_REQUIRED'
              USING ERRCODE='42501';
          END IF;
          IF nullif(btrim(p_run_id),'') IS NULL OR length(p_run_id)>128
             OR jsonb_typeof(p_request)<>'object'
             OR p_expected_request_hash !~ '^[0-9a-f]{64}$'
             OR public.dts_v2_json_has_forbidden_student_key(p_request) THEN
            RAISE EXCEPTION 'DTS_V2_RECONCILIATION_REQUEST_INVALID'
              USING ERRCODE='22023';
          END IF;
          request_hash_value:=public.dts_canonical_json_sha256_v1(p_request);
          IF request_hash_value<>p_expected_request_hash THEN
            RAISE EXCEPTION 'DTS_V2_RECONCILIATION_REQUEST_HASH_MISMATCH'
              USING ERRCODE='23514';
          END IF;
          PERFORM pg_advisory_xact_lock(
            hashtextextended('tit:dts-v2-cutover',0)
          );
          SELECT * INTO existing FROM public.dts_v2_reconciliation_runs
          WHERE run_id=p_run_id;
          IF FOUND THEN
            IF existing.request_hash<>request_hash_value THEN
              RAISE EXCEPTION 'DTS_V2_RECONCILIATION_RUN_CONFLICT'
                USING ERRCODE='23505';
            END IF;
            RETURN jsonb_build_object(
              'status','REPLAYED','run_id',existing.run_id,
              'request_hash',existing.request_hash,
              'target_projection_generation',
                existing.target_projection_generation,
              'source_fence_hash',existing.source_fence_hash
            );
          END IF;
          BEGIN
            evaluation_value:=(p_request->>'evaluation_as_of')::timestamptz;
          EXCEPTION WHEN OTHERS THEN
            RAISE EXCEPTION 'DTS_V2_RECONCILIATION_REQUEST_INVALID'
              USING ERRCODE='22023';
          END;
          expected_request:=jsonb_build_object(
            'protocol_version','dts-v2-reconciliation-pass-v1',
            'base_control_version',
              (p_request->>'base_control_version')::bigint,
            'base_route_version',
              (p_request->>'base_route_version')::bigint,
            'target_projection_generation',
              (p_request->>'target_projection_generation')::bigint,
            'source_profile_manifest_version',
              (p_request->>'source_profile_manifest_version')::integer,
            'source_profile_manifest_sha256',
              p_request->>'source_profile_manifest_sha256',
            'source_profile_vector',p_request->'source_profile_vector',
            'source_fence_hash',p_request->>'source_fence_hash',
            'v1_result_manifest',p_request->'v1_result_manifest',
            'v2_result_manifest',p_request->'v2_result_manifest',
            'legacy_output_manifest',p_request->'legacy_output_manifest',
            'technical_gate_manifest',p_request->'technical_gate_manifest',
            'evaluation_as_of',to_char(
              evaluation_value AT TIME ZONE 'UTC',
              'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'
            )
          );
          IF p_request<>expected_request
             OR evaluation_value>clock_timestamp()
             OR NOT public.dts_v2_source_profile_vector_valid_v1(
                  p_request->'source_profile_vector'
                )
             OR NOT public.dts_v2_result_manifest_valid_v1(
                  p_request->'v1_result_manifest'
                )
             OR NOT public.dts_v2_result_manifest_valid_v1(
                  p_request->'v2_result_manifest'
                ) THEN
            RAISE EXCEPTION 'DTS_V2_RECONCILIATION_REQUEST_INVALID'
              USING ERRCODE='22023';
          END IF;
          SELECT * INTO STRICT control_row
          FROM public.dts_pipeline_control WHERE control_id='PRIMARY'
          FOR UPDATE;
          SELECT * INTO STRICT route_row
          FROM public.dts_projection_read_routes WHERE route_id='PRIMARY'
          FOR UPDATE;
          IF control_row.mode NOT IN (
               'V1_COMPAT_DUAL_CAPTURE','ROLLED_BACK'
             ) OR route_row.active_projection<>'V1_COMPAT'
             OR control_row.time_catchup_status='PENDING'
             OR control_row.row_version<>
                  (p_request->>'base_control_version')::bigint
             OR route_row.row_version<>
                  (p_request->>'base_route_version')::bigint
             OR control_row.projection_generation+1<>
                  (p_request->>'target_projection_generation')::bigint THEN
            RAISE EXCEPTION 'DTS_V2_RECONCILIATION_BASE_STATE_CHANGED'
              USING ERRCODE='40001';
          END IF;
          SELECT * INTO STRICT approval_row
          FROM public.dts_source_profile_approvals_v2
          WHERE manifest_sha256=
                  p_request->>'source_profile_manifest_sha256'
            AND status='APPROVED';
          IF approval_row.manifest_version<>
               (p_request->>'source_profile_manifest_version')::integer
             OR approval_row.profile_vector<>
                  p_request->'source_profile_vector'
             OR approval_row.profile_vector_hash<>
                  public.dts_canonical_json_sha256_v1(
                    approval_row.profile_vector
                  )
             OR NOT public.dts_v2_source_rows_match_profile_v1(
                  approval_row.profile_vector
                ) THEN
            RAISE EXCEPTION 'DTS_V2_SOURCE_PROFILE_NOT_APPROVED'
              USING ERRCODE='55000';
          END IF;
          fence_vector:=public.dts_v2_current_fence_vector_v1();
          fence_hash:=public.dts_canonical_json_sha256_v1(fence_vector);
          IF fence_hash<>p_request->>'source_fence_hash' THEN
            RAISE EXCEPTION 'DTS_V2_RECONCILIATION_SOURCE_FENCE_CHANGED'
              USING ERRCODE='40001';
          END IF;
          full_manifest:=
            public.dts_v2_read_full_reconciliation_manifest_v1(
              evaluation_value,fence_hash,approval_row.manifest_sha256
            );
          legacy_manifest:=
            public.dts_v2_legacy_output_mapping_manifest_v1();
          technical_manifest:=
            public.dts_v2_cutover_technical_gate_manifest_v1(
              evaluation_value
            );
          IF full_manifest->'v1_result_manifest'<>
               p_request->'v1_result_manifest'
             OR full_manifest->'v2_result_manifest'<>
               p_request->'v2_result_manifest'
             OR legacy_manifest<>p_request->'legacy_output_manifest'
             OR (legacy_manifest->>'issue_count')::bigint<>0
             OR technical_manifest<>p_request->'technical_gate_manifest'
             OR NOT public.dts_v2_technical_gate_passes_v1(
                  technical_manifest
                ) THEN
            RAISE EXCEPTION 'DTS_V2_RECONCILIATION_NOT_PASS'
              USING ERRCODE='55000';
          END IF;
          PERFORM set_config(
            'tit.dts_projection_cutover_evidence_v1','on',true
          );
          INSERT INTO public.dts_v2_reconciliation_runs(
            run_id,request_hash,base_mode,base_control_version,
            base_route_version,target_projection_generation,
            source_profile_manifest_version,
            source_profile_manifest_sha256,source_profile_vector,
            source_profile_vector_hash,source_fence_vector,
            source_fence_hash,full_reconciliation_manifest,
            full_reconciliation_manifest_hash,v1_result_manifest,
            v1_result_manifest_hash,v2_result_manifest,
            v2_result_manifest_hash,legacy_output_manifest,
            legacy_output_manifest_hash,technical_gate_manifest,
            technical_gate_manifest_hash,evaluation_as_of,
            evaluation_business_date_beijing,result_status,
            recorded_at,recorded_by
          ) VALUES (
            p_run_id,request_hash_value,control_row.mode,
            control_row.row_version,route_row.row_version,
            control_row.projection_generation+1,
            approval_row.manifest_version,approval_row.manifest_sha256,
            approval_row.profile_vector,approval_row.profile_vector_hash,
            fence_vector,fence_hash,full_manifest,
            public.dts_canonical_json_sha256_v1(full_manifest),
            full_manifest->'v1_result_manifest',
            public.dts_canonical_json_sha256_v1(
              full_manifest->'v1_result_manifest'
            ),full_manifest->'v2_result_manifest',
            public.dts_canonical_json_sha256_v1(
              full_manifest->'v2_result_manifest'
            ),legacy_manifest,
            public.dts_canonical_json_sha256_v1(legacy_manifest),
            technical_manifest,
            public.dts_canonical_json_sha256_v1(technical_manifest),
            evaluation_value,
            (evaluation_value AT TIME ZONE 'Asia/Shanghai')::date,
            'PASS',clock_timestamp(),actor_name
          );
          PERFORM set_config(
            'tit.dts_projection_cutover_evidence_v1','off',true
          );
          RETURN jsonb_build_object(
            'status','APPLIED','run_id',p_run_id,
            'request_hash',request_hash_value,
            'target_projection_generation',
              control_row.projection_generation+1,
            'source_fence_hash',fence_hash
          );
        EXCEPTION WHEN no_data_found OR too_many_rows THEN
          RAISE EXCEPTION 'DTS_V2_RECONCILIATION_BASE_STATE_UNAVAILABLE'
            USING ERRCODE='55000';
        END
        $$;

        REVOKE ALL ON FUNCTION
          public.preview_dts_v2_reconciliation_evidence_v1(
            timestamptz,text
          ),
          public.record_dts_v2_reconciliation_pass_v1(text,jsonb,text)
        FROM PUBLIC;
        GRANT EXECUTE ON FUNCTION
          public.preview_dts_v2_reconciliation_evidence_v1(
            timestamptz,text
          ),
          public.record_dts_v2_reconciliation_pass_v1(text,jsonb,text)
        TO tit_growth_app;

CREATE FUNCTION public.switch_dts_projection_mode_v2(
          p_run_id text,p_expected_control_version bigint,
          p_expected_route_version bigint,p_target_mode text
        ) RETURNS jsonb
        LANGUAGE plpgsql VOLATILE SECURITY DEFINER
        SET search_path=pg_catalog,public
        AS $$
        DECLARE actor_name text:=coalesce(
          nullif(current_setting('role',true),'none'),session_user
        );
        DECLARE control_row public.dts_pipeline_control%ROWTYPE;
        DECLARE route_row public.dts_projection_read_routes%ROWTYPE;
        DECLARE run_row public.dts_v2_reconciliation_runs%ROWTYPE;
        DECLARE approval_row public.dts_source_profile_approvals_v2%ROWTYPE;
        DECLARE existing public.dts_projection_switch_audits%ROWTYPE;
        DECLARE request_payload jsonb;
        DECLARE request_hash_value text;
        DECLARE response_payload jsonb;
        DECLARE response_hash_value text;
        DECLARE target_projection text;
        DECLARE target_generation bigint;
        DECLARE fence_vector jsonb;
        DECLARE fence_hash text;
        DECLARE full_manifest jsonb;
        DECLARE legacy_manifest jsonb;
        DECLARE technical_manifest jsonb;
        DECLARE switch_time timestamptz;
        BEGIN
          IF NOT public.dts_projection_cutover_actor_allowed_v1() THEN
            RAISE EXCEPTION 'DTS_PROJECTION_CUTOVER_ROLE_REQUIRED'
              USING ERRCODE='42501';
          END IF;
          IF nullif(btrim(p_run_id),'') IS NULL OR length(p_run_id)>128
             OR p_expected_control_version<1
             OR p_expected_route_version<1
             OR p_target_mode NOT IN ('V2_PRIMARY','ROLLED_BACK') THEN
            RAISE EXCEPTION 'DTS_PROJECTION_SWITCH_REQUEST_INVALID'
              USING ERRCODE='22023';
          END IF;
          request_payload:=jsonb_build_object(
            'protocol_version','dts-projection-switch-command-v2',
            'run_id',p_run_id,
            'expected_control_version',p_expected_control_version,
            'expected_route_version',p_expected_route_version,
            'target_mode',p_target_mode
          );
          request_hash_value:=
            public.dts_canonical_json_sha256_v1(request_payload);
          PERFORM pg_advisory_xact_lock(
            hashtextextended('tit:dts-v2-cutover',0)
          );
          SELECT * INTO STRICT control_row
          FROM public.dts_pipeline_control WHERE control_id='PRIMARY'
          FOR UPDATE;
          SELECT * INTO STRICT route_row
          FROM public.dts_projection_read_routes WHERE route_id='PRIMARY'
          FOR UPDATE;
          switch_time:=clock_timestamp();
          SELECT * INTO existing FROM public.dts_projection_switch_audits
          WHERE switch_run_id=p_run_id;
          IF FOUND THEN
            IF existing.request_hash<>request_hash_value
               OR existing.to_mode<>p_target_mode
               OR control_row.mode<>existing.to_mode
               OR route_row.active_projection<>existing.to_projection
               OR control_row.projection_generation<>
                    existing.projection_generation
               OR control_row.row_version<>
                    existing.after_control_version
               OR route_row.row_version<>existing.after_route_version THEN
              RAISE EXCEPTION 'PROJECTION_ROUTE_CONFLICT'
                USING ERRCODE='23505';
            END IF;
            RETURN existing.response_payload ||
              jsonb_build_object('status','REPLAYED');
          END IF;
          IF control_row.row_version<>p_expected_control_version
             OR route_row.row_version<>p_expected_route_version
             OR control_row.time_catchup_status='PENDING' THEN
            RAISE EXCEPTION 'PROJECTION_ROUTE_CONFLICT'
              USING ERRCODE='40001';
          END IF;
          IF p_target_mode='V2_PRIMARY' THEN
            IF control_row.mode NOT IN (
                 'V1_COMPAT_DUAL_CAPTURE','ROLLED_BACK'
               ) OR route_row.active_projection<>'V1_COMPAT' THEN
              RAISE EXCEPTION 'PROJECTION_ROUTE_CONFLICT'
                USING ERRCODE='40001';
            END IF;
            SELECT * INTO STRICT run_row
            FROM public.dts_v2_reconciliation_runs
            WHERE run_id=p_run_id AND result_status='PASS'
            FOR SHARE;
            IF run_row.base_mode<>control_row.mode
               OR run_row.base_control_version<>control_row.row_version
               OR run_row.base_route_version<>route_row.row_version
               OR run_row.target_projection_generation<>
                    control_row.projection_generation+1 THEN
              RAISE EXCEPTION 'DTS_V2_RECONCILIATION_RUN_STALE'
                USING ERRCODE='40001';
            END IF;
            SELECT * INTO STRICT approval_row
            FROM public.dts_source_profile_approvals_v2
            WHERE manifest_sha256=
                    run_row.source_profile_manifest_sha256
              AND status='APPROVED';
            IF approval_row.profile_vector<>run_row.source_profile_vector
               OR approval_row.profile_vector_hash<>
                    run_row.source_profile_vector_hash
               OR NOT public.dts_v2_source_rows_match_profile_v1(
                    approval_row.profile_vector
                  ) THEN
              RAISE EXCEPTION 'DTS_V2_SOURCE_PROFILE_CHANGED'
                USING ERRCODE='40001';
            END IF;
            fence_vector:=public.dts_v2_current_fence_vector_v1();
            fence_hash:=public.dts_canonical_json_sha256_v1(fence_vector);
            full_manifest:=
              public.dts_v2_read_full_reconciliation_manifest_v1(
                run_row.evaluation_as_of,fence_hash,
                approval_row.manifest_sha256
              );
            legacy_manifest:=
              public.dts_v2_legacy_output_mapping_manifest_v1();
            technical_manifest:=
              public.dts_v2_cutover_technical_gate_manifest_v1(
                run_row.evaluation_as_of
              );
            IF fence_hash<>run_row.source_fence_hash
               OR full_manifest<>run_row.full_reconciliation_manifest
               OR public.dts_canonical_json_sha256_v1(full_manifest)<>
                    run_row.full_reconciliation_manifest_hash
               OR legacy_manifest<>run_row.legacy_output_manifest
               OR technical_manifest<>run_row.technical_gate_manifest
               OR NOT public.dts_v2_technical_gate_passes_v1(
                    technical_manifest
                  )
               OR (run_row.evaluation_as_of AT TIME ZONE
                    'Asia/Shanghai')::date<>
                    (switch_time AT TIME ZONE 'Asia/Shanghai')::date
               OR EXISTS (
                 SELECT 1 FROM public.course_favorite_observations
                 WHERE observed_at>run_row.evaluation_as_of
                   AND observed_at<=switch_time
               ) THEN
              RAISE EXCEPTION 'DTS_V2_CUTOVER_INPUT_CHANGED'
                USING ERRCODE='40001';
            END IF;
            target_projection:='V2';
            target_generation:=control_row.projection_generation+1;
            UPDATE public.dts_pipeline_control
            SET mode='V2_PRIMARY',row_version=row_version+1,
                projection_generation=target_generation,
                last_handoff_vector=fence_vector,
                last_handoff_vector_hash=fence_hash,
                last_handoff_run_id=p_run_id,
                time_catchup_status='COMPLETE',
                time_catchup_run_id=p_run_id,
                time_catchup_from=run_row.evaluation_as_of,
                time_catchup_through=switch_time,
                time_catchup_expected_count=0,
                time_catchup_expected_hash=
                  public.dts_canonical_json_sha256_v1('[]'::jsonb),
                changed_at=switch_time,changed_by=actor_name
            WHERE control_id='PRIMARY'
              AND row_version=p_expected_control_version;
          ELSE
            IF control_row.mode<>'V2_PRIMARY'
               OR route_row.active_projection<>'V2'
               OR control_row.last_handoff_vector_hash IS NULL THEN
              RAISE EXCEPTION 'PROJECTION_ROUTE_CONFLICT'
                USING ERRCODE='40001';
            END IF;
            target_projection:='V1_COMPAT';
            target_generation:=control_row.projection_generation;
            fence_hash:=control_row.last_handoff_vector_hash;
            UPDATE public.dts_pipeline_control
            SET mode='ROLLED_BACK',row_version=row_version+1,
                time_catchup_status='NOT_REQUIRED',
                time_catchup_run_id=NULL,time_catchup_from=NULL,
                time_catchup_through=NULL,
                time_catchup_expected_count=NULL,
                time_catchup_expected_hash=NULL,
                changed_at=switch_time,changed_by=actor_name
            WHERE control_id='PRIMARY'
              AND row_version=p_expected_control_version;
          END IF;
          IF NOT FOUND THEN
            RAISE EXCEPTION 'PROJECTION_ROUTE_CONFLICT'
              USING ERRCODE='40001';
          END IF;
          PERFORM set_config('tit.dts_projection_switch_v1','on',true);
          UPDATE public.dts_projection_read_routes
          SET active_projection=target_projection,
              row_version=row_version+1,switched_by_run_id=p_run_id,
              switched_at=switch_time,switched_by=actor_name
          WHERE route_id='PRIMARY'
            AND row_version=p_expected_route_version;
          PERFORM set_config('tit.dts_projection_switch_v1','off',true);
          IF NOT FOUND THEN
            RAISE EXCEPTION 'PROJECTION_ROUTE_CONFLICT'
              USING ERRCODE='40001';
          END IF;
          response_payload:=jsonb_build_object(
            'status','APPLIED','run_id',p_run_id,
            'request_hash',request_hash_value,
            'target_mode',p_target_mode,
            'active_projection',target_projection,
            'projection_generation',target_generation,
            'control_row_version',p_expected_control_version+1,
            'route_row_version',p_expected_route_version+1,
            'source_fence_hash',fence_hash
          );
          response_hash_value:=
            public.dts_canonical_json_sha256_v1(response_payload);
          PERFORM set_config(
            'tit.dts_projection_cutover_evidence_v1','on',true
          );
          INSERT INTO public.dts_projection_switch_audits(
            switch_run_id,request_hash,reconciliation_run_id,
            from_mode,to_mode,from_projection,to_projection,
            projection_generation,before_control_version,
            after_control_version,before_route_version,
            after_route_version,source_fence_hash,response_payload,
            response_hash,result_status,occurred_at,occurred_by
          ) VALUES (
            p_run_id,request_hash_value,
            CASE WHEN p_target_mode='V2_PRIMARY' THEN p_run_id END,
            control_row.mode,p_target_mode,route_row.active_projection,
            target_projection,target_generation,
            p_expected_control_version,p_expected_control_version+1,
            p_expected_route_version,p_expected_route_version+1,
            fence_hash,response_payload,response_hash_value,
            'APPLIED',switch_time,actor_name
          );
          PERFORM set_config(
            'tit.dts_projection_cutover_evidence_v1','off',true
          );
          RETURN response_payload;
        EXCEPTION WHEN no_data_found OR too_many_rows THEN
          RAISE EXCEPTION 'PROJECTION_ROUTE_CONFLICT'
            USING ERRCODE='40001';
        END
        $$;

        CREATE FUNCTION public.dts_projection_readiness_v1()
        RETURNS jsonb
        LANGUAGE plpgsql STABLE SECURITY DEFINER
        SET search_path=pg_catalog,public
        AS $$
        DECLARE control_row public.dts_pipeline_control%ROWTYPE;
        DECLARE route_row public.dts_projection_read_routes%ROWTYPE;
        DECLARE audit_row public.dts_projection_switch_audits%ROWTYPE;
        DECLARE run_row public.dts_v2_reconciliation_runs%ROWTYPE;
        DECLARE ready_value boolean:=false;
        DECLARE code_value text:='DTS_PROJECTION_STATE_UNAVAILABLE';
        DECLARE reconciliation_id text;
        BEGIN
          IF (SELECT count(*) FROM public.dts_pipeline_control)<>1
             OR (SELECT count(*) FROM public.dts_projection_read_routes)<>1
          THEN
            RETURN jsonb_build_object(
              'ready',false,'code',code_value
            );
          END IF;
          SELECT * INTO control_row FROM public.dts_pipeline_control
          WHERE control_id='PRIMARY';
          SELECT * INTO route_row FROM public.dts_projection_read_routes
          WHERE route_id='PRIMARY';
          IF route_row.route_contract_version<>'teacher-read-route-v1'
             OR control_row.time_catchup_status='PENDING' THEN
            code_value:='DTS_PROJECTION_MAINTENANCE';
          ELSIF (control_row.mode IN (
                    'V1_COMPAT_DUAL_CAPTURE','ROLLED_BACK'
                  ) AND route_row.active_projection<>'V1_COMPAT')
             OR (control_row.mode='V2_PRIMARY'
                  AND route_row.active_projection<>'V2') THEN
            code_value:='DTS_PROJECTION_ROUTE_MODE_MISMATCH';
          ELSIF control_row.mode='V1_COMPAT_DUAL_CAPTURE' THEN
            ready_value:=true;
            code_value:='READY_V1_COMPAT';
          ELSIF control_row.mode='ROLLED_BACK' THEN
            SELECT * INTO audit_row
            FROM public.dts_projection_switch_audits
            WHERE to_mode='ROLLED_BACK'
              AND after_control_version=control_row.row_version
              AND after_route_version=route_row.row_version
              AND projection_generation=control_row.projection_generation;
            IF FOUND THEN
              ready_value:=true;
              code_value:='READY_ROLLED_BACK';
            ELSE
              code_value:='DTS_PROJECTION_ROLLBACK_AUDIT_MISSING';
            END IF;
          ELSIF control_row.mode='V2_PRIMARY' THEN
            SELECT * INTO audit_row
            FROM public.dts_projection_switch_audits
            WHERE to_mode='V2_PRIMARY'
              AND after_control_version=control_row.row_version
              AND after_route_version=route_row.row_version
              AND projection_generation=control_row.projection_generation;
            IF NOT FOUND THEN
              code_value:='DTS_PROJECTION_SWITCH_AUDIT_MISSING';
            ELSE
              reconciliation_id:=audit_row.reconciliation_run_id;
              SELECT * INTO run_row FROM public.dts_v2_reconciliation_runs
              WHERE run_id=reconciliation_id AND result_status='PASS'
                AND target_projection_generation=
                    control_row.projection_generation;
              IF NOT FOUND THEN
                code_value:='DTS_V2_RECONCILIATION_PASS_MISSING';
              ELSIF control_row.time_catchup_status<>'COMPLETE' THEN
                code_value:='DTS_V2_TIME_CATCHUP_INCOMPLETE';
              ELSIF NOT EXISTS (
                SELECT 1 FROM public.dts_source_profile_approvals_v2 approval
                WHERE approval.manifest_sha256=
                        run_row.source_profile_manifest_sha256
                  AND approval.status='APPROVED'
                  AND approval.profile_vector=run_row.source_profile_vector
                  AND public.dts_v2_source_rows_match_profile_v1(
                        approval.profile_vector
                      )
              ) THEN
                code_value:='DTS_V2_SOURCE_PROFILE_NOT_APPROVED';
              ELSE
                ready_value:=true;
                code_value:='READY_V2_PRIMARY';
              END IF;
            END IF;
          ELSE
            code_value:='DTS_PROJECTION_MODE_UNKNOWN';
          END IF;
          RETURN jsonb_build_object(
            'ready',ready_value,'code',code_value,
            'mode',control_row.mode,
            'active_projection',route_row.active_projection,
            'projection_generation',control_row.projection_generation,
            'control_row_version',control_row.row_version,
            'route_row_version',route_row.row_version,
            'time_catchup_status',control_row.time_catchup_status,
            'reconciliation_run_id',reconciliation_id
          );
        EXCEPTION WHEN OTHERS THEN
          RETURN jsonb_build_object(
            'ready',false,'code','DTS_PROJECTION_STATE_UNAVAILABLE'
          );
        END
        $$;

        CREATE FUNCTION public.dts_projection_route_guard_v1()
        RETURNS text
        LANGUAGE plpgsql STABLE SECURITY DEFINER
        SET search_path=pg_catalog,public
        AS $$
        DECLARE readiness jsonb;
        BEGIN
          readiness:=public.dts_projection_readiness_v1();
          IF (readiness->>'ready')::boolean IS DISTINCT FROM true THEN
            RAISE EXCEPTION 'DTS_PROJECTION_READ_UNAVAILABLE:%',
              coalesce(readiness->>'code','UNKNOWN')
              USING ERRCODE='55000';
          END IF;
          RETURN readiness->>'active_projection';
        END
        $$;

        REVOKE ALL ON FUNCTION
          public.switch_dts_projection_mode_v2(text,bigint,bigint,text),
          public.dts_projection_readiness_v1(),
          public.dts_projection_route_guard_v1()
        FROM PUBLIC;
        GRANT EXECUTE ON FUNCTION
          public.switch_dts_projection_mode_v2(text,bigint,bigint,text),
          public.dts_projection_readiness_v1()
        TO tit_growth_app;

ALTER VIEW public.teacher_scorecard_current
          RENAME TO teacher_scorecard_pre_v2_route_v1;
        ALTER VIEW public.teacher_lesson_score_current
          RENAME TO teacher_lesson_score_pre_v2_route_v1;

        CREATE VIEW public.teacher_scorecard_current AS
        WITH route AS MATERIALIZED (
          SELECT public.dts_projection_route_guard_v1()
            AS active_projection
        )
        SELECT branch.*
        FROM route
        JOIN public.teacher_scorecard_v1_compat_v1 branch
          ON route.active_projection='V1_COMPAT'
        UNION ALL
        SELECT branch.*
        FROM route
        JOIN public.teacher_scorecard_v2_v1 branch
          ON route.active_projection='V2';

        CREATE VIEW public.teacher_lesson_score_current AS
        WITH route AS MATERIALIZED (
          SELECT public.dts_projection_route_guard_v1()
            AS active_projection
        ), selected AS (
          SELECT 'V1_COMPAT'::text AS projection_kind,branch.*
          FROM route
          JOIN public.teacher_lesson_score_v1_compat_v1 branch
            ON route.active_projection='V1_COMPAT'
          UNION ALL
          SELECT 'V2'::text AS projection_kind,branch.*
          FROM route
          JOIN public.teacher_lesson_score_v2_v1 branch
            ON route.active_projection='V2'
        )
        SELECT selected.teacher_id,selected.source_region,
          selected.source_appoint_id,selected.participation_seq,
          selected.participation_role,selected.visible_to_teacher,
          selected.lesson_sequence,selected.lesson_count,
          selected.scheduled_start_at,selected.lesson_local_date,
          selected.lesson_local_time,selected.lesson_lifecycle_status,
          selected.is_perfect,selected.valid_for_scoring,
          selected.evidence_status,selected.lesson_total_score,
          selected.score_rule_version,selected.updated_at,
          normalized.business_facts,dimension_set.dimensions
        FROM selected
        CROSS JOIN LATERAL (
          SELECT jsonb_build_object(
            'attendance',jsonb_build_object(
              'is_late',selected.business_facts#>'{attendance,is_late}',
              'is_early',selected.business_facts#>'{attendance,is_early}',
              'absence_reason_detail',selected.business_facts#>
                '{attendance,absence_reason_detail}',
              'late_evidence_status',CASE
                WHEN selected.business_facts->'attendance'
                       ? 'late_evidence_status'
                  THEN selected.business_facts#>
                    '{attendance,late_evidence_status}'
                ELSE to_jsonb('NOT_APPLICABLE'::text) END,
              'early_evidence_status',CASE
                WHEN selected.business_facts->'attendance'
                       ? 'early_evidence_status'
                  THEN selected.business_facts#>
                    '{attendance,early_evidence_status}'
                ELSE to_jsonb('NOT_APPLICABLE'::text) END
            ),
            'user_feedback',jsonb_build_object(
              'grading_classification',CASE
                WHEN selected.business_facts->'user_feedback'
                       ? 'grading_classification'
                  THEN selected.business_facts#>
                    '{user_feedback,grading_classification}'
                ELSE 'null'::jsonb END,
              'negative_score',CASE
                WHEN selected.business_facts->'user_feedback'
                       ? 'negative_score'
                  THEN selected.business_facts#>
                    '{user_feedback,negative_score}'
                ELSE 'null'::jsonb END,
              'labels',CASE
                WHEN selected.business_facts->'user_feedback' ? 'labels'
                  THEN selected.business_facts#>'{user_feedback,labels}'
                ELSE 'null'::jsonb END,
              'has_positive_feedback_tag',CASE
                WHEN selected.business_facts->'user_feedback'
                       ? 'has_positive_feedback_tag'
                  THEN selected.business_facts#>
                    '{user_feedback,has_positive_feedback_tag}'
                WHEN selected.business_facts#>>
                       '{user_feedback,grading_classification}'='POSITIVE'
                  THEN 'true'::jsonb
                WHEN selected.business_facts#>>
                       '{user_feedback,grading_classification}'='NEGATIVE'
                  THEN 'false'::jsonb
                ELSE 'null'::jsonb END,
              'has_negative_feedback_tag',CASE
                WHEN selected.business_facts->'user_feedback'
                       ? 'has_negative_feedback_tag'
                  THEN selected.business_facts#>
                    '{user_feedback,has_negative_feedback_tag}'
                WHEN selected.business_facts#>>
                       '{user_feedback,grading_classification}'='NEGATIVE'
                  THEN 'true'::jsonb
                WHEN selected.business_facts#>>
                       '{user_feedback,grading_classification}'='POSITIVE'
                  THEN 'false'::jsonb
                ELSE 'null'::jsonb END,
              'feedback_detail',CASE
                WHEN selected.business_facts->'user_feedback'
                       ? 'feedback_detail'
                  THEN selected.business_facts#>
                    '{user_feedback,feedback_detail}'
                ELSE 'null'::jsonb END,
              'favorite_attribution_status',CASE
                WHEN selected.business_facts->'user_feedback'
                       ? 'favorite_attribution_status'
                  THEN selected.business_facts#>
                    '{user_feedback,favorite_attribution_status}'
                ELSE to_jsonb('NOT_APPLICABLE'::text) END,
              'is_favorited',CASE
                WHEN selected.business_facts->'user_feedback'
                       ? 'is_favorited'
                  THEN selected.business_facts#>'{user_feedback,is_favorited}'
                WHEN selected.business_facts#>>
                       '{user_feedback,favorite_attribution_status}' IN (
                         'AWARDED','AWARDED_PENDING_EVIDENCE'
                       ) THEN 'true'::jsonb
                ELSE 'null'::jsonb END,
              'is_rebooked',CASE
                WHEN selected.business_facts->'user_feedback'
                       ? 'is_rebooked'
                  THEN selected.business_facts#>'{user_feedback,is_rebooked}'
                ELSE 'null'::jsonb END,
              'is_blocked',selected.business_facts#>
                '{user_feedback,is_blocked}'
            ),
            'classroom_quality',jsonb_build_object(
              'is_camera_off',selected.business_facts#>
                '{classroom_quality,is_camera_off}',
              'is_cpu_usage_high',selected.business_facts#>
                '{classroom_quality,is_cpu_usage_high}',
              'is_network_delay_high',selected.business_facts#>
                '{classroom_quality,is_network_delay_high}',
              'hardware_quality_passed',selected.business_facts#>
                '{classroom_quality,hardware_quality_passed}',
              'is_perfect',selected.business_facts#>
                '{classroom_quality,is_perfect}'
            ),
            'capacity',jsonb_build_object(
              'is_peak',selected.business_facts#>'{capacity,is_peak}'
            ),
            'complaint',jsonb_build_object(
              'has_complaint',CASE
                WHEN selected.business_facts->'complaint' ? 'has_complaint'
                  THEN selected.business_facts#>'{complaint,has_complaint}'
                ELSE 'null'::jsonb END,
              'has_valid_complaint',CASE
                WHEN selected.business_facts->'complaint'
                       ? 'has_valid_complaint'
                  THEN selected.business_facts#>
                    '{complaint,has_valid_complaint}'
                ELSE 'null'::jsonb END,
              'category_l1',selected.business_facts#>
                '{complaint,category_l1}',
              'category_l2',selected.business_facts#>
                '{complaint,category_l2}',
              'category_l3',selected.business_facts#>
                '{complaint,category_l3}',
              'level',CASE WHEN selected.business_facts->'complaint' ? 'level'
                THEN selected.business_facts#>'{complaint,level}'
                ELSE 'null'::jsonb END,
              'route',CASE WHEN selected.business_facts->'complaint' ? 'route'
                THEN selected.business_facts#>'{complaint,route}'
                ELSE 'null'::jsonb END,
              'evidence_status',CASE
                WHEN selected.business_facts->'complaint'
                       ? 'evidence_status'
                  THEN selected.business_facts#>
                    '{complaint,evidence_status}'
                ELSE to_jsonb('NOT_APPLICABLE'::text) END
            )
          ) AS business_facts
        ) normalized
        CROSS JOIN LATERAL (
          SELECT coalesce(jsonb_agg(
            dimension.value || jsonb_build_object(
              'evidence_status',CASE
                WHEN dimension.value ? 'evidence_status'
                  THEN dimension.value->'evidence_status'
                WHEN selected.valid_for_scoring
                  THEN to_jsonb('SOURCE_MISSING'::text)
                ELSE to_jsonb('NOT_APPLICABLE'::text) END,
              'evidence_coverage',CASE
                WHEN dimension.value ? 'evidence_coverage'
                  THEN dimension.value->'evidence_coverage'
                ELSE 'null'::jsonb END,
              'components',coalesce(
                dimension.value->'components','[]'::jsonb
              )
            ) ORDER BY dimension.ordinal
          ),'[]'::jsonb) AS dimensions
          FROM jsonb_array_elements(selected.dimensions)
            WITH ORDINALITY dimension(value,ordinal)
        ) dimension_set;

        COMMENT ON VIEW public.teacher_lesson_score_current IS
          'Stable routed lesson participation read. Identity is strictly source_region + source_appoint_id + participation_seq; no legacy lesson_id alias. Both routes expose one normalized business_facts/dimensions JSON contract; unavailable facts are null or NOT_APPLICABLE.';
        COMMENT ON VIEW public.teacher_scorecard_current IS
          'Stable routed teacher scorecard read selected atomically with DTS pipeline mode and route generation.';

        REVOKE ALL PRIVILEGES ON TABLE
          public.teacher_scorecard_current,
          public.teacher_lesson_score_current,
          public.teacher_scorecard_pre_v2_route_v1,
          public.teacher_lesson_score_pre_v2_route_v1,
          public.teacher_scorecard_v1_compat_v1,
          public.teacher_scorecard_v2_v1,
          public.teacher_lesson_score_v1_compat_v1,
          public.teacher_lesson_score_v2_v1
        FROM PUBLIC;
        DO $$
        DECLARE role_name text;
        BEGIN
          FOREACH role_name IN ARRAY ARRAY[
            'tit_growth_app','tit_teacher_crud'
          ] LOOP
            IF to_regrole(role_name) IS NOT NULL THEN
              EXECUTE format(
                'REVOKE ALL PRIVILEGES ON TABLE '
                'public.teacher_scorecard_pre_v2_route_v1,'
                'public.teacher_lesson_score_pre_v2_route_v1,'
                'public.teacher_scorecard_v1_compat_v1,'
                'public.teacher_scorecard_v2_v1,'
                'public.teacher_lesson_score_v1_compat_v1,'
                'public.teacher_lesson_score_v2_v1 FROM %I',role_name
              );
              EXECUTE format(
                'REVOKE ALL PRIVILEGES ON TABLE '
                'public.teacher_scorecard_current,'
                'public.teacher_lesson_score_current FROM %I',role_name
              );
            END IF;
          END LOOP;
          FOREACH role_name IN ARRAY ARRAY[
            'tit_teacher_crud'
          ] LOOP
            IF to_regrole(role_name) IS NOT NULL THEN
              EXECUTE format(
                'GRANT SELECT ON TABLE '
                'public.teacher_scorecard_current,'
                'public.teacher_lesson_score_current TO %I',role_name
              );
              EXECUTE format(
                'GRANT EXECUTE ON FUNCTION '
                'public.dts_projection_readiness_v1(),'
                'public.dts_projection_route_guard_v1() TO %I',role_name
              );
            END IF;
          END LOOP;
        END
        $$;

REVOKE ALL PRIVILEGES ON TABLE public.dts_projection_read_routes,public.dts_source_profile_approvals_v2,public.dts_v2_reconciliation_runs,public.dts_projection_switch_audits
        FROM PUBLIC,tit_growth_app;
        REVOKE CREATE ON SCHEMA public FROM tit_growth_app;
        GRANT USAGE ON SCHEMA public TO tit_growth_app;

        COMMENT ON TABLE public.dts_projection_read_routes IS
          'Singleton stable read-route fact. Only protected CAS switch/rollback may mutate it.';
        COMMENT ON TABLE public.dts_source_profile_approvals_v2 IS
          'Immutable production source-profile approvals. This revision intentionally seeds no default approval.';
        COMMENT ON TABLE public.dts_v2_reconciliation_runs IS
          'Immutable database-verified fourteen-result reconciliation PASS evidence; operator-supplied hashes alone are never trusted.';
        COMMENT ON TABLE public.dts_projection_switch_audits IS
          'Immutable idempotent cutover and rollback command audit.';

        DO $$
        DECLARE function_name text;
        DECLARE role_name text;
        BEGIN
          IF (SELECT count(*) FROM public.dts_projection_read_routes)<>1
             OR NOT EXISTS (
               SELECT 1 FROM public.dts_projection_read_routes
               WHERE route_id='PRIMARY'
                 AND active_projection='V1_COMPAT'
                 AND route_contract_version='teacher-read-route-v1'
                 AND row_version=1
             ) THEN
            RAISE EXCEPTION 'DTS_PROJECTION_ROUTE_INITIAL_STATE_INVALID';
          END IF;
          IF EXISTS (
            SELECT 1 FROM public.dts_source_profile_approvals_v2
          ) THEN
            RAISE EXCEPTION 'DTS_SOURCE_PROFILE_DEFAULT_APPROVAL_FORBIDDEN';
          END IF;
          FOREACH function_name IN ARRAY ARRAY[
            'preview_dts_v2_reconciliation_evidence_v1',
            'record_dts_v2_reconciliation_pass_v1',
            'switch_dts_projection_mode_v2',
            'dts_projection_readiness_v1',
            'dts_projection_route_guard_v1'
          ] LOOP
            IF NOT EXISTS (
              SELECT 1 FROM pg_proc
              WHERE pronamespace='public'::regnamespace
                AND proname=function_name AND prosecdef
                AND proconfig=ARRAY[
                  'search_path=pg_catalog, public'
                ]::text[]
            ) THEN
              RAISE EXCEPTION
                'DTS_PROJECTION_PROTECTED_FUNCTION_INVALID:%',
                function_name;
            END IF;
          END LOOP;
          IF NOT has_function_privilege(
               'tit_growth_app',
               'public.record_dts_v2_reconciliation_pass_v1('
               'text,jsonb,text)','EXECUTE'
             ) OR NOT has_function_privilege(
               'tit_growth_app',
               'public.switch_dts_projection_mode_v2('
               'text,bigint,bigint,text)','EXECUTE'
             ) OR has_table_privilege(
               'tit_growth_app',
               'public.dts_projection_read_routes','UPDATE'
             ) OR has_table_privilege(
               'tit_growth_app',
               'public.dts_v2_reconciliation_runs','INSERT'
             ) THEN
            RAISE EXCEPTION 'DTS_PROJECTION_CUTOVER_ACL_INVALID';
          END IF;
          IF EXISTS (
            SELECT 1 FROM information_schema.columns
            WHERE table_schema='public'
              AND table_name='teacher_lesson_score_current'
              AND column_name='lesson_id'
          ) OR NOT EXISTS (
            SELECT 1 FROM information_schema.columns
            WHERE table_schema='public'
              AND table_name='teacher_lesson_score_current'
              AND column_name='source_region'
          ) OR NOT EXISTS (
            SELECT 1 FROM information_schema.columns
            WHERE table_schema='public'
              AND table_name='teacher_lesson_score_current'
              AND column_name='source_appoint_id'
          ) OR NOT EXISTS (
            SELECT 1 FROM information_schema.columns
            WHERE table_schema='public'
              AND table_name='teacher_lesson_score_current'
              AND column_name='participation_seq'
          ) THEN
            RAISE EXCEPTION 'DTS_PROJECTION_LESSON_IDENTITY_INVALID';
          END IF;
          FOREACH role_name IN ARRAY ARRAY[
            'tit_growth_app','tit_teacher_crud'
          ] LOOP
            IF to_regrole(role_name) IS NOT NULL
               AND EXISTS (
                 SELECT 1 FROM unnest(ARRAY[
                   'public.teacher_scorecard_pre_v2_route_v1',
                   'public.teacher_lesson_score_pre_v2_route_v1',
                   'public.teacher_scorecard_v1_compat_v1',
                   'public.teacher_scorecard_v2_v1',
                   'public.teacher_lesson_score_v1_compat_v1',
                   'public.teacher_lesson_score_v2_v1'
                 ]::text[]) relation(name)
                 WHERE has_table_privilege(
                   role_name,relation.name,'SELECT'
                 )
               ) THEN
              RAISE EXCEPTION
                'DTS_PROJECTION_BRANCH_VIEW_GRANT_LEAK:%',role_name;
            END IF;
          END LOOP;
        END
        $$;

UPDATE alembic_version SET version_num='20260822_95_projection_cutover' WHERE alembic_version.version_num = '20260822_94_complaint_catalog_fanout';

-- Running upgrade 20260822_95_projection_cutover -> 20260822_96_compat_queue_gate

DO $$
        DECLARE relation_name text;
        BEGIN
          FOREACH relation_name IN ARRAY ARRAY[
            'dts_pipeline_control','dts_projection_read_routes',
            'dts_dirty_keys','dts_dirty_key_inputs',
            'teacher_qualifications'
          ] LOOP
            IF to_regclass('public.' || relation_name) IS NULL THEN
              RAISE EXCEPTION
                'DTS_V1_COMPAT_GATE_PREREQUISITE_MISSING:%',relation_name;
            END IF;
          END LOOP;
          IF to_regprocedure(
               'public._upsert_dts_dirty_key_input_v2('
               'text,text,text,text,text,jsonb,bigint,text)'
             ) IS NULL
             OR to_regrole('tit_growth_app') IS NULL
             OR to_regrole('tit_dts_ingest_runtime') IS NULL
             OR to_regrole('tit_growth_app') IS NULL THEN
            RAISE EXCEPTION 'DTS_V1_COMPAT_GATE_PREREQUISITE_MISSING';
          END IF;
        END
        $$;

        ALTER TABLE public.dts_pipeline_control
          ADD COLUMN IF NOT EXISTS qualification_grants_enabled boolean
          NOT NULL DEFAULT false;
        COMMENT ON COLUMN
          public.dts_pipeline_control.qualification_grants_enabled IS
          'Database-authoritative gate for first irreversible graduation '
          'and gold grants';

        ALTER TABLE public.dts_dirty_keys
          ADD COLUMN compat_status varchar(16) NOT NULL DEFAULT 'STANDBY',
          ADD COLUMN compat_required_work_revision bigint NOT NULL DEFAULT 0,
          ADD COLUMN compat_claimed_work_revision bigint,
          ADD COLUMN compat_completed_work_revision bigint NOT NULL DEFAULT 0,
          ADD COLUMN compat_attempt_count integer NOT NULL DEFAULT 0,
          ADD COLUMN compat_last_error_code varchar(128),
          ADD COLUMN compat_next_attempt_at timestamptz,
          ADD COLUMN compat_claimed_at timestamptz,
          ADD COLUMN compat_claimed_by varchar(128),
          ADD COLUMN compat_row_version bigint NOT NULL DEFAULT 1;

        UPDATE public.dts_dirty_keys AS dirty
        SET compat_required_work_revision=dirty.required_work_revision,
            compat_claimed_work_revision=NULL,
            compat_completed_work_revision=0,
            compat_status=CASE WHEN coalesce(
              (SELECT mode FROM public.dts_pipeline_control
               WHERE control_id='PRIMARY'),'V2_PRIMARY'
            ) IN ('V1_COMPAT_DUAL_CAPTURE','ROLLED_BACK')
              AND dirty.key_type IN ('COURSE','TEACHER','TEACHER_STUDENT','LABEL','COMPLAINT_CATEGORY')
              THEN 'PENDING' ELSE 'STANDBY' END,
            compat_attempt_count=0,compat_last_error_code=NULL,
            compat_next_attempt_at=CASE WHEN coalesce(
              (SELECT mode FROM public.dts_pipeline_control
               WHERE control_id='PRIMARY'),'V2_PRIMARY'
            ) IN ('V1_COMPAT_DUAL_CAPTURE','ROLLED_BACK')
              AND dirty.key_type IN ('COURSE','TEACHER','TEACHER_STUDENT','LABEL','COMPLAINT_CATEGORY')
              THEN transaction_timestamp() ELSE NULL END,
            compat_claimed_at=NULL,compat_claimed_by=NULL,
            compat_row_version=1;

        ALTER TABLE public.dts_dirty_keys
          ADD CONSTRAINT ck_dts_dirty_key_compat_state_v1 CHECK (
            compat_status IN (
              'STANDBY','PENDING','PROCESSING','RETRY','DEAD','COMPLETED'
            )
            AND compat_required_work_revision>=0
            AND compat_completed_work_revision>=0
            AND compat_completed_work_revision<=compat_required_work_revision
            AND (compat_claimed_work_revision IS NULL OR
                 (compat_claimed_work_revision>=1 AND
                  compat_claimed_work_revision<=
                    compat_required_work_revision))
            AND compat_attempt_count BETWEEN 0 AND 100
            AND compat_row_version>=1
            AND (
              (compat_status='STANDBY' AND compat_attempt_count=0
               AND compat_claimed_work_revision IS NULL
               AND compat_next_attempt_at IS NULL
               AND compat_claimed_at IS NULL AND compat_claimed_by IS NULL
               AND compat_last_error_code IS NULL)
              OR (compat_status='PENDING' AND compat_attempt_count=0
               AND compat_claimed_work_revision IS NULL
               AND compat_next_attempt_at IS NOT NULL
               AND compat_claimed_at IS NULL AND compat_claimed_by IS NULL
               AND compat_last_error_code IS NULL)
              OR (compat_status='PROCESSING'
               AND compat_claimed_work_revision IS NOT NULL
               AND compat_next_attempt_at IS NULL
               AND compat_claimed_at IS NOT NULL
               AND nullif(btrim(compat_claimed_by),'') IS NOT NULL
               AND compat_last_error_code IS NULL)
              OR (compat_status='RETRY' AND compat_attempt_count>=1
               AND compat_claimed_work_revision IS NULL
               AND compat_next_attempt_at IS NOT NULL
               AND compat_claimed_at IS NULL AND compat_claimed_by IS NULL
               AND compat_last_error_code IS NOT NULL)
              OR (compat_status='DEAD' AND compat_attempt_count>=1
               AND compat_claimed_work_revision IS NULL
               AND compat_next_attempt_at IS NULL
               AND compat_claimed_at IS NULL AND compat_claimed_by IS NULL
               AND compat_last_error_code IS NOT NULL)
              OR (compat_status='COMPLETED' AND compat_attempt_count=0
               AND compat_completed_work_revision>=
                    compat_required_work_revision
               AND compat_claimed_work_revision IS NULL
               AND compat_next_attempt_at IS NULL
               AND compat_claimed_at IS NULL AND compat_claimed_by IS NULL
               AND compat_last_error_code IS NULL)
            )
          );

        CREATE INDEX ix_dts_dirty_keys_compat_pending_v1
          ON public.dts_dirty_keys(
            updated_at,source_region,key_type,key_part_1,key_part_2
          ) WHERE compat_status='PENDING';
        CREATE INDEX ix_dts_dirty_keys_compat_retry_v1
          ON public.dts_dirty_keys(
            compat_next_attempt_at,updated_at,source_region,key_type,
            key_part_1,key_part_2
          ) WHERE compat_status='RETRY';

CREATE TABLE public.dts_qualification_gate_commands (
    command_id VARCHAR(128) NOT NULL,
    requested_enabled BOOLEAN NOT NULL,
    expected_control_row_version BIGINT NOT NULL,
    resulting_control_row_version BIGINT NOT NULL,
    reason VARCHAR(512) NOT NULL,
    command_sha256 VARCHAR(64) NOT NULL,
    fanout_count BIGINT NOT NULL,
    result_status VARCHAR(16) NOT NULL,
    executed_at TIMESTAMP WITH TIME ZONE DEFAULT clock_timestamp() NOT NULL,
    executed_by VARCHAR(128) NOT NULL,
    CONSTRAINT pk_dts_qualification_gate_commands PRIMARY KEY (command_id),
    CONSTRAINT ck_dts_qualification_gate_command_shape CHECK (expected_control_row_version>=1 AND resulting_control_row_version>=expected_control_row_version AND nullif(btrim(reason),'') IS NOT NULL AND command_sha256 ~ '^[0-9a-f]{64}$' AND fanout_count>=0 AND result_status='APPLIED')
);

COMMENT ON TABLE public.dts_qualification_gate_commands IS 'Immutable CAS commands for the database-authoritative irreversible qualification grant gate';

DROP TRIGGER IF EXISTS guard_dts_runtime_state_write
          ON public.dts_dirty_keys;
        CREATE FUNCTION public.guard_dts_dirty_key_state_write_v96()
        RETURNS trigger
        LANGUAGE plpgsql
        SET search_path=pg_catalog,public
        AS $$
        DECLARE actor_name text:=coalesce(
          nullif(current_setting('role',true),'none'),session_user
        );
        DECLARE compat_columns text[]:=ARRAY[
          'compat_status','compat_required_work_revision',
          'compat_claimed_work_revision','compat_completed_work_revision',
          'compat_attempt_count','compat_last_error_code',
          'compat_next_attempt_at','compat_claimed_at','compat_claimed_by',
          'compat_row_version'
        ];
        BEGIN
          IF TG_OP<>'DELETE' AND NEW.last_source_region='dom'
             AND NEW.key_type='TEACHER_STUDENT'
             AND NEW.key_part_2 !~ '^dom:v1:[0-9a-f]{64}$' THEN
            RAISE EXCEPTION
              'domestic DTS dirty state contains a forbidden student identifier'
              USING ERRCODE='23514';
          END IF;
          IF current_setting(
               'tit.dts_v1_compat_state_write',true
             )='on' THEN
            IF TG_OP<>'UPDATE'
               OR (to_jsonb(NEW)-compat_columns) IS DISTINCT FROM
                  (to_jsonb(OLD)-compat_columns) THEN
              RAISE EXCEPTION 'DTS_V1_COMPAT_WRITE_SCOPE_INVALID'
                USING ERRCODE='42501';
            END IF;
            RETURN NEW;
          END IF;
          IF actor_name<>'tit_dts_ingest_runtime' THEN
            IF TG_OP='DELETE' THEN RETURN OLD; END IF;
            RETURN NEW;
          END IF;
          IF TG_OP='DELETE' THEN
            RAISE EXCEPTION 'DTS durable state cannot be physically deleted'
              USING ERRCODE='42501';
          END IF;
          IF TG_OP='INSERT' THEN RETURN NEW; END IF;
          IF NEW.key_type IS DISTINCT FROM OLD.key_type
             OR NEW.key_part_1 IS DISTINCT FROM OLD.key_part_1
             OR NEW.key_part_2 IS DISTINCT FROM OLD.key_part_2
             OR NEW.row_version<>OLD.row_version+1 THEN
            RAISE EXCEPTION 'DTS dirty-key identity or version is invalid'
              USING ERRCODE='23514';
          END IF;
          RETURN NEW;
        END
        $$;
        REVOKE ALL ON FUNCTION
          public.guard_dts_dirty_key_state_write_v96()
        FROM PUBLIC;
        CREATE TRIGGER guard_dts_runtime_state_write
        BEFORE INSERT OR UPDATE OR DELETE ON public.dts_dirty_keys
        FOR EACH ROW
        EXECUTE FUNCTION public.guard_dts_dirty_key_state_write_v96();

CREATE FUNCTION public.sync_v1_compat_dirty_input_v1()
        RETURNS trigger
        LANGUAGE plpgsql
        SECURITY DEFINER
        SET search_path=pg_catalog,public
        AS $$
        DECLARE pipeline_mode text;
        BEGIN
          IF NEW.key_type NOT IN ('COURSE','TEACHER','TEACHER_STUDENT','LABEL','COMPLAINT_CATEGORY') THEN
            RETURN NEW;
          END IF;
          SELECT mode INTO pipeline_mode FROM public.dts_pipeline_control
          WHERE control_id='PRIMARY';
          PERFORM set_config('tit.dts_v1_compat_state_write','on',true);
          UPDATE public.dts_dirty_keys AS dirty
          SET compat_required_work_revision=greatest(
                dirty.compat_required_work_revision,
                NEW.dirty_work_revision
              ),
              compat_status=CASE
                WHEN pipeline_mode='V2_PRIMARY' THEN 'STANDBY'
                WHEN pipeline_mode IN (
                     'V1_COMPAT_DUAL_CAPTURE','ROLLED_BACK'
                   ) AND dirty.compat_status='PROCESSING'
                  THEN 'PROCESSING'
                WHEN pipeline_mode IN (
                     'V1_COMPAT_DUAL_CAPTURE','ROLLED_BACK'
                   ) THEN 'PENDING'
                ELSE 'STANDBY'
              END,
              compat_claimed_work_revision=CASE
                WHEN pipeline_mode IN (
                     'V1_COMPAT_DUAL_CAPTURE','ROLLED_BACK'
                   ) AND dirty.compat_status='PROCESSING'
                  THEN dirty.compat_claimed_work_revision ELSE NULL END,
              compat_attempt_count=CASE
                WHEN pipeline_mode IN (
                     'V1_COMPAT_DUAL_CAPTURE','ROLLED_BACK'
                   ) AND dirty.compat_status='PROCESSING'
                  THEN dirty.compat_attempt_count ELSE 0 END,
              compat_last_error_code=NULL,
              compat_next_attempt_at=CASE
                WHEN pipeline_mode IN (
                     'V1_COMPAT_DUAL_CAPTURE','ROLLED_BACK'
                   ) AND dirty.compat_status='PROCESSING' THEN NULL
                WHEN pipeline_mode IN (
                     'V1_COMPAT_DUAL_CAPTURE','ROLLED_BACK'
                   ) THEN transaction_timestamp()
                ELSE NULL END,
              compat_claimed_at=CASE
                WHEN pipeline_mode IN (
                     'V1_COMPAT_DUAL_CAPTURE','ROLLED_BACK'
                   ) AND dirty.compat_status='PROCESSING'
                  THEN dirty.compat_claimed_at ELSE NULL END,
              compat_claimed_by=CASE
                WHEN pipeline_mode IN (
                     'V1_COMPAT_DUAL_CAPTURE','ROLLED_BACK'
                   ) AND dirty.compat_status='PROCESSING'
                  THEN dirty.compat_claimed_by ELSE NULL END,
              compat_row_version=dirty.compat_row_version+1
          WHERE dirty.source_region=NEW.source_region
            AND dirty.key_type=NEW.key_type
            AND dirty.key_part_1=NEW.key_part_1
            AND dirty.key_part_2=NEW.key_part_2;
          IF NOT FOUND THEN
            RAISE EXCEPTION 'DTS_V1_COMPAT_DIRTY_KEY_MISSING'
              USING ERRCODE='23503';
          END IF;
          PERFORM set_config('tit.dts_v1_compat_state_write','off',true);
          RETURN NEW;
        END
        $$;

        CREATE TRIGGER trg_sync_v1_compat_dirty_input_v1
        AFTER INSERT ON public.dts_dirty_key_inputs
        FOR EACH ROW EXECUTE FUNCTION public.sync_v1_compat_dirty_input_v1();

        CREATE FUNCTION public.sync_v1_compat_pipeline_mode_v1()
        RETURNS trigger
        LANGUAGE plpgsql
        SECURITY DEFINER
        SET search_path=pg_catalog,public
        AS $$
        BEGIN
          IF TG_OP='UPDATE' AND NEW.mode IS NOT DISTINCT FROM OLD.mode THEN
            RETURN NEW;
          END IF;
          UPDATE public.dts_dirty_keys AS dirty
          SET compat_status=CASE
                WHEN NEW.mode='V2_PRIMARY' THEN 'STANDBY'
                WHEN dirty.compat_completed_work_revision>=
                     dirty.compat_required_work_revision THEN 'COMPLETED'
                ELSE 'PENDING' END,
              compat_claimed_work_revision=NULL,
              compat_attempt_count=0,compat_last_error_code=NULL,
              compat_next_attempt_at=CASE
                WHEN NEW.mode<>'V2_PRIMARY'
                 AND dirty.compat_completed_work_revision<
                     dirty.compat_required_work_revision
                  THEN transaction_timestamp() ELSE NULL END,
              compat_claimed_at=NULL,compat_claimed_by=NULL,
              compat_row_version=dirty.compat_row_version+1
          WHERE dirty.key_type IN ('COURSE','TEACHER','TEACHER_STUDENT','LABEL','COMPLAINT_CATEGORY');
          RETURN NEW;
        END
        $$;

        CREATE TRIGGER trg_sync_v1_compat_pipeline_mode_v1
        AFTER INSERT OR UPDATE OF mode ON public.dts_pipeline_control
        FOR EACH ROW EXECUTE FUNCTION public.sync_v1_compat_pipeline_mode_v1();

        CREATE FUNCTION public.claim_v1_compat_dirty_key_v1(
          p_worker_id text
        ) RETURNS TABLE(
          source_region text,key_type text,key_part_1 text,key_part_2 text,
          compat_claimed_work_revision bigint,compat_row_version bigint
        )
        LANGUAGE plpgsql
        VOLATILE
        SECURITY DEFINER
        SET search_path=pg_catalog,public
        AS $$
        DECLARE candidate record;
        DECLARE pipeline_mode text;
        BEGIN
          IF nullif(btrim(p_worker_id),'') IS NULL
             OR length(p_worker_id)>128 THEN
            RAISE EXCEPTION 'DTS_V1_COMPAT_WORKER_ID_INVALID'
              USING ERRCODE='22023';
          END IF;
          SELECT mode INTO pipeline_mode FROM public.dts_pipeline_control
          WHERE control_id='PRIMARY' FOR SHARE;
          IF pipeline_mode NOT IN (
               'V1_COMPAT_DUAL_CAPTURE','ROLLED_BACK'
             ) THEN
            RETURN;
          END IF;
          SELECT dirty.source_region,dirty.key_type,dirty.key_part_1,
                 dirty.key_part_2
          INTO candidate
          FROM public.dts_dirty_keys AS dirty
          WHERE dirty.key_type IN ('COURSE','TEACHER','TEACHER_STUDENT','LABEL','COMPLAINT_CATEGORY')
            AND dirty.compat_status IN ('PENDING','RETRY')
            AND dirty.compat_next_attempt_at<=transaction_timestamp()
          ORDER BY dirty.compat_next_attempt_at,dirty.updated_at,
                   convert_to(dirty.source_region,'UTF8'),
                   convert_to(dirty.key_type,'UTF8'),
                   convert_to(dirty.key_part_1,'UTF8'),
                   convert_to(dirty.key_part_2,'UTF8')
          FOR UPDATE SKIP LOCKED LIMIT 1;
          IF NOT FOUND THEN RETURN; END IF;
          PERFORM set_config('tit.dts_v1_compat_state_write','on',true);
          RETURN QUERY
          UPDATE public.dts_dirty_keys AS dirty
          SET compat_status='PROCESSING',
              compat_claimed_work_revision=
                dirty.compat_required_work_revision,
              compat_next_attempt_at=NULL,compat_last_error_code=NULL,
              compat_claimed_at=transaction_timestamp(),
              compat_claimed_by=p_worker_id,
              compat_row_version=dirty.compat_row_version+1
          WHERE dirty.source_region=candidate.source_region
            AND dirty.key_type=candidate.key_type
            AND dirty.key_part_1=candidate.key_part_1
            AND dirty.key_part_2=candidate.key_part_2
          RETURNING dirty.source_region::text,dirty.key_type::text,
            dirty.key_part_1::text,dirty.key_part_2::text,
            dirty.compat_claimed_work_revision,dirty.compat_row_version;
          PERFORM set_config('tit.dts_v1_compat_state_write','off',true);
        END
        $$;

        CREATE FUNCTION public.complete_v1_compat_dirty_key_v1(
          p_worker_id text,p_source_region text,p_key_type text,
          p_key_part_1 text,p_key_part_2 text,
          p_claimed_work_revision bigint,p_expected_row_version bigint
        ) RETURNS jsonb
        LANGUAGE plpgsql
        VOLATILE
        SECURITY DEFINER
        SET search_path=pg_catalog,public
        AS $$
        DECLARE dirty public.dts_dirty_keys%ROWTYPE;
        BEGIN
          IF nullif(btrim(p_worker_id),'') IS NULL
             OR p_source_region IS NULL OR p_key_type IS NULL
             OR p_key_part_1 IS NULL OR p_key_part_2 IS NULL
             OR p_claimed_work_revision IS NULL
             OR p_claimed_work_revision<1
             OR p_expected_row_version IS NULL
             OR p_expected_row_version<1 THEN
            RAISE EXCEPTION 'DTS_V1_COMPAT_COMPLETION_REQUEST_INVALID'
              USING ERRCODE='22023';
          END IF;
          SELECT * INTO dirty FROM public.dts_dirty_keys
          WHERE source_region=p_source_region AND key_type=p_key_type
            AND key_part_1=p_key_part_1 AND key_part_2=p_key_part_2
          FOR UPDATE;
          IF NOT FOUND OR dirty.compat_status<>'PROCESSING'
             OR dirty.compat_claimed_by IS DISTINCT FROM p_worker_id
             OR dirty.compat_claimed_work_revision IS DISTINCT FROM
                  p_claimed_work_revision
             OR dirty.compat_row_version<p_expected_row_version THEN
            RAISE EXCEPTION 'DTS_V1_COMPAT_CLAIM_LOST'
              USING ERRCODE='40001';
          END IF;
          PERFORM set_config('tit.dts_v1_compat_state_write','on',true);
          UPDATE public.dts_dirty_keys AS target
          SET compat_status=CASE WHEN target.compat_required_work_revision>
                    p_claimed_work_revision THEN 'PENDING' ELSE 'COMPLETED' END,
              compat_completed_work_revision=greatest(
                target.compat_completed_work_revision,
                p_claimed_work_revision
              ),
              compat_claimed_work_revision=NULL,
              compat_attempt_count=0,compat_last_error_code=NULL,
              compat_next_attempt_at=CASE WHEN
                target.compat_required_work_revision>p_claimed_work_revision
                THEN transaction_timestamp() ELSE NULL END,
              compat_claimed_at=NULL,compat_claimed_by=NULL,
              compat_row_version=target.compat_row_version+1
          WHERE target.source_region=p_source_region
            AND target.key_type=p_key_type
            AND target.key_part_1=p_key_part_1
            AND target.key_part_2=p_key_part_2
          RETURNING * INTO dirty;
          PERFORM set_config('tit.dts_v1_compat_state_write','off',true);
          RETURN jsonb_build_object(
            'status',dirty.compat_status,
            'completed_work_revision',
              dirty.compat_completed_work_revision,
            'row_version',dirty.compat_row_version
          );
        END
        $$;

        CREATE FUNCTION public.fail_v1_compat_dirty_key_v1(
          p_worker_id text,p_source_region text,p_key_type text,
          p_key_part_1 text,p_key_part_2 text,p_error_code text,
          p_max_attempts integer,p_retry_base_seconds integer,
          p_retry_max_seconds integer
        ) RETURNS jsonb
        LANGUAGE plpgsql
        VOLATILE
        SECURITY DEFINER
        SET search_path=pg_catalog,public
        AS $$
        DECLARE dirty public.dts_dirty_keys%ROWTYPE;
        DECLARE next_attempt integer;
        DECLARE retry_seconds integer;
        DECLARE pipeline_mode text;
        BEGIN
          IF nullif(btrim(p_worker_id),'') IS NULL
             OR nullif(btrim(p_error_code),'') IS NULL
             OR length(p_error_code)>128
             OR p_source_region IS NULL OR p_key_type IS NULL
             OR p_key_part_1 IS NULL OR p_key_part_2 IS NULL
             OR p_max_attempts IS NULL
             OR p_retry_base_seconds IS NULL
             OR p_retry_max_seconds IS NULL
             OR p_max_attempts NOT BETWEEN 1 AND 100
             OR p_retry_base_seconds NOT BETWEEN 1 AND 3600
             OR p_retry_max_seconds NOT BETWEEN p_retry_base_seconds AND 86400
          THEN
            RAISE EXCEPTION 'DTS_V1_COMPAT_FAILURE_REQUEST_INVALID'
              USING ERRCODE='22023';
          END IF;
          SELECT mode INTO pipeline_mode FROM public.dts_pipeline_control
          WHERE control_id='PRIMARY' FOR SHARE;
          IF pipeline_mode NOT IN (
               'V1_COMPAT_DUAL_CAPTURE','ROLLED_BACK'
             ) THEN
            RAISE EXCEPTION 'DTS_V1_COMPAT_MODE_INACTIVE'
              USING ERRCODE='55000';
          END IF;
          SELECT * INTO dirty FROM public.dts_dirty_keys
          WHERE source_region=p_source_region AND key_type=p_key_type
            AND key_part_1=p_key_part_1 AND key_part_2=p_key_part_2
          FOR UPDATE;
          IF NOT FOUND OR dirty.compat_status NOT IN ('PENDING','RETRY') THEN
            RAISE EXCEPTION 'DTS_V1_COMPAT_FAILURE_STATE_CONFLICT'
              USING ERRCODE='40001';
          END IF;
          next_attempt:=dirty.compat_attempt_count+1;
          retry_seconds:=least(
            p_retry_max_seconds,
            p_retry_base_seconds*(1<<least(next_attempt-1,8))
          );
          PERFORM set_config('tit.dts_v1_compat_state_write','on',true);
          UPDATE public.dts_dirty_keys AS target
          SET compat_status=CASE WHEN next_attempt>=p_max_attempts
                THEN 'DEAD' ELSE 'RETRY' END,
              compat_attempt_count=next_attempt,
              compat_last_error_code=p_error_code,
              compat_next_attempt_at=CASE WHEN next_attempt>=p_max_attempts
                THEN NULL ELSE transaction_timestamp()+
                  make_interval(secs=>retry_seconds) END,
              compat_claimed_work_revision=NULL,
              compat_claimed_at=NULL,compat_claimed_by=NULL,
              compat_row_version=target.compat_row_version+1
          WHERE target.source_region=p_source_region
            AND target.key_type=p_key_type
            AND target.key_part_1=p_key_part_1
            AND target.key_part_2=p_key_part_2
          RETURNING * INTO dirty;
          PERFORM set_config('tit.dts_v1_compat_state_write','off',true);
          RETURN jsonb_build_object(
            'status',dirty.compat_status,
            'attempt_count',dirty.compat_attempt_count,
            'row_version',dirty.compat_row_version
          );
        END
        $$;

        CREATE FUNCTION public.guard_v1_compat_processing_commit_v1()
        RETURNS trigger
        LANGUAGE plpgsql
        SECURITY DEFINER
        SET search_path=pg_catalog,public
        AS $$
        BEGIN
          IF NEW.compat_status='PROCESSING' AND EXISTS (
            SELECT 1 FROM public.dts_dirty_keys AS current_state
            WHERE current_state.source_region=NEW.source_region
              AND current_state.key_type=NEW.key_type
              AND current_state.key_part_1=NEW.key_part_1
              AND current_state.key_part_2=NEW.key_part_2
              AND current_state.compat_status='PROCESSING'
          ) THEN
            RAISE EXCEPTION 'DTS_V1_COMPAT_CLAIM_MUST_COMPLETE_IN_TRANSACTION'
              USING ERRCODE='40001';
          END IF;
          RETURN NULL;
        END
        $$;

        CREATE CONSTRAINT TRIGGER trg_v1_compat_processing_commit_v1
        AFTER INSERT OR UPDATE ON public.dts_dirty_keys
        DEFERRABLE INITIALLY DEFERRED
        FOR EACH ROW
        EXECUTE FUNCTION public.guard_v1_compat_processing_commit_v1();

        CREATE FUNCTION public.recover_v1_compat_dirty_key_v1(
          p_operator_request_id text,p_source_region text,p_key_type text,
          p_key_part_1 text,p_key_part_2 text,
          p_expected_compat_row_version bigint,p_reason text
        ) RETURNS jsonb
        LANGUAGE plpgsql
        VOLATILE
        SECURITY DEFINER
        SET search_path=pg_catalog,public
        AS $$
        DECLARE actor_name text:=coalesce(
          nullif(current_setting('role',true),'none'),session_user
        );
        DECLARE dirty public.dts_dirty_keys%ROWTYPE;
        DECLARE existing_audit public.dts_dirty_key_state_audits%ROWTYPE;
        DECLARE reason_hash text;
        BEGIN
          IF actor_name<>'tit_growth_app'
             OR nullif(btrim(p_operator_request_id),'') IS NULL
             OR length(p_operator_request_id)>128
             OR p_source_region IS NULL OR p_key_type IS NULL
             OR p_key_part_1 IS NULL OR p_key_part_2 IS NULL
             OR p_expected_compat_row_version IS NULL
             OR p_expected_compat_row_version<1
             OR nullif(btrim(p_reason),'') IS NULL
             OR p_reason<>btrim(p_reason) OR length(p_reason)>512 THEN
            RAISE EXCEPTION 'DTS_V1_COMPAT_RECOVERY_REQUEST_INVALID'
              USING ERRCODE='22023';
          END IF;
          PERFORM pg_advisory_xact_lock(hashtextextended(
            'tit:dts-v1-compat-recovery:'||p_operator_request_id,0
          ));
          reason_hash:=encode(sha256(convert_to(p_reason,'UTF8')),'hex');
          SELECT * INTO existing_audit
          FROM public.dts_dirty_key_state_audits
          WHERE event_type='OPERATOR_RECOVERY'
            AND detail->>'state_channel'='V1_COMPAT'
            AND detail->>'operator_request_id'=p_operator_request_id
          ORDER BY audit_id LIMIT 1;
          IF FOUND THEN
            IF existing_audit.source_region IS DISTINCT FROM p_source_region
               OR existing_audit.key_type IS DISTINCT FROM p_key_type
               OR existing_audit.key_part_1 IS DISTINCT FROM p_key_part_1
               OR existing_audit.key_part_2 IS DISTINCT FROM p_key_part_2
               OR existing_audit.detail->>'reason_hash' IS DISTINCT FROM
                    reason_hash THEN
              RAISE EXCEPTION 'DTS_V1_COMPAT_RECOVERY_COMMAND_CONFLICT'
                USING ERRCODE='23505';
            END IF;
            RETURN jsonb_build_object(
              'status','REPLAYED','operator_request_id',p_operator_request_id,
              'compat_row_version',
                (existing_audit.detail->>'compat_after_row_version')::bigint
            );
          END IF;
          SELECT * INTO dirty FROM public.dts_dirty_keys
          WHERE source_region=p_source_region AND key_type=p_key_type
            AND key_part_1=p_key_part_1 AND key_part_2=p_key_part_2
          FOR UPDATE;
          IF NOT FOUND OR dirty.compat_status<>'DEAD'
             OR dirty.compat_row_version IS DISTINCT FROM
                  p_expected_compat_row_version THEN
            RAISE EXCEPTION 'DTS_V1_COMPAT_RECOVERY_STATE_CONFLICT'
              USING ERRCODE='40001';
          END IF;
          PERFORM set_config('tit.dts_v1_compat_state_write','on',true);
          UPDATE public.dts_dirty_keys AS target
          SET compat_status='PENDING',compat_attempt_count=0,
              compat_last_error_code=NULL,
              compat_next_attempt_at=transaction_timestamp(),
              compat_claimed_work_revision=NULL,
              compat_claimed_at=NULL,compat_claimed_by=NULL,
              compat_row_version=target.compat_row_version+1
          WHERE target.source_region=p_source_region
            AND target.key_type=p_key_type
            AND target.key_part_1=p_key_part_1
            AND target.key_part_2=p_key_part_2
          RETURNING * INTO dirty;
          PERFORM set_config('tit.dts_v1_compat_state_write','off',true);
          INSERT INTO public.dts_dirty_key_state_audits(
            source_region,key_type,key_part_1,key_part_2,event_type,
            work_generation,dead_generation,detail
          ) VALUES (
            p_source_region,p_key_type,p_key_part_1,p_key_part_2,
            'OPERATOR_RECOVERY',dirty.work_generation,
            dirty.dead_generation,jsonb_build_object(
              'state_channel','V1_COMPAT',
              'operator_request_id',p_operator_request_id,
              'reason_hash',reason_hash,
              'compat_before_row_version',p_expected_compat_row_version,
              'compat_after_row_version',dirty.compat_row_version
            )
          );
          RETURN jsonb_build_object(
            'status','APPLIED','operator_request_id',p_operator_request_id,
            'compat_status',dirty.compat_status,
            'compat_row_version',dirty.compat_row_version
          );
        END
        $$;

        CREATE FUNCTION public.dts_v1_compat_dirty_not_complete_count_v1()
        RETURNS bigint
        LANGUAGE sql
        STABLE
        SECURITY DEFINER
        SET search_path=pg_catalog,public
        AS $$
          SELECT CASE WHEN coalesce(
            (SELECT mode FROM public.dts_pipeline_control
             WHERE control_id='PRIMARY'),'V2_PRIMARY'
          ) NOT IN ('V1_COMPAT_DUAL_CAPTURE','ROLLED_BACK') THEN 0::bigint
          ELSE count(*)::bigint END
          FROM public.dts_dirty_keys
          WHERE key_type IN ('COURSE','TEACHER','TEACHER_STUDENT','LABEL','COMPLAINT_CATEGORY')
            AND (compat_status<>'COMPLETED' OR
                 compat_completed_work_revision<
                   compat_required_work_revision)
        $$;

        REVOKE ALL ON FUNCTION
          public.sync_v1_compat_dirty_input_v1(),
          public.sync_v1_compat_pipeline_mode_v1(),
          public.claim_v1_compat_dirty_key_v1(text),
          public.complete_v1_compat_dirty_key_v1(
            text,text,text,text,text,bigint,bigint
          ),
          public.fail_v1_compat_dirty_key_v1(
            text,text,text,text,text,text,integer,integer,integer
          ),
          public.guard_v1_compat_processing_commit_v1(),
          public.recover_v1_compat_dirty_key_v1(
            text,text,text,text,text,bigint,text
          ),
          public.dts_v1_compat_dirty_not_complete_count_v1()
        FROM PUBLIC;
        GRANT EXECUTE ON FUNCTION
          public.claim_v1_compat_dirty_key_v1(text),
          public.complete_v1_compat_dirty_key_v1(
            text,text,text,text,text,bigint,bigint
          ),
          public.fail_v1_compat_dirty_key_v1(
            text,text,text,text,text,text,integer,integer,integer
          ),
          public.dts_v1_compat_dirty_not_complete_count_v1()
        TO tit_dts_ingest_runtime;
        GRANT EXECUTE ON FUNCTION
          public.recover_v1_compat_dirty_key_v1(
            text,text,text,text,text,bigint,text
          ),
          public.dts_v1_compat_dirty_not_complete_count_v1()
        TO tit_growth_app;

CREATE FUNCTION public.guard_qualification_gate_rollback_v2()
        RETURNS trigger
        LANGUAGE plpgsql
        SET search_path=pg_catalog,public
        AS $$
        BEGIN
          IF OLD.mode='V2_PRIMARY' AND NEW.mode='ROLLED_BACK'
             AND OLD.qualification_grants_enabled IS TRUE THEN
            RAISE EXCEPTION
              'DTS_QUALIFICATION_GATE_DISABLE_REQUIRED_BEFORE_ROLLBACK'
              USING ERRCODE='55000';
          END IF;
          RETURN NEW;
        END
        $$;
        REVOKE ALL ON FUNCTION
          public.guard_qualification_gate_rollback_v2()
        FROM PUBLIC;
        CREATE TRIGGER aa_guard_qualification_gate_rollback_v2
        BEFORE UPDATE OF mode ON public.dts_pipeline_control
        FOR EACH ROW
        EXECUTE FUNCTION public.guard_qualification_gate_rollback_v2();

        CREATE FUNCTION public.enforce_irreversible_qualification_gate_v2()
        RETURNS trigger
        LANGUAGE plpgsql
        SECURITY DEFINER
        SET search_path=pg_catalog,public
        AS $$
        DECLARE grants_enabled boolean:=false;
        DECLARE pipeline_mode text;
        DECLARE old_graduated boolean:=false;
        DECLARE old_gold boolean:=false;
        DECLARE actor_name text:=coalesce(
          nullif(current_setting('role',true),'none'),session_user
        );
        BEGIN
          SELECT qualification_grants_enabled,mode
          INTO grants_enabled,pipeline_mode
          FROM public.dts_pipeline_control WHERE control_id='PRIMARY'
          FOR SHARE;
          grants_enabled:=coalesce(grants_enabled,false)
            AND pipeline_mode='V2_PRIMARY';
          IF TG_OP='UPDATE' THEN
            old_graduated:=OLD.graduation_qualified;
            old_gold:=OLD.gold_qualified;
          END IF;
          IF NOT grants_enabled THEN
            NEW.graduation_qualified:=old_graduated;
            NEW.gold_qualified:=old_gold;
            IF NOT old_graduated THEN
              NEW.graduation_qualified_at:=NULL;
              NEW.graduation_score_locked:=NULL;
            END IF;
            IF NOT old_gold THEN NEW.gold_qualified_at:=NULL; END IF;
          ELSIF actor_name<>'tit_growth_app' AND (
            (NEW.graduation_qualified AND NOT old_graduated)
            OR (NEW.gold_qualified AND NOT old_gold)
          ) THEN
            RAISE EXCEPTION 'DTS_QUALIFICATION_GRANT_ROLE_REQUIRED'
              USING ERRCODE='42501';
          END IF;
          NEW.gate_results:=coalesce(NEW.gate_results,'{}'::jsonb) ||
            jsonb_build_object(
              'qualification_grants_enabled',grants_enabled,
              'irreversible_qualification_grants_enabled',grants_enabled
            );
          RETURN NEW;
        END
        $$;

        CREATE TRIGGER aa_enforce_irreversible_qualification_gate_v2
        BEFORE INSERT OR UPDATE ON public.teacher_qualifications
        FOR EACH ROW
        EXECUTE FUNCTION public.enforce_irreversible_qualification_gate_v2();

        CREATE FUNCTION public.enforce_teacher_qualification_gate_v2()
        RETURNS trigger
        LANGUAGE plpgsql
        SECURITY DEFINER
        SET search_path=pg_catalog,public
        AS $$
        DECLARE grants_enabled boolean:=false;
        DECLARE pipeline_mode text;
        DECLARE old_graduated boolean:=false;
        DECLARE old_gold boolean:=false;
        DECLARE actor_name text:=coalesce(
          nullif(current_setting('role',true),'none'),session_user
        );
        BEGIN
          SELECT qualification_grants_enabled,mode
          INTO grants_enabled,pipeline_mode
          FROM public.dts_pipeline_control WHERE control_id='PRIMARY'
          FOR SHARE;
          grants_enabled:=coalesce(grants_enabled,false)
            AND pipeline_mode='V2_PRIMARY';
          IF TG_OP='UPDATE' THEN
            old_graduated:=OLD.graduation_state='GRADUATED';
            old_gold:=OLD.gold_qualified;
          END IF;
          IF NOT grants_enabled THEN
            NEW.graduation_state:=CASE WHEN old_graduated
              THEN 'GRADUATED' ELSE 'IN_CAMP' END;
            NEW.gold_qualified:=old_gold;
          ELSIF actor_name<>'tit_growth_app' AND (
            (NEW.graduation_state='GRADUATED' AND NOT old_graduated)
            OR (NEW.gold_qualified AND NOT old_gold)
          ) THEN
            RAISE EXCEPTION 'DTS_TEACHER_QUALIFICATION_GRANT_ROLE_REQUIRED'
              USING ERRCODE='42501';
          END IF;
          NEW.payload:=jsonb_set(
            coalesce(NEW.payload,'{}'::jsonb),
            '{graduation_state}',to_jsonb(NEW.graduation_state),true
          );
          RETURN NEW;
        END
        $$;

        CREATE TRIGGER aa_enforce_teacher_qualification_gate_v2
        BEFORE INSERT OR UPDATE OF graduation_state,gold_qualified,payload
        ON public.teachers
        FOR EACH ROW
        EXECUTE FUNCTION public.enforce_teacher_qualification_gate_v2();

        CREATE FUNCTION public.guard_dts_qualification_gate_command_v2()
        RETURNS trigger
        LANGUAGE plpgsql
        SET search_path=pg_catalog,public
        AS $$
        BEGIN
          IF TG_OP<>'INSERT' OR current_setting(
               'tit.dts_qualification_gate_command_v1',true
             )<>'on' THEN
            RAISE EXCEPTION 'DTS_QUALIFICATION_GATE_AUDIT_IMMUTABLE'
              USING ERRCODE='42501';
          END IF;
          RETURN NEW;
        END
        $$;
        CREATE TRIGGER trg_guard_dts_qualification_gate_command_v2
        BEFORE INSERT OR UPDATE OR DELETE
        ON public.dts_qualification_gate_commands
        FOR EACH ROW
        EXECUTE FUNCTION public.guard_dts_qualification_gate_command_v2();

        CREATE FUNCTION public.set_irreversible_qualification_grants_v2(
          p_command_id text,p_enabled boolean,
          p_expected_control_row_version bigint,p_reason text
        ) RETURNS jsonb
        LANGUAGE plpgsql
        VOLATILE
        SECURITY DEFINER
        SET search_path=pg_catalog,public
        AS $$
        DECLARE actor_name text:=coalesce(
          nullif(current_setting('role',true),'none'),session_user
        );
        DECLARE existing public.dts_qualification_gate_commands%ROWTYPE;
        DECLARE control_row public.dts_pipeline_control%ROWTYPE;
        DECLARE command_document jsonb;
        DECLARE command_sha256 text;
        DECLARE resulting_version bigint;
        DECLARE fanout_count bigint:=0;
        DECLARE teacher_key record;
        DECLARE input_identity jsonb;
        DECLARE input_fingerprint text;
        BEGIN
          IF actor_name<>'tit_growth_app'
             OR nullif(btrim(p_command_id),'') IS NULL
             OR length(p_command_id)>128
             OR p_enabled IS NULL
             OR p_expected_control_row_version IS NULL
             OR p_expected_control_row_version<1
             OR nullif(btrim(p_reason),'') IS NULL
             OR p_reason<>btrim(p_reason) OR length(p_reason)>512 THEN
            RAISE EXCEPTION 'DTS_QUALIFICATION_GATE_COMMAND_INVALID'
              USING ERRCODE='22023';
          END IF;
          command_document:=jsonb_build_object(
            'protocol_version','dts-qualification-gate-command-v1',
            'command_id',p_command_id,'enabled',p_enabled,
            'expected_control_row_version',p_expected_control_row_version,
            'reason',p_reason
          );
          command_sha256:=
            public.dts_canonical_json_sha256_v1(command_document);
          PERFORM pg_advisory_xact_lock(
            hashtextextended('tit:dts-qualification-gate',0)
          );
          SELECT * INTO existing
          FROM public.dts_qualification_gate_commands
          WHERE command_id=p_command_id;
          IF FOUND THEN
            IF existing.requested_enabled IS DISTINCT FROM p_enabled
               OR existing.expected_control_row_version IS DISTINCT FROM
                    p_expected_control_row_version
               OR existing.reason IS DISTINCT FROM p_reason
               OR existing.command_sha256 IS DISTINCT FROM command_sha256 THEN
              RAISE EXCEPTION 'DTS_QUALIFICATION_GATE_COMMAND_CONFLICT'
                USING ERRCODE='23505';
            END IF;
            SELECT * INTO STRICT control_row
            FROM public.dts_pipeline_control WHERE control_id='PRIMARY'
            FOR SHARE;
            IF control_row.mode<>'V2_PRIMARY'
               OR control_row.qualification_grants_enabled IS DISTINCT FROM
                    existing.requested_enabled
               OR control_row.row_version IS DISTINCT FROM
                    existing.resulting_control_row_version THEN
              RAISE EXCEPTION 'DTS_QUALIFICATION_GATE_COMMAND_CONFLICT'
                USING ERRCODE='40001';
            END IF;
            RETURN jsonb_build_object(
              'status','REPLAYED','command_id',existing.command_id,
              'enabled',existing.requested_enabled,
              'control_row_version',
                existing.resulting_control_row_version,
              'fanout_count',existing.fanout_count,
              'command_sha256',existing.command_sha256
            );
          END IF;
          SELECT * INTO STRICT control_row
          FROM public.dts_pipeline_control WHERE control_id='PRIMARY'
          FOR UPDATE;
          IF control_row.mode<>'V2_PRIMARY'
             OR control_row.row_version<>p_expected_control_row_version THEN
            RAISE EXCEPTION 'DTS_QUALIFICATION_GATE_CONTROL_CONFLICT'
              USING ERRCODE='40001';
          END IF;
          resulting_version:=control_row.row_version;
          IF control_row.qualification_grants_enabled IS DISTINCT FROM
               p_enabled THEN
            UPDATE public.dts_pipeline_control
            SET qualification_grants_enabled=p_enabled,
                row_version=row_version+1,
                changed_at=transaction_timestamp(),changed_by=actor_name
            WHERE control_id='PRIMARY'
              AND row_version=p_expected_control_row_version
            RETURNING row_version INTO resulting_version;
            IF NOT FOUND THEN
              RAISE EXCEPTION 'DTS_QUALIFICATION_GATE_CONTROL_CONFLICT'
                USING ERRCODE='40001';
            END IF;
            input_identity:=jsonb_build_object(
              'protocol_version','dts-qualification-gate-fanout-v1',
              'command_id',p_command_id,'enabled',p_enabled,
              'control_row_version',resulting_version
            );
            FOR teacher_key IN
              SELECT source_region,key_part_1
              FROM public.dts_dirty_keys
              WHERE key_type='TEACHER' AND key_part_2=''
              ORDER BY convert_to(source_region,'UTF8'),
                       convert_to(key_part_1,'UTF8')
            LOOP
              input_fingerprint:=public.dts_canonical_json_sha256_v1(
                input_identity || jsonb_build_object(
                  'source_region',teacher_key.source_region,
                  'teacher_id',teacher_key.key_part_1
                )
              );
              PERFORM public._upsert_dts_dirty_key_input_v2(
                teacher_key.source_region,'TEACHER',
                teacher_key.key_part_1,'','OPERATOR_RECOVERY',
                input_identity,resulting_version,input_fingerprint
              );
              fanout_count:=fanout_count+1;
            END LOOP;
          END IF;
          PERFORM set_config(
            'tit.dts_qualification_gate_command_v1','on',true
          );
          INSERT INTO public.dts_qualification_gate_commands(
            command_id,requested_enabled,expected_control_row_version,
            resulting_control_row_version,reason,command_sha256,
            fanout_count,result_status,executed_by
          ) VALUES (
            p_command_id,p_enabled,p_expected_control_row_version,
            resulting_version,p_reason,command_sha256,fanout_count,
            'APPLIED',actor_name
          );
          PERFORM set_config(
            'tit.dts_qualification_gate_command_v1','off',true
          );
          RETURN jsonb_build_object(
            'status','APPLIED','command_id',p_command_id,
            'enabled',p_enabled,'control_row_version',resulting_version,
            'fanout_count',fanout_count,
            'command_sha256',command_sha256
          );
        EXCEPTION WHEN no_data_found OR too_many_rows THEN
          RAISE EXCEPTION 'DTS_QUALIFICATION_GATE_CONTROL_CONFLICT'
            USING ERRCODE='40001';
        END
        $$;

        REVOKE ALL ON TABLE public.dts_qualification_gate_commands
          FROM PUBLIC,tit_dts_ingest_runtime;
        REVOKE ALL ON FUNCTION
          public.enforce_irreversible_qualification_gate_v2(),
          public.enforce_teacher_qualification_gate_v2(),
          public.guard_dts_qualification_gate_command_v2(),
          public.set_irreversible_qualification_grants_v2(
            text,boolean,bigint,text
          )
        FROM PUBLIC;
        GRANT SELECT ON TABLE public.dts_qualification_gate_commands
          TO tit_growth_app;
        GRANT EXECUTE ON FUNCTION
          public.set_irreversible_qualification_grants_v2(
            text,boolean,bigint,text
          )
        TO tit_growth_app;

UPDATE alembic_version SET version_num='20260822_96_compat_queue_gate' WHERE alembic_version.version_num = '20260822_95_projection_cutover';

-- Running upgrade 20260822_96_compat_queue_gate -> 20260822_97_teacher_time_recheck

DO $$
        DECLARE required_relation text;
        DECLARE required_function text;
        BEGIN
          FOREACH required_relation IN ARRAY ARRAY[
            'dts_dirty_keys','dts_dirty_key_inputs',
            'dts_dirty_key_dependencies','dts_pipeline_control',
            'teacher_source_wide','teachers','domain_aggregate_revisions'
          ] LOOP
            IF to_regclass('public.'||required_relation) IS NULL THEN
              RAISE EXCEPTION
                'DTS_V2_TIME_RECHECK_PREREQUISITE_MISSING:%',
                required_relation;
            END IF;
          END LOOP;
          FOREACH required_function IN ARRAY ARRAY[
            'public._upsert_dts_dirty_key_input_v2(text,text,text,text,text,jsonb,bigint,text)',
            'public._complete_dts_dirty_key_v2(text,text,text,text,text,text,bigint,bigint)',
            'public._fail_dts_dirty_key_v2(text,text,text,text,text,text,bigint,bigint,text)',
            'public.dts_v2_runtime_primary_guard_v1(text)',
            'public.dts_canonical_json_sha256_v1(jsonb)'
          ] LOOP
            IF to_regprocedure(required_function) IS NULL THEN
              RAISE EXCEPTION
                'DTS_V2_TIME_RECHECK_PREREQUISITE_MISSING:%',
                required_function;
            END IF;
          END LOOP;
          IF to_regrole('tit_growth_app') IS NULL THEN
            RAISE EXCEPTION
              'DTS_V2_TIME_RECHECK_PREREQUISITE_MISSING:OUTBOX_ROLE';
          END IF;
          IF to_regclass('public.dts_teacher_time_recheck_results')
               IS NOT NULL
             OR to_regprocedure(
               'public.materialize_teacher_time_recheck_v2(jsonb,bigint,bigint,bigint,text,bigint)'
             ) IS NOT NULL THEN
            RAISE EXCEPTION 'DTS_V2_TIME_RECHECK_ALREADY_INSTALLED';
          END IF;
        END
        $$;

        LOCK TABLE public.dts_dirty_keys,public.dts_dirty_key_inputs,
          public.dts_dirty_key_dependencies,public.teacher_source_wide,
          public.teachers,public.domain_aggregate_revisions
        IN SHARE ROW EXCLUSIVE MODE;

CREATE TABLE public.dts_teacher_time_recheck_schedule (
    schedule_id VARCHAR(16) NOT NULL,
    last_enqueued_business_date DATE,
    last_enqueued_generation BIGINT,
    last_enqueued_at TIMESTAMP WITH TIME ZONE,
    row_version BIGINT DEFAULT 1 NOT NULL,
    CONSTRAINT pk_dts_teacher_time_recheck_schedule PRIMARY KEY (schedule_id),
    CONSTRAINT ck_dts_teacher_time_recheck_schedule_shape CHECK (schedule_id='PRIMARY' AND row_version>=1 AND ((last_enqueued_business_date IS NULL AND last_enqueued_generation IS NULL AND last_enqueued_at IS NULL) OR (last_enqueued_business_date IS NOT NULL AND last_enqueued_generation>=1 AND last_enqueued_at IS NOT NULL)))
);

INSERT INTO public.dts_teacher_time_recheck_schedule(
          schedule_id,last_enqueued_business_date,last_enqueued_generation,
          last_enqueued_at,row_version
        ) VALUES ('PRIMARY',NULL,NULL,NULL,1);

CREATE TABLE public.dts_teacher_time_recheck_results (
    teacher_id VARCHAR(64) NOT NULL,
    business_date_beijing DATE NOT NULL,
    teacher_id_type VARCHAR(16) NOT NULL,
    dom_aggregate_revision BIGINT NOT NULL,
    ovs_aggregate_revision BIGINT NOT NULL,
    regional_state_sha256 JSONB NOT NULL,
    projection_generation BIGINT NOT NULL,
    triggering_event_id VARCHAR(512) NOT NULL,
    claimed_work_revision BIGINT NOT NULL,
    time_values JSONB NOT NULL,
    plan_sha256 VARCHAR(64) NOT NULL,
    materialized_at TIMESTAMP WITH TIME ZONE DEFAULT transaction_timestamp() NOT NULL,
    CONSTRAINT pk_dts_teacher_time_recheck_results PRIMARY KEY (teacher_id, business_date_beijing),
    CONSTRAINT fk_dts_teacher_time_recheck_result_teacher FOREIGN KEY(teacher_id) REFERENCES public.teacher_source_wide (tchr_id) ON DELETE RESTRICT DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT ck_dts_teacher_time_recheck_result_shape CHECK (teacher_id_type IN ('NUMERIC','TEXT') AND dom_aggregate_revision>=1 AND ovs_aggregate_revision>=1 AND projection_generation>=1 AND claimed_work_revision>=1 AND regional_state_sha256 ?& ARRAY['dom','ovs'] AND regional_state_sha256=jsonb_build_object('dom',regional_state_sha256->'dom','ovs',regional_state_sha256->'ovs') AND regional_state_sha256->>'dom' ~ '^[0-9a-f]{64}$' AND regional_state_sha256->>'ovs' ~ '^[0-9a-f]{64}$' AND jsonb_typeof(time_values)='object' AND time_values=jsonb_build_object('job_days',time_values->'job_days','job_month',time_values->'job_month','online_status',time_values->'online_status','online_status_evidence_status',time_values->'online_status_evidence_status') AND plan_sha256 ~ '^[0-9a-f]{64}$' AND btrim(triggering_event_id)<>'')
);

CREATE INDEX ix_dts_teacher_time_recheck_result_date ON public.dts_teacher_time_recheck_results (business_date_beijing, teacher_id);

CREATE TABLE public.dts_teacher_time_recheck_audits (
    audit_id BIGINT GENERATED BY DEFAULT AS IDENTITY,
    teacher_id VARCHAR(64) NOT NULL,
    business_date_beijing DATE NOT NULL,
    event_type VARCHAR(40) NOT NULL,
    detail JSONB NOT NULL,
    detail_sha256 VARCHAR(64) NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT transaction_timestamp() NOT NULL,
    CONSTRAINT pk_dts_teacher_time_recheck_audits PRIMARY KEY (audit_id),
    CONSTRAINT ck_dts_teacher_time_recheck_audit_shape CHECK (event_type='SUPERSEDED_BY_CURRENT_DATE' AND jsonb_typeof(detail)='object' AND detail_sha256 ~ '^[0-9a-f]{64}$')
);

CREATE FUNCTION public.guard_teacher_time_recheck_append_only_v1()
        RETURNS trigger
        LANGUAGE plpgsql
        SET search_path=pg_catalog,public
        AS $$
        BEGIN
          RAISE EXCEPTION 'DTS_V2_TIME_RECHECK_EVIDENCE_IMMUTABLE'
            USING ERRCODE='42501';
        END
        $$;
        REVOKE ALL ON FUNCTION
          public.guard_teacher_time_recheck_append_only_v1() FROM PUBLIC;

        CREATE TRIGGER trg_guard_teacher_time_recheck_result_append_only_v1
        BEFORE UPDATE OR DELETE
        ON public.dts_teacher_time_recheck_results
        FOR EACH ROW EXECUTE FUNCTION
          public.guard_teacher_time_recheck_append_only_v1();

        CREATE TRIGGER trg_guard_teacher_time_recheck_audit_append_only_v1
        BEFORE UPDATE OR DELETE
        ON public.dts_teacher_time_recheck_audits
        FOR EACH ROW EXECUTE FUNCTION
          public.guard_teacher_time_recheck_append_only_v1();

CREATE FUNCTION public._enqueue_teacher_time_recheck_key_v2(
          p_teacher_id text,p_business_date date
        ) RETURNS jsonb
        LANGUAGE plpgsql
        SECURITY DEFINER
        SET search_path=pg_catalog,public
        AS $$
        DECLARE identity jsonb;
        DECLARE fingerprint text;
        DECLARE input_revision bigint;
        BEGIN
          IF p_teacher_id IS NULL OR btrim(p_teacher_id)=''
             OR length(p_teacher_id)>64 OR p_business_date IS NULL
             OR NOT EXISTS (
               SELECT 1 FROM public.teacher_source_wide
               WHERE tchr_id=p_teacher_id AND v2_row_version IS NOT NULL
             ) THEN
            RAISE EXCEPTION 'DTS_V2_TIME_RECHECK_INPUT_INVALID'
              USING ERRCODE='22023';
          END IF;
          identity := jsonb_build_object(
            'business_date_beijing',p_business_date,
            'teacher_id',p_teacher_id
          );
          input_revision := to_char(p_business_date,'YYYYMMDD')::bigint;
          fingerprint := public.dts_canonical_json_sha256_v1(
            jsonb_build_object(
              'protocol','teacher-time-recheck-input-v1',
              'identity',identity,'input_revision',input_revision
            )
          );
          RETURN public._upsert_dts_dirty_key_input_v2(
            'dom','TEACHER_TIME_RECHECK',p_teacher_id,
            to_char(p_business_date,'YYYY-MM-DD'),'TIME_RECHECK',
            identity,input_revision,fingerprint
          );
        END
        $$;
        REVOKE ALL ON FUNCTION
          public._enqueue_teacher_time_recheck_key_v2(text,date)
        FROM PUBLIC;

        CREATE FUNCTION public.enqueue_due_teacher_time_rechecks_v2()
        RETURNS jsonb
        LANGUAGE plpgsql
        SECURITY DEFINER
        SET search_path=pg_catalog,public
        AS $$
        DECLARE generation bigint;
        DECLARE local_now timestamp;
        DECLARE business_date date;
        DECLARE schedule public.dts_teacher_time_recheck_schedule%ROWTYPE;
        DECLARE teacher record;
        DECLARE outcome jsonb;
        DECLARE enqueued integer := 0;
        DECLARE superseded integer := 0;
        DECLARE obsolete public.dts_dirty_keys%ROWTYPE;
        DECLARE audit_detail jsonb;
        BEGIN
          generation := public.dts_v2_runtime_primary_guard_v1('OUTBOX');
          IF generation IS NULL THEN
            RETURN jsonb_build_object(
              'enqueued',0,'superseded',0,'schedule_due',false
            );
          END IF;
          local_now := transaction_timestamp()
            AT TIME ZONE 'Asia/Shanghai';
          business_date := local_now::date;
          IF local_now::time < time '00:05:00' THEN
            RETURN jsonb_build_object(
              'enqueued',0,'superseded',0,'schedule_due',true
            );
          END IF;

          SELECT * INTO schedule
          FROM public.dts_teacher_time_recheck_schedule
          WHERE schedule_id='PRIMARY' FOR UPDATE;
          IF NOT FOUND THEN
            RAISE EXCEPTION 'DTS_V2_TIME_RECHECK_SCHEDULE_SINGLETON_REQUIRED'
              USING ERRCODE='55000';
          END IF;

          FOR obsolete IN
            SELECT * FROM public.dts_dirty_keys
            WHERE source_region='dom'
              AND key_type='TEACHER_TIME_RECHECK'
              AND key_part_2<to_char(business_date,'YYYY-MM-DD')
              AND status<>'COMPLETED'
              AND (status<>'PROCESSING'
                   OR lease_expires_at<=transaction_timestamp())
            ORDER BY key_part_2,key_part_1
            FOR UPDATE
          LOOP
            DELETE FROM public.dts_dirty_key_dependencies
            WHERE source_region=obsolete.source_region
              AND key_type=obsolete.key_type
              AND key_part_1=obsolete.key_part_1
              AND key_part_2=obsolete.key_part_2;
            UPDATE public.dts_dirty_keys
            SET status='COMPLETED',attempt_count=0,last_error_code=NULL,
                next_attempt_at=NULL,blocked_by=NULL,
                completed_work_revision=required_work_revision,
                claimed_through_work_revision=NULL,
                lease_owner_kind=NULL,lease_owner=NULL,lease_token=NULL,
                claimed_at=NULL,lease_expires_at=NULL,claimed_by=NULL,
                row_version=row_version+1,last_seen_at=clock_timestamp(),
                updated_at=clock_timestamp()
            WHERE source_region=obsolete.source_region
              AND key_type=obsolete.key_type
              AND key_part_1=obsolete.key_part_1
              AND key_part_2=obsolete.key_part_2;
            audit_detail := jsonb_build_object(
              'current_business_date_beijing',business_date,
              'prior_status',obsolete.status,
              'required_work_revision',obsolete.required_work_revision,
              'completed_work_revision',obsolete.completed_work_revision
            );
            INSERT INTO public.dts_teacher_time_recheck_audits(
              teacher_id,business_date_beijing,event_type,detail,
              detail_sha256
            ) VALUES (
              obsolete.key_part_1,obsolete.key_part_2::date,
              'SUPERSEDED_BY_CURRENT_DATE',audit_detail,
              public.dts_canonical_json_sha256_v1(audit_detail)
            );
            superseded := superseded+1;
          END LOOP;

          IF schedule.last_enqueued_business_date IS DISTINCT FROM
               business_date THEN
            FOR teacher IN
              SELECT tchr_id FROM public.teacher_source_wide
              WHERE v2_row_version IS NOT NULL
              ORDER BY convert_to(tchr_id,'UTF8')
            LOOP
              outcome := public._enqueue_teacher_time_recheck_key_v2(
                teacher.tchr_id,business_date
              );
              IF outcome->>'status'='ENQUEUED' THEN
                enqueued := enqueued+1;
              ELSIF outcome->>'status' NOT IN ('NOOP','NOOP_OLDER') THEN
                RAISE EXCEPTION 'DTS_V2_TIME_RECHECK_ENQUEUE_RESULT_INVALID'
                  USING ERRCODE='55000';
              END IF;
            END LOOP;
            UPDATE public.dts_teacher_time_recheck_schedule
            SET last_enqueued_business_date=business_date,
                last_enqueued_generation=generation,
                last_enqueued_at=transaction_timestamp(),
                row_version=row_version+1
            WHERE schedule_id='PRIMARY';
          END IF;
          RETURN jsonb_build_object(
            'enqueued',enqueued,'superseded',superseded,
            'schedule_due',false
          );
        END
        $$;
        REVOKE ALL ON FUNCTION
          public.enqueue_due_teacher_time_rechecks_v2() FROM PUBLIC;

        CREATE FUNCTION public.enqueue_teacher_time_recheck_after_wide_v2()
        RETURNS trigger
        LANGUAGE plpgsql
        SECURITY DEFINER
        SET search_path=pg_catalog,public
        AS $$
        DECLARE generation bigint;
        DECLARE local_now timestamp;
        BEGIN
          IF NEW.v2_row_version IS NULL THEN
            RETURN NEW;
          END IF;
          generation := public.dts_v2_runtime_primary_guard_v1('OUTBOX');
          IF generation IS NULL THEN
            RETURN NEW;
          END IF;
          local_now := transaction_timestamp()
            AT TIME ZONE 'Asia/Shanghai';
          IF local_now::time>=time '00:05:00' THEN
            PERFORM public._enqueue_teacher_time_recheck_key_v2(
              NEW.tchr_id,local_now::date
            );
          END IF;
          RETURN NEW;
        END
        $$;
        REVOKE ALL ON FUNCTION
          public.enqueue_teacher_time_recheck_after_wide_v2() FROM PUBLIC;

        CREATE TRIGGER trg_enqueue_teacher_time_recheck_after_wide_v2
        AFTER INSERT OR UPDATE OF v2_row_version
        ON public.teacher_source_wide
        FOR EACH ROW
        WHEN (NEW.v2_row_version IS NOT NULL)
        EXECUTE FUNCTION
          public.enqueue_teacher_time_recheck_after_wide_v2();

CREATE FUNCTION public.claim_teacher_time_rechecks_v2(
          p_worker_id text,p_batch_size integer,p_lease_seconds integer
        ) RETURNS TABLE(
          teacher_id text,business_date_beijing date,lease_token text,
          claimed_work_revision bigint,row_version bigint
        )
        LANGUAGE plpgsql
        SECURITY DEFINER
        SET search_path=pg_catalog,public
        AS $$
        DECLARE generation bigint;
        DECLARE business_date date;
        DECLARE candidate record;
        DECLARE new_token text;
        BEGIN
          IF p_worker_id IS NULL OR btrim(p_worker_id)=''
             OR p_batch_size NOT BETWEEN 1 AND 1000
             OR p_lease_seconds NOT BETWEEN 15 AND 300 THEN
            RAISE EXCEPTION 'DTS_V2_TIME_RECHECK_CLAIM_INVALID'
              USING ERRCODE='22023';
          END IF;
          generation := public.dts_v2_runtime_primary_guard_v1('OUTBOX');
          IF generation IS NULL THEN RETURN; END IF;
          business_date := (
            transaction_timestamp() AT TIME ZONE 'Asia/Shanghai'
          )::date;
          FOR candidate IN
            SELECT dirty.source_region,dirty.key_type,dirty.key_part_1,
                   dirty.key_part_2
            FROM public.dts_dirty_keys dirty
            WHERE dirty.source_region='dom'
              AND dirty.key_type='TEACHER_TIME_RECHECK'
              AND dirty.key_part_2=to_char(business_date,'YYYY-MM-DD')
              AND dirty.status IN ('PENDING','RETRY')
              AND dirty.next_attempt_at<=transaction_timestamp()
            ORDER BY dirty.next_attempt_at,dirty.updated_at,
                     convert_to(dirty.key_part_1,'UTF8')
            FOR UPDATE SKIP LOCKED LIMIT p_batch_size
          LOOP
            new_token := gen_random_uuid()::text;
            UPDATE public.dts_dirty_keys dirty
            SET status='PROCESSING',
                claimed_through_work_revision=required_work_revision,
                lease_owner_kind='SOURCEWIDE_TIME_RECHECK',
                lease_owner=p_worker_id,lease_token=new_token,
                claimed_at=transaction_timestamp(),
                lease_expires_at=transaction_timestamp()
                  +make_interval(secs=>p_lease_seconds),
                next_attempt_at=NULL,row_version=dirty.row_version+1,
                updated_at=clock_timestamp()
            WHERE dirty.source_region=candidate.source_region
              AND dirty.key_type=candidate.key_type
              AND dirty.key_part_1=candidate.key_part_1
              AND dirty.key_part_2=candidate.key_part_2
            RETURNING dirty.key_part_1,dirty.key_part_2::date,
              dirty.lease_token,dirty.claimed_through_work_revision,
              dirty.row_version
            INTO teacher_id,business_date_beijing,lease_token,
              claimed_work_revision,row_version;
            RETURN NEXT;
          END LOOP;
        END
        $$;

        CREATE FUNCTION public.complete_teacher_time_recheck_v2(
          p_teacher_id text,p_business_date date,p_lease_token text,
          p_claimed_work_revision bigint,p_expected_row_version bigint
        ) RETURNS jsonb
        LANGUAGE plpgsql
        SECURITY DEFINER
        SET search_path=pg_catalog,public
        AS $$
        DECLARE generation bigint;
        BEGIN
          generation := public.dts_v2_runtime_primary_guard_v1('OUTBOX');
          IF generation IS NULL THEN
            RAISE EXCEPTION 'DTS_V2_TIME_RECHECK_PRIMARY_REQUIRED'
              USING ERRCODE='55000';
          END IF;
          IF NOT EXISTS (
            SELECT 1 FROM public.dts_teacher_time_recheck_results result
            WHERE result.teacher_id=p_teacher_id
              AND result.business_date_beijing=p_business_date
              AND result.claimed_work_revision=p_claimed_work_revision
              AND result.projection_generation=generation
          ) THEN
            RAISE EXCEPTION 'DTS_V2_TIME_RECHECK_RESULT_REQUIRED'
              USING ERRCODE='23503';
          END IF;
          RETURN public._complete_dts_dirty_key_v2(
            'SOURCEWIDE_TIME_RECHECK','dom','TEACHER_TIME_RECHECK',
            p_teacher_id,to_char(p_business_date,'YYYY-MM-DD'),p_lease_token,
            p_claimed_work_revision,p_expected_row_version
          );
        END
        $$;

        CREATE FUNCTION public.fail_teacher_time_recheck_v2(
          p_teacher_id text,p_business_date date,p_lease_token text,
          p_claimed_work_revision bigint,p_expected_row_version bigint,
          p_error_code text
        ) RETURNS jsonb
        LANGUAGE plpgsql
        SECURITY DEFINER
        SET search_path=pg_catalog,public
        AS $$
        DECLARE generation bigint;
        BEGIN
          generation := public.dts_v2_runtime_primary_guard_v1('OUTBOX');
          IF generation IS NULL THEN
            RAISE EXCEPTION 'DTS_V2_TIME_RECHECK_PRIMARY_REQUIRED'
              USING ERRCODE='55000';
          END IF;
          RETURN public._fail_dts_dirty_key_v2(
            'SOURCEWIDE_TIME_RECHECK','dom','TEACHER_TIME_RECHECK',
            p_teacher_id,to_char(p_business_date,'YYYY-MM-DD'),p_lease_token,
            p_claimed_work_revision,p_expected_row_version,p_error_code
          );
        END
        $$;

        CREATE FUNCTION public.reap_expired_teacher_time_rechecks_v2(
          p_batch_size integer
        ) RETURNS integer
        LANGUAGE plpgsql
        SECURITY DEFINER
        SET search_path=pg_catalog,public
        AS $$
        DECLARE generation bigint;
        DECLARE business_date date;
        DECLARE dirty public.dts_dirty_keys%ROWTYPE;
        DECLARE next_attempt integer;
        DECLARE reaped integer := 0;
        DECLARE audit_detail jsonb;
        BEGIN
          IF p_batch_size NOT BETWEEN 1 AND 1000 THEN
            RAISE EXCEPTION 'DTS_V2_TIME_RECHECK_REAP_INVALID'
              USING ERRCODE='22023';
          END IF;
          generation := public.dts_v2_runtime_primary_guard_v1('OUTBOX');
          IF generation IS NULL THEN RETURN 0; END IF;
          business_date := (
            transaction_timestamp() AT TIME ZONE 'Asia/Shanghai'
          )::date;
          FOR dirty IN
            SELECT * FROM public.dts_dirty_keys
            WHERE source_region='dom'
              AND key_type='TEACHER_TIME_RECHECK'
              AND status='PROCESSING'
              AND lease_owner_kind='SOURCEWIDE_TIME_RECHECK'
              AND lease_expires_at<=transaction_timestamp()
            ORDER BY lease_expires_at,key_part_2,key_part_1
            FOR UPDATE SKIP LOCKED LIMIT p_batch_size
          LOOP
            IF dirty.key_part_2<to_char(business_date,'YYYY-MM-DD') THEN
              UPDATE public.dts_dirty_keys
              SET status='COMPLETED',attempt_count=0,last_error_code=NULL,
                  next_attempt_at=NULL,blocked_by=NULL,
                  completed_work_revision=required_work_revision,
                  claimed_through_work_revision=NULL,
                  lease_owner_kind=NULL,lease_owner=NULL,lease_token=NULL,
                  claimed_at=NULL,lease_expires_at=NULL,claimed_by=NULL,
                  row_version=row_version+1,updated_at=clock_timestamp()
              WHERE source_region=dirty.source_region
                AND key_type=dirty.key_type
                AND key_part_1=dirty.key_part_1
                AND key_part_2=dirty.key_part_2;
              audit_detail := jsonb_build_object(
                'current_business_date_beijing',business_date,
                'prior_status',dirty.status,
                'required_work_revision',dirty.required_work_revision,
                'completed_work_revision',dirty.completed_work_revision
              );
              INSERT INTO public.dts_teacher_time_recheck_audits(
                teacher_id,business_date_beijing,event_type,detail,
                detail_sha256
              ) VALUES (
                dirty.key_part_1,dirty.key_part_2::date,
                'SUPERSEDED_BY_CURRENT_DATE',audit_detail,
                public.dts_canonical_json_sha256_v1(audit_detail)
              );
            ELSIF dirty.required_work_revision>
                    dirty.claimed_through_work_revision THEN
              UPDATE public.dts_dirty_keys
              SET status='PENDING',attempt_count=0,last_error_code=NULL,
                  next_attempt_at=transaction_timestamp(),blocked_by=NULL,
                  claimed_through_work_revision=NULL,
                  lease_owner_kind=NULL,lease_owner=NULL,lease_token=NULL,
                  claimed_at=NULL,lease_expires_at=NULL,claimed_by=NULL,
                  row_version=row_version+1,updated_at=clock_timestamp()
              WHERE source_region=dirty.source_region
                AND key_type=dirty.key_type
                AND key_part_1=dirty.key_part_1
                AND key_part_2=dirty.key_part_2;
            ELSE
              next_attempt := dirty.attempt_count+1;
              UPDATE public.dts_dirty_keys
              SET status=CASE WHEN next_attempt=8 THEN 'DEAD'
                              ELSE 'RETRY' END,
                  attempt_count=next_attempt,
                  dead_generation=dead_generation
                    +CASE WHEN next_attempt=8 THEN 1 ELSE 0 END,
                  last_error_code='DIRTY_LEASE_EXPIRED',blocked_by=NULL,
                  next_attempt_at=CASE WHEN next_attempt=8 THEN NULL
                    ELSE transaction_timestamp()+least(
                      interval '30 minutes',
                      interval '5 seconds'*power(2,next_attempt-1)
                    ) END,
                  claimed_through_work_revision=NULL,
                  lease_owner_kind=NULL,lease_owner=NULL,lease_token=NULL,
                  claimed_at=NULL,lease_expires_at=NULL,claimed_by=NULL,
                  row_version=row_version+1,updated_at=clock_timestamp()
              WHERE source_region=dirty.source_region
                AND key_type=dirty.key_type
                AND key_part_1=dirty.key_part_1
                AND key_part_2=dirty.key_part_2;
              IF next_attempt=8 THEN
                INSERT INTO public.dts_dirty_key_state_audits(
                  source_region,key_type,key_part_1,key_part_2,event_type,
                  work_generation,dead_generation,detail
                ) VALUES (
                  dirty.source_region,dirty.key_type,dirty.key_part_1,
                  dirty.key_part_2,'DEAD',dirty.work_generation,
                  dirty.dead_generation+1,
                  jsonb_build_object('error_code','DIRTY_LEASE_EXPIRED')
                );
              END IF;
            END IF;
            reaped := reaped+1;
          END LOOP;
          RETURN reaped;
        END
        $$;

        REVOKE ALL ON FUNCTION
          public.claim_teacher_time_rechecks_v2(text,integer,integer),
          public.complete_teacher_time_recheck_v2(
            text,date,text,bigint,bigint
          ),
          public.fail_teacher_time_recheck_v2(
            text,date,text,bigint,bigint,text
          ),
          public.reap_expired_teacher_time_rechecks_v2(integer)
        FROM PUBLIC;

CREATE FUNCTION public.materialize_teacher_time_recheck_v2(
          p_payload jsonb,p_dom_revision bigint,p_ovs_revision bigint,
          p_projection_generation bigint,p_event_id text,
          p_claimed_work_revision bigint
        ) RETURNS jsonb
        LANGUAGE plpgsql
        SECURITY DEFINER
        SET search_path=pg_catalog,public
        AS $$
        DECLARE actor_name text := COALESCE(
          NULLIF(current_setting('role',true),'none'),session_user
        );
        DECLARE generation bigint;
        DECLARE local_now timestamp;
        DECLARE business_date date;
        DECLARE wide public.teacher_source_wide%ROWTYPE;
        DECLARE existing_result
          public.dts_teacher_time_recheck_results%ROWTYPE;
        DECLARE latest_result_date date;
        DECLARE aggregate_count integer;
        DECLARE expected_job_days integer;
        DECLARE expected_job_month double precision;
        DECLARE expected_online_status text;
        DECLARE expected_online_evidence text;
        DECLARE plan_document jsonb;
        DECLARE plan_sha256 text;
        DECLARE wide_changes integer := 0;
        DECLARE teacher_changes integer := 0;
        DECLARE result_changes integer := 0;
        BEGIN
          IF actor_name<>'tit_growth_app'
             OR jsonb_typeof(p_payload)<>'object'
             OR (SELECT array_agg(key ORDER BY key)
                 FROM jsonb_object_keys(p_payload) keys(key))
                  IS DISTINCT FROM ARRAY[
                    'business_date_beijing','regional_state_sha256',
                    'teacher_id','teacher_id_type','time_values','v'
                  ]::text[]
             OR p_payload->>'v'<>'1'
             OR p_payload->>'teacher_id' IS NULL
             OR btrim(p_payload->>'teacher_id')=''
             OR length(p_payload->>'teacher_id')>64
             OR p_payload->>'teacher_id_type' NOT IN ('NUMERIC','TEXT')
             OR jsonb_typeof(p_payload->'regional_state_sha256')<>'object'
             OR p_payload->'regional_state_sha256'<>
                  jsonb_build_object(
                    'dom',p_payload#>'{regional_state_sha256,dom}',
                    'ovs',p_payload#>'{regional_state_sha256,ovs}'
                  )
             OR p_payload#>>'{regional_state_sha256,dom}'
                  !~ '^[0-9a-f]{64}$'
             OR p_payload#>>'{regional_state_sha256,ovs}'
                  !~ '^[0-9a-f]{64}$'
             OR jsonb_typeof(p_payload->'time_values')<>'object'
             OR (SELECT array_agg(key ORDER BY key)
                 FROM jsonb_object_keys(p_payload->'time_values') keys(key))
                  IS DISTINCT FROM ARRAY[
                    'job_days','job_month','online_status',
                    'online_status_evidence_status'
                  ]::text[]
             OR jsonb_typeof(p_payload#>'{time_values,job_days}')
                  NOT IN ('number','null')
             OR jsonb_typeof(p_payload#>'{time_values,job_month}')
                  NOT IN ('number','null')
             OR jsonb_typeof(p_payload#>'{time_values,online_status}')
                  NOT IN ('string','null')
             OR jsonb_typeof(
                  p_payload#>'{time_values,online_status_evidence_status}'
                )<>'string'
             OR p_dom_revision<1 OR p_ovs_revision<1
             OR p_projection_generation<1 OR p_claimed_work_revision<1
             OR p_event_id IS NULL OR btrim(p_event_id)=''
             OR length(p_event_id)>512 THEN
            RAISE EXCEPTION 'DTS_V2_TEACHER_TIME_RECHECK_REQUEST_INVALID'
              USING ERRCODE='22023';
          END IF;
          BEGIN
            business_date := (p_payload->>'business_date_beijing')::date;
          EXCEPTION WHEN invalid_text_representation OR datetime_field_overflow
          THEN
            RAISE EXCEPTION 'DTS_V2_TEACHER_TIME_RECHECK_DATE_INVALID'
              USING ERRCODE='22023';
          END;
          IF to_char(business_date,'YYYY-MM-DD') IS DISTINCT FROM
               p_payload->>'business_date_beijing' THEN
            RAISE EXCEPTION 'DTS_V2_TEACHER_TIME_RECHECK_DATE_INVALID'
              USING ERRCODE='22023';
          END IF;

          generation := public.dts_v2_runtime_primary_guard_v1('TEACHER');
          IF generation IS NULL
             OR generation IS DISTINCT FROM p_projection_generation THEN
            RAISE EXCEPTION 'DTS_V2_TEACHER_TIME_RECHECK_PRIMARY_REQUIRED'
              USING ERRCODE='55000';
          END IF;
          local_now := transaction_timestamp()
            AT TIME ZONE 'Asia/Shanghai';
          IF business_date IS DISTINCT FROM local_now::date THEN
            RAISE EXCEPTION
              'DTS_V2_TEACHER_TIME_RECHECK_DATE_REGRESSION'
              USING ERRCODE='40001';
          END IF;

          SELECT max(result.business_date_beijing)
          INTO latest_result_date
          FROM public.dts_teacher_time_recheck_results result
          WHERE result.teacher_id=p_payload->>'teacher_id';
          IF latest_result_date>business_date THEN
            RAISE EXCEPTION
              'DTS_V2_TEACHER_TIME_RECHECK_DATE_REGRESSION'
              USING ERRCODE='40001';
          END IF;

          PERFORM 1 FROM public.domain_aggregate_revisions aggregate
          WHERE aggregate.aggregate_type='TEACHER'
            AND aggregate.canonical_key IN (
              jsonb_build_object(
                'source_region','dom','teacher_id',
                p_payload->>'teacher_id'
              ),
              jsonb_build_object(
                'source_region','ovs','teacher_id',
                p_payload->>'teacher_id'
              )
            )
            AND ((aggregate.canonical_key->>'source_region'='dom'
                  AND aggregate.revision=p_dom_revision
                  AND aggregate.aggregate_state_sha256=
                    p_payload#>>'{regional_state_sha256,dom}')
                 OR
                 (aggregate.canonical_key->>'source_region'='ovs'
                  AND aggregate.revision=p_ovs_revision
                  AND aggregate.aggregate_state_sha256=
                    p_payload#>>'{regional_state_sha256,ovs}'))
          ORDER BY aggregate.aggregate_id FOR SHARE;
          SELECT count(*) INTO aggregate_count
          FROM public.domain_aggregate_revisions aggregate
          WHERE aggregate.aggregate_type='TEACHER'
            AND aggregate.canonical_key IN (
              jsonb_build_object(
                'source_region','dom','teacher_id',
                p_payload->>'teacher_id'
              ),
              jsonb_build_object(
                'source_region','ovs','teacher_id',
                p_payload->>'teacher_id'
              )
            )
            AND ((aggregate.canonical_key->>'source_region'='dom'
                  AND aggregate.revision=p_dom_revision
                  AND aggregate.aggregate_state_sha256=
                    p_payload#>>'{regional_state_sha256,dom}')
                 OR
                 (aggregate.canonical_key->>'source_region'='ovs'
                  AND aggregate.revision=p_ovs_revision
                  AND aggregate.aggregate_state_sha256=
                    p_payload#>>'{regional_state_sha256,ovs}'));
          IF aggregate_count<>2 THEN
            RAISE EXCEPTION
              'DTS_V2_TEACHER_TIME_RECHECK_REGIONAL_VECTOR_STALE'
              USING ERRCODE='40001';
          END IF;

          SELECT * INTO wide FROM public.teacher_source_wide
          WHERE tchr_id=p_payload->>'teacher_id' FOR UPDATE;
          IF NOT FOUND OR wide.v2_row_version IS NULL
             OR wide.v2_dom_aggregate_revision IS DISTINCT FROM p_dom_revision
             OR wide.v2_ovs_aggregate_revision IS DISTINCT FROM p_ovs_revision
             OR wide.v2_projection_generation>p_projection_generation THEN
            RAISE EXCEPTION
              'DTS_V2_TEACHER_TIME_RECHECK_SERVING_VECTOR_STALE'
              USING ERRCODE='40001';
          END IF;

          expected_job_days := CASE
            WHEN wide.onboard_date IS NULL THEN NULL
            WHEN coalesce(wide.status_off_date,business_date)
                   <wide.onboard_date THEN NULL
            ELSE coalesce(wide.status_off_date,business_date)
                   -wide.onboard_date
          END;
          expected_job_month := CASE
            WHEN expected_job_days IS NULL THEN NULL
            ELSE floor(expected_job_days::numeric/30)+1
          END;
          expected_online_status := CASE
            WHEN lower(btrim(wide.status))='off' THEN 'LEFT'
            WHEN lower(btrim(wide.status))='hei' THEN 'BLOCKED'
            WHEN lower(btrim(wide.status))='on'
                 AND wide.status_on_date IS NOT NULL
                 AND business_date-wide.status_on_date BETWEEN 0 AND 29
              THEN 'NEW'
            WHEN lower(btrim(wide.status))='on'
                 AND wide.status_on_date IS NOT NULL
                 AND business_date-wide.status_on_date>=30
              THEN 'EXISTING'
            ELSE NULL
          END;
          expected_online_evidence := CASE
            WHEN expected_online_status IS NULL THEN 'SOURCE_MISSING'
            ELSE 'CONFIRMED'
          END;
          BEGIN
            IF (p_payload#>>'{time_values,job_days}')::integer
                  IS DISTINCT FROM expected_job_days
               OR (p_payload#>>'{time_values,job_month}')::double precision
                  IS DISTINCT FROM expected_job_month
               OR p_payload#>>'{time_values,online_status}'
                  IS DISTINCT FROM expected_online_status
               OR p_payload#>>'{time_values,online_status_evidence_status}'
                  IS DISTINCT FROM expected_online_evidence THEN
              RAISE EXCEPTION
                'DTS_V2_TEACHER_TIME_RECHECK_VALUES_MISMATCH'
                USING ERRCODE='23514';
            END IF;
          EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range
          THEN
            RAISE EXCEPTION
              'DTS_V2_TEACHER_TIME_RECHECK_VALUES_MISMATCH'
              USING ERRCODE='23514';
          END;

          plan_document := jsonb_build_object(
            'protocol','teacher-time-recheck-plan-v1','payload',p_payload,
            'dom_aggregate_revision',p_dom_revision,
            'ovs_aggregate_revision',p_ovs_revision,
            'projection_generation',p_projection_generation,
            'triggering_event_id',p_event_id,
            'claimed_work_revision',p_claimed_work_revision
          );
          plan_sha256 := public.dts_canonical_json_sha256_v1(plan_document);
          SELECT * INTO existing_result
          FROM public.dts_teacher_time_recheck_results
          WHERE teacher_id=p_payload->>'teacher_id'
            AND business_date_beijing=business_date
          FOR SHARE;
          IF FOUND THEN
            IF existing_result.plan_sha256<>plan_sha256 THEN
              RAISE EXCEPTION
                'DTS_V2_TEACHER_TIME_RECHECK_NONDETERMINISTIC'
                USING ERRCODE='23514';
            END IF;
            RETURN jsonb_build_object(
              'teacher_source_changes',0,
              'teacher_identity_changes',0,
              'time_recheck_result_changes',0
            );
          END IF;

          PERFORM set_config('tit.dts_v2_materializer','teacher',true);
          UPDATE public.teacher_source_wide
          SET job_days=expected_job_days,job_month=expected_job_month,
              v2_projection_generation=p_projection_generation,
              v2_materialized_event_id=p_event_id,
              v2_materialized_at=transaction_timestamp(),
              v2_row_version=v2_row_version+1
          WHERE tchr_id=p_payload->>'teacher_id'
            AND ROW(
              job_days,job_month,v2_projection_generation,
              v2_materialized_event_id
            ) IS DISTINCT FROM ROW(
              expected_job_days,expected_job_month,p_projection_generation,
              p_event_id
            );
          GET DIAGNOSTICS wide_changes=ROW_COUNT;

          UPDATE public.teachers
          SET camp_day=least(greatest(coalesce(expected_job_days,0),0),30),
              online_status=expected_online_status,
              payload=payload||jsonb_build_object(
                'teacher_time_recheck_v2',jsonb_build_object(
                  'business_date_beijing',business_date,
                  'online_status_evidence_status',expected_online_evidence,
                  'dom_aggregate_revision',p_dom_revision,
                  'ovs_aggregate_revision',p_ovs_revision,
                  'projection_generation',p_projection_generation,
                  'plan_sha256',plan_sha256
                )
              ),updated_at=transaction_timestamp()
          WHERE teacher_id=p_payload->>'teacher_id'
            AND ROW(
              camp_day,online_status,payload->'teacher_time_recheck_v2'
            ) IS DISTINCT FROM ROW(
              least(greatest(coalesce(expected_job_days,0),0),30),
              expected_online_status,
              jsonb_build_object(
                'business_date_beijing',business_date,
                'online_status_evidence_status',expected_online_evidence,
                'dom_aggregate_revision',p_dom_revision,
                'ovs_aggregate_revision',p_ovs_revision,
                'projection_generation',p_projection_generation,
                'plan_sha256',plan_sha256
              )
            );
          GET DIAGNOSTICS teacher_changes=ROW_COUNT;
          IF teacher_changes<>1 THEN
            RAISE EXCEPTION
              'DTS_V2_TEACHER_TIME_RECHECK_TEACHER_MISSING'
              USING ERRCODE='23503';
          END IF;

          INSERT INTO public.dts_teacher_time_recheck_results(
            teacher_id,business_date_beijing,teacher_id_type,
            dom_aggregate_revision,ovs_aggregate_revision,
            regional_state_sha256,projection_generation,
            triggering_event_id,claimed_work_revision,time_values,
            plan_sha256,materialized_at
          ) VALUES (
            p_payload->>'teacher_id',business_date,
            p_payload->>'teacher_id_type',p_dom_revision,p_ovs_revision,
            p_payload->'regional_state_sha256',p_projection_generation,
            p_event_id,p_claimed_work_revision,p_payload->'time_values',
            plan_sha256,transaction_timestamp()
          );
          GET DIAGNOSTICS result_changes=ROW_COUNT;
          RETURN jsonb_build_object(
            'teacher_source_changes',wide_changes,
            'teacher_identity_changes',teacher_changes,
            'time_recheck_result_changes',result_changes
          );
        END
        $$;
        REVOKE ALL ON FUNCTION
          public.materialize_teacher_time_recheck_v2(
            jsonb,bigint,bigint,bigint,text,bigint
          ) FROM PUBLIC;

        CREATE FUNCTION public.teacher_time_recheck_result_proof_v1(
          p_teacher_id text,p_business_date date
        ) RETURNS jsonb
        LANGUAGE sql
        STABLE
        SECURITY DEFINER
        SET search_path=pg_catalog,public
        AS $$
          SELECT jsonb_build_object(
            'teacher_id',result.teacher_id,
            'business_date_beijing',result.business_date_beijing,
            'dom_aggregate_revision',result.dom_aggregate_revision,
            'ovs_aggregate_revision',result.ovs_aggregate_revision,
            'regional_state_sha256',result.regional_state_sha256,
            'projection_generation',result.projection_generation,
            'triggering_event_id',result.triggering_event_id,
            'claimed_work_revision',result.claimed_work_revision,
            'time_values',result.time_values,
            'plan_sha256',result.plan_sha256
          )
          FROM public.dts_teacher_time_recheck_results result
          WHERE result.teacher_id=p_teacher_id
            AND result.business_date_beijing=p_business_date
        $$;
        REVOKE ALL ON FUNCTION
          public.teacher_time_recheck_result_proof_v1(text,date)
        FROM PUBLIC;

CREATE FUNCTION public.dts_v2_teacher_time_recheck_health_v1(
          p_stale_after_seconds bigint
        ) RETURNS jsonb
        LANGUAGE plpgsql
        STABLE
        SECURITY DEFINER
        SET search_path=pg_catalog,public
        AS $$
        DECLARE control_count integer;
        DECLARE control_mode text;
        DECLARE generation bigint;
        DECLARE local_now timestamp;
        DECLARE business_date date;
        DECLARE due boolean;
        DECLARE missing_count bigint := 0;
        DECLARE runnable bigint := 0;
        DECLARE active bigint := 0;
        DECLARE expired bigint := 0;
        DECLARE dead bigint := 0;
        DECLARE stale bigint := 0;
        DECLARE oldest bigint;
        BEGIN
          IF p_stale_after_seconds NOT BETWEEN 1 AND 86400 THEN
            RAISE EXCEPTION 'DTS_V2_TIME_RECHECK_HEALTH_THRESHOLD_INVALID'
              USING ERRCODE='22023';
          END IF;
          PERFORM pg_advisory_xact_lock_shared(
            hashtextextended('tit:dts-v2-cutover',0)
          );
          SELECT count(*) INTO control_count
          FROM public.dts_pipeline_control;
          SELECT mode,projection_generation INTO control_mode,generation
          FROM public.dts_pipeline_control WHERE control_id='PRIMARY';
          IF control_count<>1 OR control_mode NOT IN (
               'V1_COMPAT_DUAL_CAPTURE','V2_PRIMARY','ROLLED_BACK'
             ) OR generation IS NULL OR generation<0 THEN
            RAISE EXCEPTION 'DTS_V2_PIPELINE_CONTROL_STATE_INVALID'
              USING ERRCODE='55000';
          END IF;
          local_now := transaction_timestamp()
            AT TIME ZONE 'Asia/Shanghai';
          business_date := local_now::date;
          SELECT control_mode='V2_PRIMARY'
                 AND local_now::time>=time '00:05:00'
                 AND schedule.last_enqueued_business_date
                       IS DISTINCT FROM business_date
          INTO due
          FROM public.dts_teacher_time_recheck_schedule schedule
          WHERE schedule_id='PRIMARY';
          IF due IS NULL THEN
            RAISE EXCEPTION 'DTS_V2_TIME_RECHECK_SCHEDULE_SINGLETON_REQUIRED'
              USING ERRCODE='55000';
          END IF;
          IF control_mode='V2_PRIMARY'
             AND local_now::time>=time '00:05:00' THEN
            SELECT count(*) INTO missing_count
            FROM public.teacher_source_wide wide
            WHERE wide.v2_row_version IS NOT NULL
              AND NOT EXISTS (
                SELECT 1
                FROM public.dts_teacher_time_recheck_results result
                WHERE result.teacher_id=wide.tchr_id
                  AND result.business_date_beijing=business_date
              );
            SELECT
              count(*) FILTER (
                WHERE status IN ('PENDING','RETRY')
                  AND next_attempt_at<=transaction_timestamp()
              ),
              count(*) FILTER (WHERE status='PROCESSING'),
              count(*) FILTER (
                WHERE status='PROCESSING'
                  AND lease_expires_at<=transaction_timestamp()
              ),
              count(*) FILTER (WHERE status='DEAD'),
              count(*) FILTER (
                WHERE status IN ('PENDING','RETRY')
                  AND next_attempt_at<=transaction_timestamp()
                  AND updated_at<=transaction_timestamp()
                    -make_interval(secs=>p_stale_after_seconds::integer)
              ),
              floor(extract(epoch FROM transaction_timestamp()
                    -min(updated_at) FILTER (
                      WHERE status IN ('PENDING','RETRY')
                        AND next_attempt_at<=transaction_timestamp()
                    )))::bigint
            INTO runnable,active,expired,dead,stale,oldest
            FROM public.dts_dirty_keys
            WHERE source_region='dom'
              AND key_type='TEACHER_TIME_RECHECK'
              AND key_part_2=to_char(business_date,'YYYY-MM-DD');
          END IF;
          RETURN jsonb_build_object(
            'protocol_version',
              'dts-v2-teacher-time-recheck-health-v1',
            'mode',control_mode,'projection_generation',generation,
            'schedule_due',due,
            'current_date_missing_count',coalesce(missing_count,0),
            'runnable_count',coalesce(runnable,0),
            'active_lease_count',coalesce(active,0),
            'expired_lease_count',coalesce(expired,0),
            'dead_count',coalesce(dead,0),
            'stale_runnable_count',coalesce(stale,0),
            'oldest_runnable_age_seconds',oldest
          );
        END
        $$;
        REVOKE ALL ON FUNCTION
          public.dts_v2_teacher_time_recheck_health_v1(bigint)
        FROM PUBLIC;

REVOKE ALL PRIVILEGES ON TABLE
          public.dts_teacher_time_recheck_schedule,
          public.dts_teacher_time_recheck_results,
          public.dts_teacher_time_recheck_audits
        FROM PUBLIC,tit_growth_app,tit_dts_ingest_runtime,
          tit_teacher_crud,tide_support_ticket_owner;

        -- The application rebuilds the date-derived plan from the same two
        -- immutable TEACHER aggregate states used by the regular Outbox
        -- processor.  Read-only access is therefore required; every write
        -- remains behind a SECURITY DEFINER command below.
        REVOKE ALL PRIVILEGES ON TABLE public.domain_aggregate_revisions
          FROM tit_growth_app;
        GRANT SELECT ON TABLE public.domain_aggregate_revisions
          TO tit_growth_app;

        GRANT EXECUTE ON FUNCTION
          public.enqueue_due_teacher_time_rechecks_v2(),
          public.claim_teacher_time_rechecks_v2(text,integer,integer),
          public.complete_teacher_time_recheck_v2(
            text,date,text,bigint,bigint
          ),
          public.fail_teacher_time_recheck_v2(
            text,date,text,bigint,bigint,text
          ),
          public.reap_expired_teacher_time_rechecks_v2(integer),
          public.materialize_teacher_time_recheck_v2(
            jsonb,bigint,bigint,bigint,text,bigint
          ),
          public.teacher_time_recheck_result_proof_v1(text,date),
          public.dts_v2_teacher_time_recheck_health_v1(bigint)
        TO tit_growth_app;

        REVOKE ALL ON FUNCTION
          public.enqueue_due_teacher_time_rechecks_v2(),
          public.claim_teacher_time_rechecks_v2(text,integer,integer),
          public.complete_teacher_time_recheck_v2(
            text,date,text,bigint,bigint
          ),
          public.fail_teacher_time_recheck_v2(
            text,date,text,bigint,bigint,text
          ),
          public.reap_expired_teacher_time_rechecks_v2(integer),
          public.materialize_teacher_time_recheck_v2(
            jsonb,bigint,bigint,bigint,text,bigint
          ),
          public.teacher_time_recheck_result_proof_v1(text,date),
          public.dts_v2_teacher_time_recheck_health_v1(bigint)
        FROM PUBLIC,tit_dts_ingest_runtime,
          tit_teacher_crud,tide_support_ticket_owner;

        DO $$
        BEGIN
          IF has_table_privilege(
               'tit_growth_app',
               'public.dts_teacher_time_recheck_results','SELECT'
             ) OR has_table_privilege(
               'tit_growth_app',
               'public.dts_teacher_time_recheck_results','INSERT'
             ) OR has_table_privilege(
               'tit_growth_app','public.dts_dirty_keys','UPDATE'
             ) OR NOT has_table_privilege(
               'tit_growth_app',
               'public.domain_aggregate_revisions','SELECT'
             ) OR has_table_privilege(
               'tit_growth_app',
               'public.domain_aggregate_revisions','UPDATE'
             ) OR NOT has_function_privilege(
               'tit_growth_app',
               'public.materialize_teacher_time_recheck_v2(jsonb,bigint,bigint,bigint,text,bigint)',
               'EXECUTE'
             ) THEN
            RAISE EXCEPTION 'DTS_V2_TEACHER_TIME_RECHECK_ACL_INVALID';
          END IF;
        END
        $$;

