-- Running upgrade 20260822_97_teacher_time_recheck -> 20260822_98_task_v2_refresh

DO $$
        BEGIN
          IF to_regrole('tit_growth_app') IS NULL
             OR to_regclass('public.dts_pipeline_control') IS NULL
             OR to_regclass('public.dts_dirty_keys') IS NULL
