CREATE TABLE public.dts_source_snapshot_desired_rows (
    snapshot_id VARCHAR(160) NOT NULL,
    source_region VARCHAR(8) NOT NULL,
    source_table VARCHAR(128) NOT NULL,
    scope_kind VARCHAR(16) NOT NULL,
    scope_level VARCHAR(16) NOT NULL,
    scope_key VARCHAR(160) NOT NULL,
    source_key VARCHAR(512) NOT NULL,
    source_key_data JSONB NOT NULL,
    source_key_type VARCHAR(16) NOT NULL,
    source_key_numeric NUMERIC,
    source_key_text TEXT,
    dependency_keys JSONB NOT NULL,
    protected_source_row JSONB NOT NULL,
    desired_row_hash VARCHAR(64) NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT pk_dts_source_snapshot_desired_rows PRIMARY KEY (snapshot_id, source_region, source_table, scope_kind, scope_level, scope_key, source_key),
    CONSTRAINT fk_dts_source_snapshot_desired_snapshot FOREIGN KEY(snapshot_id, source_region, source_table, scope_kind, scope_level, scope_key) REFERENCES public.dts_source_scope_snapshots (snapshot_id, source_region, source_table, scope_kind, scope_level, scope_key) ON DELETE RESTRICT,
    CONSTRAINT ck_dts_source_snapshot_desired_key CHECK (public.dts_source_key_parts_valid_v2(source_key,source_key_data,source_key_type,source_key_numeric,source_key_text)),
    CONSTRAINT ck_dts_source_snapshot_desired_dependencies CHECK (public.dts_dependency_keys_valid_v2(source_region,dependency_keys)),
    CONSTRAINT ck_dts_source_snapshot_desired_payload CHECK (jsonb_typeof(protected_source_row) = 'object' AND desired_row_hash ~ '^[0-9a-f]{64}$' AND desired_row_hash = public.dts_canonical_json_sha256_v1(protected_source_row) AND (source_region <> 'dom' OR public.dom_student_json_is_safe_v1(protected_source_row)))
);

